[38598] = { ["id"] = 38598, ["name"] = "TEST: Craft Some Legplates", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["storyline"] = { 38598 }, ["description"] = "The Highmountain tauren craft their legplates piece-by-piece, then assemble them all at the end. Seems pretty slow and unnecessarily arduous if you ask me, but we should start here before making any efficiency improvements. Here's some leystone. I've added the recipe into your workbook, as well. Let's give this a shot!", ["objectivesText"] = "Use your Blacksmithing skill to craft a pair of Handcrafted Leystone Legplates.", ["rewardXP"] = 1415, ["rewardItems"] = { 124006, 124007, 124008, 124009, 124010 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44482] = { ["id"] = 44482, ["name"] = "Recruiting Ebon Knights", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["mapID"] = 726, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["description"] = "Korgaz Deadaxe has been hard at work training a new generation of death knights. He has done an excellent job culling the ranks of weakness. Those who have survived the trials of death knight training are ready to join the ranks of the Ebon Blade. Korgaz is waiting for you on the upper level. I suggest you speak with him at your soonest convenience. New death knights will bolster our ranks and aid is in the war against the Burning Legion.", ["objectivesText"] = "Speak to Korgaz Deadaxe.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 11, ["flags"] = 1 } } },
[45397] = { ["id"] = 45397, ["name"] = "Fire the Cannons!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 7543, ["storyline"] = { 45397 }, ["description"] = "It will take more than a damn shipwreck to bring me down. Those overgrown, vomit-reeking, demon felbags have another thing coming if they think that's all it's gonna take to stop me. <Keeshan coughs up seawater, wiping his mouth dry with his sleeve.> Ughh... I may need a little breather though. Here, take this flare gun and use it to call down artillery strikes on the beach. Rain hell on those worthless, half-goat bastards and I'll rendezvous with you back at the base when the mission is complete!", ["objectivesText"] = "Slay 14 demons.", ["rewardItems"] = { 142390 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[47029] = { ["id"] = 47029, ["name"] = "Holy: A Threat in Val'sharah", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 47029 }, ["series"] = { 46078, 46079, 46080, 46082, 47003, 47004, 47005, 47006, 47027 }, ["description"] = "It appears you have grown strong enough to take on another Legion threat. If you could speak to Archmage Modera in Dalaran as soon as possible, the Council would be in your debt.", ["objectivesText"] = "Speak with Archmage Modera in Dalaran.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 142384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[54943] = { ["id"] = 54943, ["name"] = "The Dark Ranger's Pupil", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["mapID"] = 18, ["storyline"] = { 54943 }, ["description"] = "Thank the abyss you're here, Huntmaster <name>! I'm concerned about Dark Ranger Velonara. We have become good friends during our time together in the Trueshot Lodge, and I fear she is in peril. She's been training an apprentice dark ranger, a lad named Prelus. Newly raised, she said. At any rate, Prelus ran off after receiving a letter from his brother, and now Velonara has gone to Tirisfal Glades to find him. I have a bad feeling about all this. Could you check on her safety?", ["objectivesText"] = "Find Dark Ranger Velonara in Tirisfal Glades.", ["rewardGold"] = 77400, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 884, ["name"] = "Memento of the Dark Rangers", ["orderIndex"] = 0, ["flags"] = 0 } } },
[59969] = { ["id"] = 59969, ["name"] = "A Shaman's Duty", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 10424, ["storyline"] = { 59969 }, ["description"] = "Greetings, young one. Your compatriots cannot see me. Only you, for you have been trained in the ways of a shaman. The necrotic energies of this island have ensnared my pack. I need your aid to free them. Gather veil blossoms from surrounding area. Burn them on the campfire and breath deep of their smoke. Then you will be able to see my packmates and release them from their bonds.", ["objectivesText"] = "Gather 4 ghost blossoms to burn on the campfire in order to rescue the ghost wolf 's companions.", ["rewardGold"] = 4000, ["rewardXP"] = 250, ["rewardItems"] = { 174947, 174968 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10424 } }, ["questType"] = "standard" },
[62394] = { ["id"] = 62394, ["name"] = "House In Decline", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["storyline"] = { 62394 }, ["description"] = "Our forces are gathering. Soon it will be time to move against the House of Rituals. See what you can do to continue strengthening our position.", ["objectivesText"] = "Increase your renown.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[64159] = { ["id"] = 64159, ["name"] = "Repatriate Rare Supplies", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["storyline"] = { 64159 }, ["description"] = "The rebels have stolen supplies from surrounding camps. You have proven yourself adept at correcting such situations. I trust you can aid us in resolving this situation.", ["objectivesText"] = "Recover supplies from the makeshift camps across the river.", ["rewardGold"] = 309800, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[64162] = { ["id"] = 64162, ["name"] = "Ritual Rival", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["storyline"] = { 64162 }, ["description"] = "Yet another rival Kahn has risen out of the rebel tribes. I'd take care of then myself, but I'm busy overseeing things here. I trust you can teach them the error of their ways?", ["objectivesText"] = "Find and defeat the Rebel Kahn in the makeshift camps across the river.", ["rewardGold"] = 309800, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[64163] = { ["id"] = 64163, ["name"] = "Revenge Against Renegades", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["storyline"] = { 64163 }, ["description"] = "Rebel clans have laid claims to some of our camps across the river. Such rebellious rabble need dealing with. I trust that you are capable of teaching these rebels a lesson on my behalf? The camps are an untidy mess as well, so just ignore the chaos for now. We can resolve that later once order is restored.", ["objectivesText"] = "Find and defeat Rebel Centaur Warriors in the makeshift camps across the river.", ["rewardGold"] = 309800, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
