[65869] = { ["id"] = 65869, ["name"] = "Another Ambush", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "A tragedy. And potentially the first of many more. Find out what Akiun knows, then examine anyone who fell in the attack. I have my hunches about what happened here. Let's see if the clues support my theory. Meanwhile, I'll try to reassure my rattled friends.", ["objectivesText"] = "Speak to Akiun and examine 4 nearby corpses. Progress: We must pinpoint the source of this gnoll aggression, before they can do any more damage.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191107, 191111, 191118, 192189, 192190 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187721, ["x"] = 0.286, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189708, ["x"] = 0.288, ["y"] = 0.346 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.286, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1317, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1317, ["name"] = "Tuskarr Troubles", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 26, ["flags"] = 0 } } },
