[65872] = { ["id"] = 65872, ["name"] = "Ill Gnolls with Ill Intent", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "I'm catching a strange scent on the wind. Something here isn't right... Hanu described the gnolls in this cave as strange... and sickly. We should learn more about what is causing this. Don't let your guard down. Despite their sickly appearance, expect them to be just as devious and dangerous.", ["objectivesText"] = "Kill 16 Shadepaw gnolls in Kargpaw's Den.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191107, 191111, 191118, 192189, 192190 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186228, ["x"] = 0.344, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186228, ["x"] = 0.344, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1317, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1317, ["name"] = "Tuskarr Troubles", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 23, ["flags"] = 0 } } },
[65873] = { ["id"] = 65873, ["name"] = "Leader of the Shadepaw Pack", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "Kargpaw is the true leader of the gnolls in this part of the forest. We've had... unpleasant encounters with him in the past. This time was different. He carried a strange totem that seemed to twist his very essence. Kargpaw must be stopped and this totem recovered. I fear the gnolls are meddling in something darker than we can imagine.", ["objectivesText"] = "Kill Kargpaw and recover his totem. Progress: Did you recover Kargpaw's totem ?", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 191107, 191111, 191118, 192189, 192190, 198004, 198006 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186228, ["x"] = 0.344, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186228, ["x"] = 0.344, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1317, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1317, ["name"] = "Tuskarr Troubles", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 24, ["flags"] = 0 } } },
[65874] = { ["id"] = 65874, ["name"] = "A Rotten Revelation", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["storyline"] = { 65874 }, ["description"] = "Hmm... <Brel peers intently at the strange totem, turning it over in her thick hands.> We've got to put our whiskers together and determine what this means.", ["objectivesText"] = "Speak with Hanu, Elder Poa, and Norukk.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[65875] = { ["id"] = 65875, ["name"] = "A Dragon's Day Off", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65875 }, ["description"] = "A lifetime spent in Outland... always fighting. So little time to relax! Sometimes a dragon just needs a day off by the sea with a cold, cold drink in their claws. Hey, maybe you can help me relax! Do me a favor and see if you can find a few of these drinks to refresh our supply here.", ["objectivesText"] = "Locate the various drinks for Vazallia . Progress: Have fetched my beverages yet? No? That's too bad.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 109076, 191251, 191255, 191264, 192786, 193201, 195543, 197737, 197738, 197739, 197744, 198043, 198044, 198045, 198047, 198356, 198622, 199215, 201817, 201818, 201838, 202173 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192662, ["x"] = 0.202, ["y"] = 0.395 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192662, ["x"] = 0.202, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.202, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[65886] = { ["id"] = 65886, ["name"] = "To Rhonin's Shield", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "Raszageth and the Primalists are launching an all out assault on Vakthros. We cannot let her succeed! Khadgar and I will go ahead to handle the situation there from the sky. In the meantime, make your way to the Rhonin's Shield, one of the last Kirin Tor camps in the area. You may be able to get there faster by riding that drake of yours from the top of the archives. See that the Kirin Tor there are all right, then make your way to Vakthros. We'll be counting on your help from the ground.", ["objectivesText"] = "Meet with Drok Scrollstabber in the Tower Outlook.", ["rewardGold"] = 70225, ["rewardXP"] = 1030, ["rewardItems"] = { 192478, 192479, 194705 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186280, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189751, ["x"] = 0.658, ["y"] = 0.254 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1315, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1315, ["name"] = "Vakthros", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 39, ["flags"] = 0 } } },
[65887] = { ["id"] = 65887, ["name"] = "To the Mountain", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "It's a sight to behold up there, Khadgar and Kalecgos fighting the Primalists in the sky! They've summoned several mirror images of themselves to help you through the monstrous hole the Primalists have created. One pair is at the base of the mountains right now. If things start to look bad... well I'll get the word out to the rest of us in the Azure Span .", ["objectivesText"] = "Meet Khadgar and Kalecgos 's mirror images at the base of Vakthros Range.", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["rewardItems"] = { 21100, 21746, 54885, 54886, 54887, 54888, 60688, 60689, 60690, 60691, 63701, 63702, 63703, 63704, 63705, 63706, 63707, 63708, 94290, 123975, 131517, 192478, 192479, 194705, 211279, 237812, 245333 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189751, ["x"] = 0.658, ["y"] = 0.254 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186304, ["x"] = 0.7, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.254 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1315, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1315, ["name"] = "Vakthros", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 40, ["flags"] = 0 } } },
[65890] = { ["id"] = 65890, ["name"] = "The Nelthazan Ruins", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65890 }, ["series"] = { 65891, 70337 }, ["description"] = "The Dragonscale Expedition requires your assistance. A skyscribe was sent to the ruins to gather information. They should be uninhabited, but I can hear his shouting from over here. He must be in dire circumstances for it to be audible at this distance. On this expedition, we take care of our own. Even the insufferable ones. Seek him out and protect him from whatever danger he has found.", ["objectivesText"] = "Meet Skyscribe Adenedal at the Nelthazan Ruins.", ["rewardGold"] = 16980, ["rewardXP"] = 345, ["rewardItems"] = { 193355, 193357, 193375, 193601, 197407, 198078, 198079 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190089, ["x"] = 0.66, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186300, ["x"] = 0.63, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65891] = { ["id"] = 65891, ["name"] = "Tools of the Tirade", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65891 }, ["series"] = { 65890, 70337 }, ["description"] = "Good. I was just thinking that I am in need of an adventurer like you. Strong. Sturdy. Willing to work for a trivial sum. It is as if I willed you into existence. Well done, me. These ruins seem to have brought the attention of others. We cannot rely on them to excavate it properly. They will taint the samples! Take this. Deploy it around artifacts of interest around the ruins. It is enchanted to perform any necessary duty.", ["objectivesText"] = "Deploy the enchanted tools to 5 piles of rubble. Progress: I think I shall write a bit of poetry. Or, rather, instruct the book to write it for me.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193355, 193357, 193375, 193601, 193858, 197407, 198078, 198079 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186300, ["x"] = 0.63, ["y"] = 0.172 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186300, ["x"] = 0.63, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65892] = { ["id"] = 65892, ["name"] = "The Sundered Asunder", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65892 }, ["objectivesText"] = "Disrupt the Reclaimers", ["rewardGold"] = 842700, ["rewardXP"] = 4150, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13645 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Disrupt the Reclaimers", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[65893] = { ["id"] = 65893, ["name"] = "The Relic Inquiry", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65893 }, ["description"] = "The Sundered Flame are here. Would you trust anyone claiming to be sundered with precious artifacts? I did not think so. Regardless, we need to know what they are here for if we are to proceed. Gather what you can recover from them and report back to me with your findings. There are more pieces to this puzzle than what we will find in the ground.", ["objectivesText"] = "Gather 60 Nelthazan Artifact Fragments . Progress: These ruins are ruined enough.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 193355, 193357, 193375, 193601, 197407, 198078, 198079 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186300, ["x"] = 0.63, ["y"] = 0.172 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186300, ["x"] = 0.63, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65895] = { ["id"] = 65895, ["name"] = "Competing Company", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65895 }, ["description"] = "Bah! We will learn nothing from the slaughter of laborers. Seek out their leaders. One of them will know what we need. Oh, and <name>. Listen to them before you kill them this time. You may learn something useful.", ["objectivesText"] = "Gather information about the Sundered Flame. Progress: What have you learned?", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 193355, 193357, 193375, 193601, 197407, 198078, 198079 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186300, ["x"] = 0.63, ["y"] = 0.172 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186300, ["x"] = 0.63, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65896] = { ["id"] = 65896, ["name"] = "Let the Healing Begin", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 65896 }, ["description"] = "Do you think you would be able to step into this city without me noticing? No! I was right about your kind before and I'll be damned before I let dragons destroy my home again. This once was a park filled with joy and peace. Then your progenitor, Deathwing, came. Oh yes, I know all about him. See for yourself the legacy of destruction that was left behind. The pain that walks these streets still.", ["objectivesText"] = "Help the people of Stormwind heal.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 190830, ["x"] = 0.444333, ["y"] = 0.594333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 194554, ["x"] = 0.4312, ["y"] = 0.6612 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.444333, ["y"] = 0.594333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[65898] = { ["id"] = 65898, ["name"] = "Proto Problems", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65898 }, ["description"] = "I hold no love for the Sundered Flame, but even I cannot stand idle while they rip themselves apart like this. It is all too familiar. Whatever this Locus is, it is safer in our hands than in their clutches. Follow the trail of bodies and I suspect we will find it. Do be careful, $p. I worry we will find that the nest is not quite as abandoned as it appears.", ["objectivesText"] = "Acquire the Locus and defeat the protodrake that protects it. Progress: I am glad you made it out safely. Do you have the Locus?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 193355, 193357, 193375, 193376, 193601, 197407, 198078, 198079, 198351 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186300, ["x"] = 0.63, ["y"] = 0.172 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 191154, ["x"] = 0.662, ["y"] = 0.242 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65899] = { ["id"] = 65899, ["name"] = "Find Theramus", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65899 }, ["description"] = "<race>! Are you here to visit the beautiful Lilac Ramble? I'm so sorry about its current state. I promise it's not usually this untended! Theramus, the garden's keeper, was supposed to meet us today and tackle the issues together. He's been struggling with the upkeep lately, so Felina and I are helping out. But we can't do it all. Would you help us look around for him? Maybe he did forget.", ["objectivesText"] = "Search the nearby caves and find Theramus.", ["rewardGold"] = 38050, ["rewardXP"] = 2765, ["rewardItems"] = { 191083, 191084, 191085, 191086, 191134, 191568, 201874 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186303, ["x"] = 0.247, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186303, ["x"] = 0.247, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.247, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65900] = { ["id"] = 65900, ["name"] = "Suspiciously Spiced Steak", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65900 }, ["description"] = "My sister's idea is charming, but Theramus needs a real pick-me-up. That would be a generous serving of sourbloom . We can make it into a paste to slather onto his favorite food: turtle meat! Will you help me collect the ingredients?", ["objectivesText"] = "Collect 2 Perfectly Tender Turtle Meat , 6 Reptilian Eggshells , and 15 Sourbloom . Progress: Do you know why sourbloom grow under the coastal trees? The tree roots trap an abundance of nutrients from the waves, which then feed the sourbloom . This gives them incredible nutritious value.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191083, 191084, 191085, 191086, 191134, 191568, 201874 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185726, ["x"] = 0.246, ["y"] = 0.632571 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185726, ["x"] = 0.246, ["y"] = 0.632571 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.246, ["y"] = 0.632571 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65901] = { ["id"] = 65901, ["name"] = "Sneaking Out", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65901 }, ["description"] = "I'm grounded indefinitely! Doesn't my Ohn know I'm turning sixteen next spring? I should be able to leave when I want to. You look like you could help me out. I do have an escape plan: by channeling these totems, I'll concentrate the air and create quite a stir. But I can't go around placing them, because I'm under maximum wind watch. Even Togo won't help me. But with your help... Please! I promise I'll show you something cool.", ["objectivesText"] = "Place the air totems in Ohn'iri Springs and then inform Radiya. Progress: If you rat me out, I'll haunt you with the windiest ghost--FOREVER! Don't do it!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 192743, 200272, 200274, 200277 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.535778, ["y"] = 0.680889 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65902] = { ["id"] = 65902, ["name"] = "Food or Floof", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65902 }, ["description"] = "Look at this juicy and delectable herbed turtle meat ! I speak objectively, of course. I'm a vegetarian. Go on! He probably hasn't had a meal all day.", ["objectivesText"] = "Bring the Herbed Turtle Meat and Glade Hoppers to Theramus. Progress: Go, before the meat gets old!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191083, 191084, 191085, 191086, 191134, 191568, 192098, 201874 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185726, ["x"] = 0.246, ["y"] = 0.632571 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185726, ["x"] = 0.246, ["y"] = 0.632571 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.246, ["y"] = 0.632571 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65903] = { ["id"] = 65903, ["name"] = "Can't Beat Fluffy", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65903 }, ["description"] = "Poor Theramus. I have an idea to cheer him up! Take this net to catch some of the native hoppers, which are docile but quick. They've made quite a home by the coast. We'll bring them to Theramus. He'll literally be overrun with fluffy goodness!", ["objectivesText"] = "Catch 12 Glade Hoppers . Progress: They are impossibly soft! I could spend all day petting them.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191083, 191084, 191085, 191086, 191134, 191568, 201874 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186303, ["x"] = 0.247, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186303, ["x"] = 0.247, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.247, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65904] = { ["id"] = 65904, ["name"] = "Enough Is Enough", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65904 }, ["description"] = "Grumpy or not, Theramus has a job to do. While he hides inside, he can't see the consequences of his absence. Let's go together. We'll show him the evidence.", ["objectivesText"] = "Bring the evidence of Lilac Ramble's damage to Theramus. Progress: This would convince anyone that the grove needs help, now!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 44785, 44788, 46723, 46800, 46824, 64533, 64534, 64535, 64536, 64537, 64538, 64539, 64540, 64541, 64542, 116404, 132305, 132306, 132308, 132309, 132310, 132311, 132312, 132314, 132316, 132317, 132319, 132320, 132321, 132322, 132323, 132325, 141933, 180901, 180902, 180903, 180904, 191083, 191084, 191085, 191086, 191134, 191568, 197890, 197894, 197898, 198609, 201874, 211279, 237812 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186303, ["x"] = 0.247, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186303, ["x"] = 0.247, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.247, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65905] = { ["id"] = 65905, ["name"] = "More Than Weeds", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65905 }, ["description"] = "Perhaps it's best we give Theramus some space. But we can't be idle. The grove is destroying itself at a rapid rate! Please help us out.", ["objectivesText"] = "Clear out overgrowth and monsters in Lilac Ramble.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191083, 191084, 191085, 191086, 191134, 191568, 201874 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185726, ["x"] = 0.246, ["y"] = 0.632571 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185726, ["x"] = 0.246, ["y"] = 0.632571 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.246, ["y"] = 0.632571 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65906] = { ["id"] = 65906, ["name"] = "A Disgruntled Initiate", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65906 }, ["description"] = "I received an interesting letter from Ohn'iri Springs. As for the letter's contents, it details, quote, horrid imprisonment, controlling mentors, and extreme boredom. It is formally signed by Initiate Radiya . There's also a sketch of an eagle... kicking a centaur named Meluun off a cliff. Well. I suppose this is a call for help, if you are so inclined to see for yourself. To be frank, I think Radiya is probably okay. She sends me such letters often.", ["objectivesText"] = "Speak to Initiate Radiya at Ohn'iri Springs in the Ohn'ahran Plains .", ["rewardGold"] = 26210, ["rewardXP"] = 345, ["rewardItems"] = { 192743, 192799 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 195302, ["x"] = 0.63, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65907] = { ["id"] = 65907, ["name"] = "Favorite Fruit", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65907 }, ["description"] = "Mystic training is so boring. I'm watching water be wet half of my days. My brothers are already out in the wild hunting drakes and primalists, and making a difference in the world. Anyway, I promised I'd show you something cool! Did you know mudstompers love bushfruit? It grows nearby, among the geysers. Go pick some and we can feed them together.", ["objectivesText"] = "Forage Wild Bushfruit from the Ohn'ir Geysers and feed them to 6 Lounging Mudstompers. Progress: I used to really like bushfruit until I had too much one day. My whole body was shivering, like a bad cold, and my breath was minty for days after.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 192743 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.535778, ["y"] = 0.680889 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65911] = { ["id"] = 65911, ["name"] = "Azure Alignment", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65911, 66210 }, ["description"] = "The bonds of this community... the friendship and family they share. I... never had that. The blue dragonflight never had that. And maybe that's because we haven't had a chance to. Now is the time. I must gather my kind. Meet me at the Azure Archives. There is much to be done.", ["objectivesText"] = "Return to Kalecgos in the Azure Archives.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 191928, 194115, 194119, 194120, 194121, 194431 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186177, ["x"] = 0.146667, ["y"] = 0.437333 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186280, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.146667, ["y"] = 0.437333 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1316, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1316, ["name"] = "Decayed Roots", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 37, ["flags"] = 0 } } },
[65913] = { ["id"] = 65913, ["name"] = "Wotcher, Watcher?", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65913 }, ["description"] = "Thank the Titans! <class>, we need your help! Primalists attacked only moments ago. My sisters and I were able to defend, but at a severe loss... There will be time to mourn after my watcher is safe! A group of Primalists broke away while we were fighting and I swear if they hurt our Watcher-- You must help her before it's too late!", ["objectivesText"] = "Rescue Watcher Mara from the Primalists in Tyrhold Reservoir.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 193043 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190527, ["x"] = 0.495, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 189045, ["x"] = 0.496, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[65914] = { ["id"] = 65914, ["name"] = "Mammoths Matter", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65914 }, ["description"] = "Our tribe has proudly nurtured the On'tuq mammoth herd for generations. Now they're... gone. Their souls will linger in rage, after such a massacre. We must honor their lives by making good use of their remains. There's too many for us to gather alone. Please, gather what materials you can from the youngsters and matriarchs, then meet me in the Kauriq Gleamlet.", ["objectivesText"] = "Collect On'tuq Hide Scraps and On'tuq Tusks from fallen On'tuq Mammoths near the Kauriq Gleamlet. Progress: My children had already picked out calves to foster into companions. How will I tell them?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191091, 191092, 191199 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186157, ["x"] = 0.4515, ["y"] = 0.549 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186157, ["x"] = 0.4515, ["y"] = 0.549 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4515, ["y"] = 0.549 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[65916] = { ["id"] = 65916, ["name"] = "We Don't Negotiate with Primalists", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65916 }, ["description"] = "The Primalists thought they were able to overcome the might of Tyr. They were wrong. My refti were able to track down the Primalists to a cave not far from here. As I thought, they have the missing keystones. Champion, if we are to restore the reservoir, we must get those keystones back. Furthermore, their leader must be slain so that they won't attempt a second assault.", ["objectivesText"] = "Slay Primalist Leader Ko'jo and retrieve the Missing Keystones in Tyrhold Reservoir. Progress: Surely once we get the keystones back, Zuttiki will not look so... Dismal.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 193043 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 189045, ["x"] = 0.496, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 189045, ["x"] = 0.496, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[65918] = { ["id"] = 65918, ["name"] = "Preventative Maintenance", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13802, ["mapID"] = 2025, ["storyline"] = { 65918 }, ["description"] = "The Primal Elementals are reproducing unchecked. Ordinarily, my sisters and I would take care of them, but we're in no condition to fight them. We've had so many of our soldiers eliminated. Besides, we few that remain have other matters we must look into. < Zuttiki winces in pain.> That's where you come in, $p. Could you take care of the elementals?", ["objectivesText"] = "Kill 8 Unleashed Elementals in Tyrhold Reservoir. Progress: Mara, my sisters? This wasn't supposed to happen.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 193043 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190527, ["x"] = 0.495, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190527, ["x"] = 0.495, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13802 } }, ["questType"] = "standard" },
[65920] = { ["id"] = 65920, ["name"] = "For the Ward!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65920 }, ["description"] = "We can finally restore the wards. We have suffered great losses, but our work must be completed. $p, we need your help once more. Bring each keystone to its rightful place in order to make the wards whole again. Once that is done, come back, so we can activate the console and restore order in the reservoir.", ["objectivesText"] = "Use the Missing Keystones to repair the reservoir wards, then activate the console. Progress: Once all three wards are repaired, return here to activate the ward console.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 193043, 195192, 195193 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 189045, ["x"] = 0.496, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 189045, ["x"] = 0.496, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[65921] = { ["id"] = 65921, ["name"] = "Refti Retribution", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65921 }, ["description"] = "I cannot get it out of my head, $p. So many of my sisters massacred! Lives tossed away... Their sacrifices will not go unanswered! My soldiers have tracked down the Primalists, and they say some of our sisters are still alive. We must rescue them, and ensure every Primalist knows my anger!", ["objectivesText"] = "Kill Primalists and rescue refti in Tyrhold Reservoir. Progress: I knew this day could always come, I just hoped that it would not.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 193043 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 190527, ["x"] = 0.495, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190527, ["x"] = 0.495, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[65925] = { ["id"] = 65925, ["name"] = "Culling the Cullers", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65925 }, ["description"] = "These wyrms don't belong here. I don't know what's driven them from their underground lairs, but there's no way to help them, now. We can't allow them to destroy the native life here. Slay the wyrms, <name>. Keep their parts, if you must, and find me in the Gleamlet when you're done.", ["objectivesText"] = "Slay Ice Slitherers and Ice Borers near the Kauriq Gleamlet.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191091, 191092, 191199 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186157, ["x"] = 0.4515, ["y"] = 0.549 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186157, ["x"] = 0.4515, ["y"] = 0.549 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4515, ["y"] = 0.549 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[65926] = { ["id"] = 65926, ["name"] = "Tackling the Falls", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65926 }, ["description"] = "Have you heard the tale of the Gleamfisher? She built a boat strong enough to pass down waterfalls! Elder Nava loves to tell the story. I think the noble spirits of the On'tuq mammoths would be honored if we used their remains to craft such a boat again. My brother says no. But if we succeed, we can help bring fish to our struggling sister tribes. You've proven your skill and passion! Together, I'm sure we can build something great.", ["objectivesText"] = "Help Ruriq build The Fallstrider.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191091, 191092, 191199 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186157, ["x"] = 0.4515, ["y"] = 0.549 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186386, ["x"] = 0.4536, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4515, ["y"] = 0.549 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[65928] = { ["id"] = 65928, ["name"] = "Wayward Winds", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65928 }, ["description"] = "Bah! Work together, she says? But... if the Gleamfisher believes there is a chance we can help the other tribes... we must try. For the wind spirit Kraunot to acknowledge us, we will first have to tend to his element. The nearby wind elementals have been agitated ever since the land began to awaken. While I inspect this boat you two made, you go and fight to dismantle them, then bring me their restless motes . That should bring some calm back to the area.", ["objectivesText"] = "Collect 10 Restless Wind Motes from Restless Winds near the Kauriq Gleamlet. Progress: Don't worry, these wind elementals being here simply means they are riled up. By destroying them, we will restore some peace to the winds here.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191091, 191092, 191199 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186386, ["x"] = 0.4536, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186386, ["x"] = 0.4536, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4536, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[65929] = { ["id"] = 65929, ["name"] = "Ice Breakers", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65929 }, ["description"] = "I knew the ancestor would approve! I don't know much about spirits -- Kauj is the shaman. But we will need to appease the great Spirits of Air and Water before they will appear to us. Anyone could see water elementals up the mountain slowly freezing. It is not a natural freeze. Cold has been coming down the mountains more than usual, lately. Left be, our entire river could ice over. Release them from their icy prisons!", ["objectivesText"] = "Break Freezing Waters from ice near the Kauriq Gleamlet. Progress: We welcome the natural shift of the earth, but this encroaching ice... it threatens our entire home.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191091, 191092, 191199 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186157, ["x"] = 0.4515, ["y"] = 0.549 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186157, ["x"] = 0.4515, ["y"] = 0.549 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4515, ["y"] = 0.549 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[65930] = { ["id"] = 65930, ["name"] = "A Wrestle of Wind and Water", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65930 }, ["description"] = "Now we should be able to face the Spirits. Did Ruriq fail to mention it? By our tribe's traditions, we must face the Spirits in combat before asking a boon of them. The strength of their blessing is dependent on how well you impress them. Perhaps that is why the Gleamfisher insisted we all work together. If you take on Kraunot, the Spirit of Air, Ruriq and I will tackle Otu'rorq, the Spirit of Water. They dwell in the cave behind the nearby waterfall. We will meet you there, adventurer.", ["objectivesText"] = "Face Kraunot, the Spirit of Air, near the Kauriq Gleamlet. Progress: We must impress those spirits if Ruriq 's vision is to come to life.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 191091, 191092, 191199 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186386, ["x"] = 0.4536, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186157, ["x"] = 0.4515, ["y"] = 0.549 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4536, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[65935] = { ["id"] = 65935, ["name"] = "Catching Up to Chromie", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "You have helped us regain our hold on the sands, but I can sense something greater happening up on the temple platforms. Let us take to the skies and regroup with Ambassador Chronormu there. As always, time is of the essence.", ["objectivesText"] = "Meet with Chromie on the Temporal Conflux platforms.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 192602, 192809, 198408, 198410 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187877, ["x"] = 0.575, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186711, ["x"] = 0.595, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1324, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1324, ["name"] = "Time Management", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 23, ["flags"] = 0 } } },
[65937] = { ["id"] = 65937, ["name"] = "Proof of Negligence", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65937 }, ["description"] = "We can't give up. He must understand what's happening out here! If he won't leave the cave, we'll show him directly. Anything will do, I'm sure. There's so much going wrong, from the corrupted flora to the antagonized wildlife!", ["objectivesText"] = "Find and then show evidence of the Lilac Ramble's damage to Theramus. Progress: It's terrible to see the grove, and Theramus, in such a state.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191083, 191084, 191085, 191086, 191134, 191568, 201874 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186303, ["x"] = 0.247, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186303, ["x"] = 0.247, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.247, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65938] = { ["id"] = 65938, ["name"] = "The Once and Future Team", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "All right! Let's pop that stasis bubble around the temple doors and release our Wardens! Are you ready for a huge tug-of-war match with time itself? Yank at the door's bubble like you did with the crystals earlier. But be careful, all the time energy released is sure to collect and attack you. I'm not sure what will be there, but at least you'll have the freed Wardens on your side no matter what happens. Good luck, <name>!", ["objectivesText"] = "Use your Timewalker Staff to pop the temple door's stasis bubble. Progress: We really should've foreseen this when we built our security system all that time ago...", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 192602, 192809, 195199, 198408, 198410 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186711, ["x"] = 0.595, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186711, ["x"] = 0.595, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1324, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1324, ["name"] = "Time Management", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 27, ["flags"] = 0 } } },
[65939] = { ["id"] = 65939, ["name"] = "The Courage of One's Convictions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "The next battle will no doubt be fierce, but our courage and determination will overcome their greater numbers. I am counting on your exceptional skills to help lead the troops to victory. We shall begin the assault when you are ready.", ["objectivesText"] = "Gain control of the Obsidian Citadel. Progress: Have we secured the Citadel.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 191131, 192548 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186681, ["x"] = 0.34, ["y"] = 0.612 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186933, ["x"] = 0.29, ["y"] = 0.588 }, { ["mapID"] = 2022, ["npcID"] = 187045, ["x"] = 0.272, ["y"] = 0.625 }, { ["mapID"] = 2022, ["npcID"] = 196265, ["x"] = 0.264, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 37, ["flags"] = 0 } } },
[65940] = { ["id"] = 65940, ["name"] = "By Broken Road", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65779, 65780, 65783, 65795, 65801, 65802, 65803, 65804, 65805, 65806, 65940, 66848, 70174, 70185 }, ["series"] = { 65805, 66848 }, ["description"] = "I hope you don't mind getting your feet wet. The next leg of our journey will take us across two rivers. Ohn Seshteng would like to share a story with you about our blessed watcher, Ohn'ahra. I happily leave you under her watch.", ["objectivesText"] = "Travel with the Shikaar caravan to the river crossing.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 191055, 191100, 191101, 191102, 191103, 192812, 198517 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185882, ["x"] = 0.808, ["y"] = 0.254333 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 184595, ["x"] = 0.778, ["y"] = 0.293 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.808, ["y"] = 0.254333 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1303, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1303, ["name"] = "Into the Plains", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 9, ["flags"] = 0 } } },
[65943] = { ["id"] = 65943, ["name"] = "Primal Offensive", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "Khadgar and I are doing our best to hold off the Primalists in the sky, but we can't push further towards the tower. We need you to weaken their ground forces so we can get closer to Raszageth and stop her before it's too late. Make your way through the Primalists ahead. If I can maintain my concentration, there'll be another mirror image waiting.", ["objectivesText"] = "Defeat 15 Primalists within Vakthros.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 192478, 192479, 194705 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186304, ["x"] = 0.7, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186686, ["x"] = 0.744, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1315, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1315, ["name"] = "Vakthros", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 41, ["flags"] = 0 } } },
[65944] = { ["id"] = 65944, ["name"] = "Lava Burst", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "The Primalists have torn apart the mountain to send their forces streaming to Vakthros! I spied some lava orbs in the initial corridor that they're using to spread more of their elemental chaos. Destroy them to help slow their advance. I'll do what I can from up here to help Kalecgos.", ["objectivesText"] = "Destroy 3 Lava Orbs .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 192478, 192479, 194705 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186305, ["x"] = 0.7, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186688, ["x"] = 0.744, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1315, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1315, ["name"] = "Vakthros", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 42, ["flags"] = 0 } } },
[65947] = { ["id"] = 65947, ["name"] = "Time-Locked Timewalkers", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "I'm so glad you're here! I need you to stabilize the situation here on the platforms while Dante and Zera help me hold our infinite dragon friend in place. The temple's security measures locked Eternus in a stasis bubble when she tried to take control of our Oathstone. Unfortunately, the other Timewalkers were also caught in those security measures. Your Timewalker staff should free them, no problem. Just make sure to deal with any angry timelings that pop up!", ["objectivesText"] = "Free 8 Timewalkers from Time Bubbles. Progress: We can't have our Temple visitors rest inside of stasis bubbles when they get here. Oh, wait! Maybe that's exactly what we should do! I'll write it down for later, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 191113, 192602, 192809, 198408, 198410 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186711, ["x"] = 0.595, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186711, ["x"] = 0.595, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1324, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1324, ["name"] = "Time Management", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 24, ["flags"] = 0 } } },
[65948] = { ["id"] = 65948, ["name"] = "Cracks in Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "When the temple locked down, the Wardens got sealed up with the temple doors. We need to pop that stasis bubble to get them out! Unfortunately, that'll need a fully empowered Timewalker staff... I know! You can drain the crystals here on the platforms! That should power up your staff enough. They have their own stasis fields, so just yank them out and absorb their energy with your staff. And don't feel bad if they shatter--the power is still there, even if it's in pieces!", ["objectivesText"] = "Use the East and West crystals to further empower your Timewalker Staff.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192602, 192809, 197151, 198408, 198410 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186711, ["x"] = 0.595, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186711, ["x"] = 0.595, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1324, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1324, ["name"] = "Time Management", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 25, ["flags"] = 0 } } },
[65949] = { ["id"] = 65949, ["name"] = "The Sole Mender", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65949 }, ["description"] = "When we join Ohn'ahra in the wind, we leave these medallions behind. Although I helped craft this medallion, I am not its rightful owner. It should be returned to Roscha. It is the last memory of her betrothed. Take it to her so she may mourn and be at peace.", ["objectivesText"] = "Return the Medallion to Farrier Roscha . Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 1385, ["rewardItems"] = { 191127, 191143, 191541, 192054, 197668, 198792, 198793, 198794, 198795 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186649, ["x"] = 0.8215, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186650, ["x"] = 0.844, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.8215, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65950] = { ["id"] = 65950, ["name"] = "Thieving Gorlocs", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65950 }, ["description"] = "Is Farrier Roscha invited to the caravan? No! But who must provide shoes for the caravan? Farrier Roscha . And from whom do the Mudfins steal? Of course, Farrier Roscha . Pah. I would send Khasar , but who knows where he has wandered this time? Find my supplies. Teach those thieving creatures not to steal from Farrier Roscha . Go!", ["objectivesText"] = "Return the stolen supplies from the Mudfin Village. Progress: There are too many gorlocs around us. We're not safe here.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191127, 191143, 191541, 198792, 198793, 198794, 198795 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186650, ["x"] = 0.844, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186649, ["x"] = 0.8215, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.844, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65951] = { ["id"] = 65951, ["name"] = "Sole Supplier", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65951 }, ["description"] = "Poor Roscha! She has toiled endlessly to prepare for the caravan, only for her supplies to be stolen by nasty gorlocs. She has lost so much already. I am doing my best to assist her. Khasar likely went after her supplies alone, telling no one. It is his way. But he has been gone too long. Many dogs are missing as well. Would you please check on Khasar and the dogs, $p?", ["objectivesText"] = "Search the woods for Khasar .", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 191127, 191143, 191541, 198792, 198793, 198794, 198795 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186653, ["x"] = 0.844, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186649, ["x"] = 0.8215, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.844, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65952] = { ["id"] = 65952, ["name"] = "A Chief of Legends", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65952 }, ["description"] = "The gorlocs of this swamp were once simple creatures. Pests, perhaps, but never raiders, thieves, or dog-eaters. It is their chief, Grrlgllmesh, who has led them away from their nature. Put an end to him, and the gorlocs will threaten us no more.", ["objectivesText"] = "Kill Chief Grrlgllmesh . Progress: Chief Grrlgllmesh is a scourge to these lands.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 191127, 191143, 191541, 198792, 198793, 198794, 198795 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186649, ["x"] = 0.8215, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186649, ["x"] = 0.8215, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.8215, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65953] = { ["id"] = 65953, ["name"] = "The Ora-cull", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65953 }, ["description"] = "Of all the madness in this gorloc village, I have discovered none so troubling as the gorloc shamans. They are particularly vicious and play recklessly with storm magic with no regard for the consequences. This must be put to an end. Slay them, and bring me their totems. Our mystics will be interested in them.", ["objectivesText"] = "Collect 4 totems from gorloc shamans. Progress: The gorloc shamans have gone too far.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191127, 191143, 191541, 198792, 198793, 198794, 198795 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186649, ["x"] = 0.8215, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186649, ["x"] = 0.8215, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.8215, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65954] = { ["id"] = 65954, ["name"] = "Release the Hounds", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65954 }, ["description"] = "I have heard the familiar howls and barks of bakar that are missing from camp. Our beloved dogs are trapped in cages, waiting to be ripped apart by those... those things. We have a duty to our companions. Free them and witness the true might of a Shikaar bakar!", ["objectivesText"] = "Free the Shikaar Bakar. Progress: The gorlocs of this village will learn to fear our bakar.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191127, 191143, 191539, 191540, 191541, 197960, 198792, 198793, 198794, 198795 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186649, ["x"] = 0.8215, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186649, ["x"] = 0.8215, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.8215, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65955] = { ["id"] = 65955, ["name"] = "A Centaur's Best Friend", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65955 }, ["description"] = "It isn't safe for us to remain in the open, $p. The gorlocs forced my hunting companion, Baba, into a cave to the east. Set me free, then we shall rescue Baba. I will meet you in the cave when the path is clear.", ["objectivesText"] = "Free Khasar and meet him in the cave. Progress: Together, Baba and I are one hunting unit greater than all the rest.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 191127, 191143, 191541, 198792, 198793, 198794, 198795 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 186649, ["x"] = 0.8215, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186649, ["x"] = 0.8215, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.8215, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65956] = { ["id"] = 65956, ["name"] = "Talon Strike", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "With your help, my Blacktalon assassins will cut down the djaradin defending the outer perimeter. Mark any targets with a small stun bomb, and they will come to your aid. Proceed quickly and eliminate anything that may hinder our advance.", ["objectivesText"] = "Djaradin defenses disrupted. Progress: Have you eliminated their defenses?", ["rewardGold"] = 68950, ["rewardXP"] = 1415, ["rewardItems"] = { 191131, 192548 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186274, ["x"] = 0.424, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186681, ["x"] = 0.34, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 35, ["flags"] = 0 } } },
[65957] = { ["id"] = 65957, ["name"] = "No Time for Heroes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "From what we have observed, djaradin society is built on strength. The strongest serve as examples for others to fight all the harder. Among the forces below are three examples of the mightiest djaradin... and your targets. You, <name>, will personally eliminate them. This should deal a devastating blow to their morale.", ["objectivesText"] = "Slay Modak the Flamespit, Piercer Gigra , and Olphis the Molten . Progress: Have you defeated your targets?", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 191131, 192548, 194370 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186274, ["x"] = 0.424, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186681, ["x"] = 0.34, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 36, ["flags"] = 0 } } },
[65958] = { ["id"] = 65958, ["name"] = "Primal Power", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "I'm afraid it's becoming harder to maintain my mirror images. The Primalists are focusing their efforts to tearing me out from the sky. Not to worry... I have a plan. I need you to take the orb you recovered and gather elemental magic from slain Primalists. We'll need that elemental power up ahead to divert their forces away from me.", ["objectivesText"] = "Use the Elemental Focus to drain elemental energy out of slain Primalists and elementals. Progress: We must act quickly.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 61528, 61529, 61530, 131529, 192478, 192479, 194705 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186686, ["x"] = 0.744, ["y"] = 0.378 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186779, ["x"] = 0.768, ["y"] = 0.394 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.744, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1315, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1315, ["name"] = "Vakthros", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 44, ["flags"] = 0 } } },
[65962] = { ["id"] = 65962, ["name"] = "The Never-Final Countdown", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["description"] = "I never thought I'd save our temple by dismantling the very security we set up to protect it, but here we are! With the time elementals purged, our Timewalkers free, and our Wardens at the ready, it's finally time to let this last stasis bubble down and deal with Eternus. Let me know when you're ready. I know with you by my side nothing can go wrong.", ["objectivesText"] = "Speak to Chromie when ready.", ["rewardGold"] = 70225, ["rewardXP"] = 1365, ["rewardItems"] = { 192602, 192809, 194521, 198408, 198410 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 186711, ["x"] = 0.595, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 186931, ["x"] = 0.6, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 189, ["title"] = "Thaldraszus", ["questLineID"] = 1324, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1324, ["name"] = "Time Management", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 28, ["flags"] = 0 } } },
[65977] = { ["id"] = 65977, ["name"] = "Kirin Tor Recovery", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 65686, 65688, 65689, 65702, 65709, 65751, 65752, 65838, 65844, 65845, 65846, 65847, 65848, 65849, 65850, 65852, 65854, 65855, 65864, 65866, 65867, 65868, 65869, 65870, 65871, 65872, 65873, 65886, 65887, 65911, 65943, 65944, 65958, 65977, 66007, 66009, 66015, 66026, 66027, 66210, 66228, 66239, 66340, 66647, 66699, 67033, 67035, 67036, 70041, 70746, 70747, 72268 }, ["description"] = "When the Primalists attacked our expedition, I feared many of our mages were lost to us. It seems they were taken by the Primalists and are being tortured as we speak! Please, you must rescue the mages left here. They may not be able to help in this fight, but we cannot leave them behind!", ["objectivesText"] = "Rescue 6 Dying Mages . Progress: We must aid those mages.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 192478, 192479, 194705 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186688, ["x"] = 0.744, ["y"] = 0.378 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186779, ["x"] = 0.768, ["y"] = 0.394 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.744, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 174, ["title"] = "The Azure Span", ["questLineID"] = 1315, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5566, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1315, ["name"] = "Vakthros", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5566, ["name"] = "The Azure Span", ["orderIndex"] = 45, ["flags"] = 0 } } },
[65989] = { ["id"] = 65989, ["name"] = "Invader Djaradin", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65760, 65989, 65990, 65991, 65992, 65993, 65995, 65996, 65997, 65998, 65999, 66000, 66001 }, ["description"] = "We may not have the power to take back our outpost, but we do not have to surrender without a fight. Show them we still have teeth.", ["objectivesText"] = "Kill 6 djaradin at the Dragonheart Outpost. Progress: The djaradin had not been seen for generations. We were... unprepared.", ["rewardGold"] = 17450, ["rewardXP"] = 1415, ["rewardItems"] = { 193874, 194400, 194401, 194402, 194403 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186584, ["x"] = 0.712, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186584, ["x"] = 0.712, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1299, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1299, ["name"] = "Dragons in Distress", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 1, ["flags"] = 0 } } },
[65990] = { ["id"] = 65990, ["name"] = "Deliver Whelps From Evil", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65760, 65989, 65990, 65991, 65992, 65993, 65995, 65996, 65997, 65998, 65999, 66000, 66001 }, ["description"] = "They descended upon us before we could even respond. My guards held as long as they could as we evacuated the young and helpless, but I fear that there are more within the outpost. Cross that bridge and search for survivors.", ["objectivesText"] = "Save 4 Whimpering Whelplings from Dragonheart Outpost. Progress: We will take back the town as soon as we can muster the forces... but for now, the lives of our people must be our priority.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193874 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186584, ["x"] = 0.712, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186584, ["x"] = 0.712, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1299, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1299, ["name"] = "Dragons in Distress", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 2, ["flags"] = 0 } } },
[65991] = { ["id"] = 65991, ["name"] = "Time for a Reckoning", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65760, 65989, 65990, 65991, 65992, 65993, 65995, 65996, 65997, 65998, 65999, 66000, 66001 }, ["description"] = "Cadet Sendrax has informed me of our majordomo's plans. Thank the Life-Binder that we have their help. Their interference gives us the reprieve we need to get our wounded back to the Life Pools to be treated. I wish I could reinforce Selistra but I must keep my guards near the wounded. Go to the enemy stronghold to meet them. If there were another way of handling the djaradin, I would ask it. But, as it were... You must do what you must.", ["objectivesText"] = "Meet Wrathion and Majordomo Selistra at Scalecracker Keep.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193874 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186584, ["x"] = 0.712, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186640, ["x"] = 0.664, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1299, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1299, ["name"] = "Dragons in Distress", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 3, ["flags"] = 0 } } },
[65992] = { ["id"] = 65992, ["name"] = "Blacktalon Intel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65760, 65989, 65990, 65991, 65992, 65993, 65995, 65996, 65997, 65998, 65999, 66000, 66001 }, ["description"] = "While Selistra and I attracted their eyes above, shadows crept in through their defenses. My agents, the Blacktalon, are keeping an eye and an ear throughout the keep. Meet them and let them know you're on our side. They'll give you some valuable information on our enemies.", ["objectivesText"] = "Speak to Wrathion 's spies hidden around Scalecracker Keep. Progress: I've put my life in their hands. You can trust them.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193874 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186640, ["x"] = 0.664, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 194772, ["x"] = 0.626, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1299, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1299, ["name"] = "Dragons in Distress", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 5, ["flags"] = 0 } } },
[65993] = { ["id"] = 65993, ["name"] = "Killjoy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65760, 65989, 65990, 65991, 65992, 65993, 65995, 65996, 65997, 65998, 65999, 66000, 66001 }, ["description"] = "Ah, yes. I saw the leader of these giants headed back from the raid shortly after I arrived. She's celebrating their victory somewhere within the camp. It would be a shame if someone interrupted her revelries, don't you think?", ["objectivesText"] = "Kill Meatgrinder Sotok at Scalecracker Keep.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 193874, 194373, 194374, 194375, 194377, 194389, 194392, 194394, 198488 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 186640, ["x"] = 0.664, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 194772, ["x"] = 0.626, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1299, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1299, ["name"] = "Dragons in Distress", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 4, ["flags"] = 0 } } },
