[69888] = { ["id"] = 69888, ["name"] = "Unusual Suspects", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69888 }, ["description"] = "<name>, you're here. Good. Don't react, but our findings on the titan discs have just been stolen! Other than us, only the Sundered Flame know what we were up to in that facility. I need ye to take this device and scan some of the suspicious members that have joined us recently. Reveal the spy and recover the data if you can. We cannae allow it to fall into their hands!", ["objectivesText"] = "Scan Suspicious Explorers to reveal the spy. Progress: Be quick and be casual. Got it?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 197805, 201782 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187276, ["x"] = 0.472, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187276, ["x"] = 0.472, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
