[69895] = { ["id"] = 69895, ["name"] = "Summoned Destroyer", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["storyline"] = { 69895 }, ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2VignetteID"] = 5213, ["db2VignetteName"] = "Summoned Destroyer" },
[69896] = { ["id"] = 69896, ["name"] = "Disastrous Detour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69896 }, ["description"] = "I knew joining the Dragonscale Expedition meant venturing into dangerous territory. But I was not expecting to fight off elementals! Our dig site at the Life Vault Ruins is in complete disarray! Stone monstrosities are rising up out of the ground! We called in an elementalist to consult, but I believe she will need all the help she can get. Perhaps you can help her? Our camp is just across the river.", ["objectivesText"] = "Meet Elementalist Taiyang in the Life Vault Ruins.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190273, ["x"] = 0.635, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188735, ["x"] = 0.66, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[69897] = { ["id"] = 69897, ["name"] = "Behavior Analysis \"Homework\"", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69897 }, ["description"] = "I need to talk to someone who knows proto-whelps. Like the ones that live in the Wild Preserve! Are they as angry as the big ones? Do they bite or breathe fire at you? What if I... er... you petted a proto-whelp? Would they know that you're nice and trying to help them? I'm asking for science, of course. Tyrgon always tells us to test our hippa... no... hypo... hmph! Hyppotatotoast... ugh! THEORIES! I think they would like petting and it would make them feel good. Could you test that for me?", ["objectivesText"] = "Pet 3 Sleeping Whelps and report back to Iyali . Progress: Do you think a whelp would feel better if I petted them? I always feel better when I get hurt and mom takes care of me. < Iyali looks around, avoiding eye contact.> I know I'm not supposed to touch the animals. It's for my homework on, uh, proto-whelp behavior. And it's due, uh, soon. So...", ["rewardGold"] = 37050, ["rewardXP"] = 710, ["rewardItems"] = { 194564 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193500, ["x"] = 0.458, ["y"] = 0.814 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193500, ["x"] = 0.458, ["y"] = 0.814 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.814 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[69898] = { ["id"] = 69898, ["name"] = "Scientific Meat-thod", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69898 }, ["description"] = "So, I have, uh, more homework... Professor Tyrgon's lessons are super tough! He wants us to find out what proto-whelps, uh, eat! Yeah... I already know the answer! It's riverbeast meat! Can you bring me a piece of riverbeast meat? Some riverbeast meat would be a great \"visual aid\" for my project. But it has to be a REALLY good piece, ok? Like... the ones from Pudgy Riverbeasts. One like a momma proto-drake would give their whelp to make them strong because, uh, it will make Mister Tyrgon happy.", ["objectivesText"] = "Collect 1 piece of Extra-Delicious Riverbeast Meat . Progress: Mom says food makes everyone happy. Maybe it will be friends with me then... I mean, we'll all be friends! And Professor Tyrgon won't give me a bad grade if I make Riverbeast meat part of my project!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 194564 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193500, ["x"] = 0.458, ["y"] = 0.814 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193500, ["x"] = 0.458, ["y"] = 0.814 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.814 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[69899] = { ["id"] = 69899, ["name"] = "Secret Research", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69899 }, ["description"] = "I know.. I am acting weird. I'm sorry! You probably guessed I am not being truthful. I can tell you my secret... if you like. But you will have to promise not to tell the adults!", ["objectivesText"] = "Help Iyali and their friends. Progress: We found this Injured Proto-Whelp in the Wild Preserve. There was an evil Primalist attacking Proto-Dragons and... they hurt this poor little whelpling! Please don't yell at us... We just wanted to help!", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 194564 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193500, ["x"] = 0.458, ["y"] = 0.814 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.814 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[69900] = { ["id"] = 69900, ["name"] = "Identifying the Source", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69900 }, ["description"] = "Judging by what the children have said, we might have a primalist prowling the Wild Preserve. This calls for immediate investigation. According to what other researchers have observed, Primalists like to steal eggs and whelps to infuse them with power and corrupt them. Those that don't acclimate to the process suffer a slow death... not that the primalists seem to care... We need them out of the Preserve. Attend to that, and I will try to distract the children. They must not know of this.", ["objectivesText"] = "Slay the experimenting primalist in the Wild Preserve. Progress: Keep your voice down! Have you done what I asked?", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 194564 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[69901] = { ["id"] = 69901, ["name"] = "Bring In the Expert", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69901 }, ["description"] = "Did Iyali say how long this creature has been suffering? If it's too injured to eat, we need to treat it quickly. Normally a Dragonscale Expedition camp would have everything I need to help this whelp, but getting supplies to the \"frontier\" here on the Dragon Isles has proven tricky. There have been significant delays in our supply routes. But, fear not. The land itself will provide! If you bring me Sunlight Flowers , I can craft a soothing balm that will calm the drake so I can heal it.", ["objectivesText"] = "Collect 5 Sunlight Flowers . Progress: Sunlight Flowers are very useful resource. Their petals and stalks have sedative properties which will ease the whelp's suffering while we heal it.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 194564 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[69902] = { ["id"] = 69902, ["name"] = "Theory in Practice", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69902 }, ["description"] = "<name>, I require your assistance... I hope no one was expecting me to craft, subdue the whelp, heal, and teach these children all at once! Multitasking like that is certainly overrated. Now, you can start by using those flowers. I'll need a couple minutes to prepare myself to heal the proto-whelp. Hopefully, the children will find this incident... instructional.", ["objectivesText"] = "Assist Tyrgon to heal the creature. Progress: Where on earth did they get the idea we wouldn't help them? I need to investigate this further...", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 194564 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192298, ["x"] = 0.46, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[69904] = { ["id"] = 69904, ["name"] = "Suspiciously Quiet", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 69904 }, ["description"] = "Can you spare a minute, $p? I haven't heard from my two apprentices, Scrumpy and Tucky, in some time. This is concerning. I sent them to fetch us supplies for the inn. They couldn't have strayed too far... Please find them, but I warn you... They're... quite the handful.", ["objectivesText"] = "Find Noriko's apprentices in Camp Antonidas.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 200926 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 183543, ["x"] = 0.466, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189198, ["x"] = 0.476, ["y"] = 0.402 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[69910] = { ["id"] = 69910, ["name"] = "Where is Wrathion?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65435, 65437, 65439, 65443, 65444, 65451, 65452, 65453, 69910, 69911, 69912, 69914, 69944, 70198, 72256, 72293 }, ["description"] = "How unusual. Ebyssian told us that Wrathion would be awaiting our arrival along with an ambassador for Alexstrasza the Life-Binder, Queen of the Dragons. It isn't like a dragon to break a promise. At least this eager drakonid is here to greet us. Would you kindly inquire into when the others shall arrive?", ["objectivesText"] = "Ask Sendrax when the dragons are expected to arrive. Progress: Welcome to the Dragon Isles, friend! ... I think I may have already said that. No matter! I am just excited you are here!", ["rewardGold"] = 3575, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 184870, ["x"] = 0.766, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193362, ["x"] = 0.765, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.766, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 10, ["flags"] = 0 } } },
[69911] = { ["id"] = 69911, ["name"] = "Excuse the Mess", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65435, 65436, 65437, 65439, 65443, 65444, 65451, 65452, 65453, 66577, 66589, 66596, 67700, 69910, 69911, 69912, 69914, 69944, 70050, 70122, 70123, 70124, 70125, 70197, 70198, 72240, 72256, 72293 }, ["description"] = "I wish I knew more about how to welcome you to the Dragon Isles, but I'm only the sentry. < Sendrax motions to the tower behind her.> You could try talking with Ambassador Fastrasz in the visitor center. He might be able to answer more of your questions before the dragons arrive. Mind your step in there. He was clearing out rubble last I saw.", ["objectivesText"] = "Help Ambassador Fastrasz restore the embassy. Progress: Ambassador Fastrasz will be eager to meet you.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 198398 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193362, ["x"] = 0.765, ["y"] = 0.336 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193362, ["x"] = 0.765, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 22, ["flags"] = 0 } } },
[69912] = { ["id"] = 69912, ["name"] = "My First Real Emergency!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65435, 65436, 65437, 65439, 65443, 65444, 65451, 65452, 65453, 66577, 66589, 66596, 67700, 69910, 69911, 69912, 69914, 69944, 70050, 70122, 70123, 70124, 70125, 70197, 70198, 72240, 72256, 72293 }, ["description"] = "< Sendrax looks puzzled.> I have never known the majordomo to be late to anything, much less THIS late to something THIS important. Most unusual... < Sendrax perks up at a thought.> I could use my emergency signal flare to alert them to your arrival. Then they would come rushing to greet you immediately! I've never fired my emergency signal flare before, though...", ["objectivesText"] = "Convince Sendrax to fire her emergency signal flare to alert the dragons of your arrival.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 198398 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193362, ["x"] = 0.765, ["y"] = 0.336 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193371, ["x"] = 0.762, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 23, ["flags"] = 0 } } },
[69913] = { ["id"] = 69913, ["name"] = "Towers of Earthen Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["mapID"] = 2022, ["storyline"] = { 69913 }, ["objectivesText"] = "Earthen Energy deposited Earthen Energy deposited", ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Earthen Energy deposited", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Earthen Energy deposited", ["amount"] = 5, ["type"] = 0, ["objectID"] = 193416, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[69914] = { ["id"] = 69914, ["name"] = "The Djaradin Have Awoken", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65435, 65436, 65437, 65439, 65443, 65444, 65451, 65452, 65453, 66577, 66589, 66596, 67700, 69910, 69911, 69912, 69914, 69944, 70050, 70122, 70123, 70124, 70125, 70197, 70198, 72240, 72256, 72293 }, ["description"] = "I wish we'd time for more pleasant introductions, but we can't all be Chronormu, can we? I am Selistra, majordomo to Alexstrasza the Life-Binder, Queen of the Dragons. Queen Alexstrasza asked me to convey her kindest regards and escort you to her at the Life Pools. But I'm afraid I must ask for your assistance before we go meet her. Our ancient rivals, the djaradin, have awoken from their slumber under the earth and have already assaulted a nearby outpost!", ["objectivesText"] = "Receive your orders from Majordomo Selistra . Progress: We must do whatever the majordomo asks of us.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198398 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193372, ["x"] = 0.762, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193363, ["x"] = 0.762, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 24, ["flags"] = 0 } } },
[69915] = { ["id"] = 69915, ["name"] = "Targeted Ads", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 69915 }, ["description"] = "Hi, hi, hi! You looking for a gig? We're doing a BIG opening sale for our new Crafting Order service, and we need to draw attention! But the wind took my flyers and I think some of the local goats ran off with them. Could you get my flyers back?", ["objectivesText"] = "Recover flyers from Forkriver and Meddlesome Goats. Progress: Whoo! Setting up a business is busy, busy, busy!", ["rewardXP"] = 2765, ["rewardItems"] = { 190456, 191233, 191237, 191240, 191241, 191242, 194125, 198091, 198225, 198245, 198346, 198347, 198348, 198715 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 193108, ["x"] = 0.72, ["y"] = 0.81 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 193108, ["x"] = 0.72, ["y"] = 0.81 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.81 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "profession" },
