[69918] = { ["id"] = 69918, ["name"] = "Shaking Our Foundations", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69918 }, ["description"] = "Djaradin stonebinders are threatening to break the very foundations of the Citadel! They have to be stopped! We haven't even had a chance to reclaim the Citadel as our own and yet it might crumble beneath us. We can't let that happen. Do what you can, <name>... by that I mean kill them!", ["objectivesText"] = "Slay Stonewrecker Tokara , Molka the Grinder , and the elementals they have unleashed. Progress: Have you saved the foundation of this Citadel?", ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192020, 192021, 192033, 192037, 193477, 197923, 197926, 197956, 197957, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190899, ["x"] = 0.266, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190899, ["x"] = 0.266, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[69919] = { ["id"] = 69919, ["name"] = "A Craft in Need", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2023, ["storyline"] = { 69919 }, ["description"] = "You seem like a skilled crafter. Would you like to fill some crafting orders for fellow adventurers and get rich, rich, rich? I'll tell you the rules of working with the Artisan's Consortium, then you can pick up Crafting Orders at any crafting station on the Dragon Isles!", ["objectivesText"] = "Speak with Azley to learn about filling Crafting Orders. Progress: Business is busy, busy, busy!", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 190456, 193479, 193529, 193534, 193538, 198091, 198346, 198347, 198348, 251321, 251322, 251324, 251326, 251327 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 193108, ["x"] = 0.72, ["y"] = 0.81 }, { ["mapID"] = 2112, ["npcID"] = 194026, ["x"] = 0.3552, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 193108, ["x"] = 0.72, ["y"] = 0.81 }, { ["mapID"] = 2112, ["npcID"] = 194026, ["x"] = 0.3552, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.81 }, ["mapCandidates"] = { ["npc"] = { 2023, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession" },
[69923] = { ["id"] = 69923, ["name"] = "A Primal Threat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 66586, 69923, 69925, 69944, 69992 }, ["description"] = "Raszageth has wasted no time building up her Primalist forces. The Kirin Tor have detected massive storms being unleashed at key points across Kalimdor and the Eastern Kingdoms. The Primalists are unleashing the elements to add to their strength. It seems they plan to cause chaos not only in the Dragon Isles, but in the lands of the Alliance and Horde as well. Seek out the enemy and study their methods. We have to stop them before it's too late.", ["objectivesText"] = "Gather 10 Motes of Primal Energy from enemies in active primal storm locations throughout Kalimdor and the Eastern Kingdoms. Progress: I'm afraid this is only the beginning.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192493, 199109, 199211 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 1405, ["name"] = "10.0 Pre-Patch [DNT]", ["orderIndex"] = 6, ["flags"] = 0 } } },
