[69925] = { ["id"] = 69925, ["name"] = "Calming the Storms", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 66586, 69923, 69925, 69944, 69992 }, ["description"] = "These Primalists are relentless, unleashing elemental devastation across the Eastern Kingdoms and Kalimdor. You must show the same determination, <name>. It is the only way to stop them. Find their next incursion, remove the enemies within the primal storm area before it is too late and foil their efforts. We must protect Azeroth!", ["objectivesText"] = "Gather 10 Motes of Primal Energy from enemies in active primal storm locations throughout Kalimdor and the Eastern Kingdoms. Progress: Our effort continues.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192493, 199211 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 193450, ["x"] = 0.558, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 1405, ["name"] = "10.0 Pre-Patch [DNT]", ["orderIndex"] = 7, ["flags"] = 0 } } },
[69926] = { ["id"] = 69926, ["name"] = "Becca Black and the Seven Gnomes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69926 }, ["description"] = "The djaradin have ransacked the Obsidian Citadel and stolen a number of valuable artifacts. Wrathion has tasked us to recover every item taken from the Citadel. My team has located several in the area, but we could use your help.", ["objectivesText"] = "Recover the missing artifacts. Progress: Have you found everything on the list?", ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 191984, 191989, 191991, 191992, 191993, 191995, 191996, 191998, 192000, 192001, 192004, 192005, 192006, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192037, 193477, 197931, 197939, 197946, 197950, 197959, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191014, ["x"] = 0.322, ["y"] = 0.654 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191014, ["x"] = 0.322, ["y"] = 0.654 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.322, ["y"] = 0.654 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
