[69944] = { ["id"] = 69944, ["name"] = "Chasing Storms", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 66586, 69923, 69925, 69944, 69992 }, ["series"] = { 65444, 70198 }, ["description"] = "Well, that wizard certainly knows how to make an entrance, doesn't he? We won't be able to set sail until someone gets those elemental storms under control. Check-in with Storm Huntress Suhrakka . She's leading the expedition efforts to investigate the storms and can help outfit you with whatever gear you need. While you handle that, I'll coordinate the rest of the preparations. At least it'll give me some time to read a few more volumes on dragon history before we set sail.", ["objectivesText"] = "Speak with Storm Huntress Suhrakka at the zeppelin tower.", ["rewardGold"] = 715, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 197279, ["x"] = 0.558, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 195899, ["x"] = 0.558, ["y"] = 0.124 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 1405, ["name"] = "10.0 Pre-Patch [DNT]", ["orderIndex"] = 8, ["flags"] = 0 } } },
[69946] = { ["id"] = 69946, ["name"] = "The Master of Their Craft", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2022, ["storyline"] = { 67100, 67137, 67295, 67564, 69946, 69979 }, ["description"] = "While I was traveling through these plains, I met an old centaur in a cave up north. They had clearly mastered their craft and had wisdom to spare. They helped me understand the knowledge I had gained from the Dragon Isles. If you're curious about specializing in your profession, seek out the wisdom of this master. Khadin was their name, of Clan Teerai.", ["objectivesText"] = "Seek out Master Khadin to learn their professional wisdom. Progress: Patience, young one. Rest in knowing that there is much to learn, and that is acceptable.", ["rewardGold"] = 210675, ["rewardXP"] = 2075, ["rewardItems"] = { 190456, 191784, 194714, 194729, 197860 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192574, ["x"] = 0.602, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 193110, ["x"] = 0.518, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 2022, 2023 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["campaigns"] = { { ["id"] = 191, ["title"] = "Professions Onboarding Skip", ["questLineID"] = 1364, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1364, ["name"] = "Catching Up!", ["orderIndex"] = 4, ["flags"] = 0 } } },
