[69979] = { ["id"] = 69979, ["name"] = "A Worthy Hunt", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 67100, 67137, 67295, 67564, 69946, 69979 }, ["description"] = "Wisdom is not gained. It is earned. If you wish to prove yourself worthy, you will do so in the manner of my people: learning as we act. Find and hunt Thousandmile , the Elderbull, he who has escaped the hunt for generations. From this, you will gain the wisdom you seek.", ["objectivesText"] = "Slay Thousandmile the Elderbull. Progress: Do you return victorious? A great hunt comes with great reward.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 190456, 191784, 194714, 194729, 197860, 198137 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 193110, ["x"] = 0.518, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 193110, ["x"] = 0.518, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "profession", ["campaigns"] = { { ["id"] = 191, ["title"] = "Professions Onboarding Skip", ["questLineID"] = 1364, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1364, ["name"] = "Catching Up!", ["orderIndex"] = 5, ["flags"] = 0 } } },
