[70195] = { ["id"] = 70195, ["name"] = "Taken By Storm", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "According to reports, the Nokhud were accompanied by an outsider wielding never-before-seen magic. This outsider tore through our ranks like a tempest. If the Nokhud have allies who can wreak this much havoc, we must find out as much as we can about them. I have sent my ohuna, Altan, to find this outsider. She has not flown back, and I am concerned. <name>, can you search for clues about this outsider and see what has become of Altan?", ["objectivesText"] = "Rescue Altan and search for clues about the outsider. Progress: I have my suspicions about the identity of these new Nokhud allies, but I must be sure.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 193051, 197642, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 195316, ["x"] = 0.494, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190648, ["x"] = 0.494, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 31, ["flags"] = 0 } } },
