[70197] = { ["id"] = 70197, ["name"] = "The Call of the Isles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 65436, 66577, 66589, 66596, 67700, 69911, 69912, 69914, 70050, 70122, 70123, 70124, 70125, 70197, 72240, 72293 }, ["series"] = { 67700, 70050 }, ["description"] = "Are ye ready for the adventure of a lifetime? I know I sure am! Our allies have gathered and supplies are loaded. So what're you waiting for? Meet me at the Stormwind docks. It's time to set sail for the Dragon Isles !", ["objectivesText"] = "Meet Toddy Whiskers at the Stormwind Harbor.", ["rewardGold"] = 7410, ["rewardXP"] = 175, ["rewardItems"] = { 198398, 200073, 201921, 201922, 201923, 201924 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 189077, ["x"] = 0.228, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.228, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 26, ["flags"] = 1 } } },
