[70229] = { ["id"] = 70229, ["name"] = "Boku the Mystic", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66201, 66222, 66224, 66225, 66236, 66242, 66254, 66256, 66257, 66258, 66259, 70195, 70229 }, ["description"] = "The mystics were called away to Ridgewater Retreat a few days ago, but one mystic remains. His name is Boku. He can be found on top of the hill at the Ohn'ahran shrine. He's just an initiate, but he should be able to commune with Ohn'ahra and acquire her blessing. With Ohn'ahra on our side, we might be able to win this war before it starts.", ["objectivesText"] = "Find Boku in Teerakai.", ["rewardGold"] = 7410, ["rewardXP"] = 345, ["rewardItems"] = { 193051, 198652, 198655, 198698 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187787, ["x"] = 0.418, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 186290, ["x"] = 0.368, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1305, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1305, ["name"] = "Ohn'ahra's Blessing", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 28, ["flags"] = 0 } } },
[70233] = { ["id"] = 70233, ["name"] = "Axe Shortage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70233 }, ["description"] = "A mix-up with orders resulted in a severe shortage of new axes for our explorers. We have an immediate need for more Draconium Axes and are looking for all blacksmiths to pitch in. In return, I will impart new Blacksmithing Knowledge to you to assist in making even more epic pieces.", ["objectivesText"] = "Craft 2 Draconium Axes for Metalshaper Kuroko in Valdrakken. Progress: Are you finished already?", ["rewardXP"] = 1415, ["rewardItems"] = { 190487, 198606 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185546, ["x"] = 0.37, ["y"] = 0.469333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185546, ["x"] = 0.37, ["y"] = 0.469333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.469333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 33 },
[70234] = { ["id"] = 70234, ["name"] = "All this Hammering", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70234 }, ["description"] = "The anvils have not been quiet since the Dragon Isles awoke. The anvils are doing fine, but our hammers are starting to crack. To keep up with the demand, we need to restock.", ["objectivesText"] = "Craft 2 Draconium Blacksmith's Hammers for Metalshaper Kuroko in Valdrakken. Progress: Are you finished already?", ["rewardXP"] = 1415, ["rewardItems"] = { 191237, 198606 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185546, ["x"] = 0.37, ["y"] = 0.469333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185546, ["x"] = 0.37, ["y"] = 0.469333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.469333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 33 },
