[70239] = { ["id"] = 70239, ["name"] = "Untold Regrets", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70239 }, ["description"] = "Duroz is old, sick, and stubborn as a kodo. There was no stopping him getting on the airship to come here. Best I could do was come be his walking stick. I've seen him in pain enough times on the battlefield to know when he's hiding it. He's been getting worse every day out here. Can you help me get him to the potion makers? Ale's not doing the trick anymore. If you can carry our weapons, I can help him walk.", ["objectivesText"] = "Walk with Duroz and Kolgar to find help. Progress: I wish there was more I could do.", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 200109 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 194801, ["x"] = 0.578, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 194805, ["x"] = 0.57, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70240] = { ["id"] = 70240, ["name"] = "Pain Management", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70240 }, ["description"] = "It is a good thing you brought him here when you did. I can tell he is in a great deal of pain, though he bears it well. So must we all when it comes time. I am afraid that it is age that ails him and not illness, but I may be able to relieve some portion of his suffering. Would you mind gathering some snapflowers, shallowlilies, and pure water from the garden nearby? I can create a pain medicine with these components, if you find enough.", ["objectivesText"] = "Gather 5 Milky Snapflowers , 3 Blooming Shallowlilies , and a Filled Life Pools Vial. Progress: Was the dragonspawn... willing to make anything?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198666, 198668, 198673, 200109 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 194805, ["x"] = 0.57, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 194800, ["x"] = 0.574, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70241] = { ["id"] = 70241, ["name"] = "The Bitter End", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70241 }, ["description"] = "It just happened. I--He was sleeping and I looked away and-- We came back here every day, he just wanted to sit with the whelps, I didn't know he-- <Kolgar's face is clearly tear-stained. He rubs his eyes with the back of his hand.> No, I knew. I knew. But I don't know what to do now. What do I do with him? Can you-- Can you find Bathoras ?", ["objectivesText"] = "Bring Bathoras to Duroz and Kolgar. Progress: Oh, greetings once more, <name>. I have been able to make a few more batches of that medicine with all the herbs you brought me. Duroz began refusing it earlier today, but I may be able to find other uses for it.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 194801, ["x"] = 0.578, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 194805, ["x"] = 0.57, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70242] = { ["id"] = 70242, ["name"] = "Life After Life", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70242 }, ["description"] = "I could sense that his friend bore a deep scar. Something in this place reopened it--perhaps so that it could heal cleanly this time. Now it is Kolgar's time to heal. In the terrace above us, you will find my friend Trellain working with the enchanters. Tell him that I require one of the vessels he uses in his work. He will give it to you freely.", ["objectivesText"] = "Collect an Inert Vessel from Trellain in the Ruby Lifeshrine. Progress: Were you able to find Trellain?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198701 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 194805, ["x"] = 0.57, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 194805, ["x"] = 0.57, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70244] = { ["id"] = 70244, ["name"] = "Nokhud Can Come of This", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66327, 66328, 66329, 66331, 66333, 66335, 66336, 66337, 66344, 66783, 66784, 70220, 70244 }, ["description"] = "For thousands of years, the Teerai have guarded the Horn of Drusahl, our most sacred relic. By sacking this village, Balakar has betrayed everything it means to be Maruuk. There can be no redemption for him now. We must retake the Horn before Balakar can destroy it and rescue any Teerai who yet live. I am going with you to personally bring that false Khan to justice. The Nokhud will know the wrath of the Khanam Matra!", ["objectivesText"] = "Enter the village with Khanam Matra Sarest and reclaim it from the Nokhud. Progress: There is no time to lose! We must re-take the village and defend the Horn of Drusahl!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 194549, 197375, 197653 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 188068, ["x"] = 0.7375, ["y"] = 0.4305 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188068, ["x"] = 0.7375, ["y"] = 0.4305 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.7375, ["y"] = 0.4305 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 166, ["title"] = "Ohn'ahran Plains", ["questLineID"] = 1306, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5569, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1306, ["name"] = "Bonds Renewed", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5569, ["name"] = "The Ohn'ahran Plains", ["orderIndex"] = 40, ["flags"] = 0 } } },
[70268] = { ["id"] = 70268, ["name"] = "Memories Revived", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70268 }, ["description"] = "You found a partially destroyed diary . It appears to be written from the view point of a young black dragon woman, before the corruption. While the back part of it is illegible, skimming through the first part, a name stands out to you. Veritistrasz .", ["objectivesText"] = "Give Veritistrasz the Diary. Progress: Hello young one, nice to see you again.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198661 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 194076, ["x"] = 0.578, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70279] = { ["id"] = 70279, ["name"] = "Blood of Dragons", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70279 }, ["description"] = "As you've no doubt seen, this land contains creatures which grow beyond their normal size. We consider these beasts as blessed by the gods of the wild, and they are often considered honorable targets for hunters to prove their strength. One of these beasts, which we call Karkidan , is nearby. I would be most impressed if you managed to take it down.", ["objectivesText"] = "Slay Karkidan . Progress: How goes your hunt?", ["rewardXP"] = 3455, ["rewardItems"] = { 191983, 191987, 191993, 191997, 192000, 192005, 192006, 192013 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.491667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "group" },
[70299] = { ["id"] = 70299, ["name"] = "Draconic Defensive", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70299 }, ["description"] = "I've heard words on the wind of outsiders allying with Clan Nokhud in an effort to defeat our dragon neighbors. These Primalists are a blight on the plains of our ancestors. Slay them, and bring me the cores of the elementals they command.", ["objectivesText"] = "Slay primalists in the Storm Scar. Progress: The dragons and our kin have long held peace. This threat to such cannot be ignored.", ["rewardXP"] = 2765, ["rewardItems"] = { 191984, 191986, 191989, 191991, 191992, 191995, 191997, 191999, 192003, 192006, 192007, 192008, 192011, 192020, 192030, 198539, 198542, 198691 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185867, ["x"] = 0.66, ["y"] = 0.484667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185867, ["x"] = 0.66, ["y"] = 0.484667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.484667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70319] = { ["id"] = 70319, ["name"] = "Nergazurai", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70319 }, ["description"] = "My uncle told me many tales of his battle with a hornstrider named Nergazurai. He told me of its fuchsia scales weaving through the hills of the plains as it seeks its prey, its razor-sharp talons and venomous bite. While I was out hunting I saw the flash, but it was too late; it left me with a nasty bite in my shoulder. He was as terrible as my uncle described, but I came out alive. I need to clean the infection from his bite. Please, collect the reagents I need. Time is of the essence.", ["objectivesText"] = "Bring an Ottuk Heart , a Rockfang Femur , a Hornstrider Scale , and a Vulture Gizzard to Muqur Rain-Touched in Timberstep Outpost. Progress: My fever grows worse, friend. I fear if I do not clean the infection soon, it will be the death of me.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 191127, 191143, 191541, 198792, 198793, 198794, 198795 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194904, ["x"] = 0.845, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194904, ["x"] = 0.845, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.845, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70335] = { ["id"] = 70335, ["name"] = "Simple Excavation Tools", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70335, 70807, 70808, 70809, 70810, 70812, 70813, 70814, 70815, 70817, 70818, 70819, 70820, 70821, 70822, 70828, 70831, 70832, 70833, 70834, 70835, 72023, 72024, 72025, 72026, 72032, 72033, 72034, 72035, 72036, 72037, 72038, 72039, 72040, 72041, 72042, 72043, 72044, 72045, 72046, 72047, 72048, 72294, 72295, 72299, 72300, 72301, 72302, 72303, 72304, 72305, 72306, 72308, 72309 }, ["rewardItems"] = { 198387, 198717, 198718, 199746 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188265, ["x"] = 0.478, ["y"] = 0.82 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188265, ["x"] = 0.478, ["y"] = 0.82 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.82 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1380, ["name"] = "Dragonscale Expedition Renown", ["orderIndex"] = 2, ["flags"] = 0 } } },
[70337] = { ["id"] = 70337, ["name"] = "Emberwatch", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70337 }, ["series"] = { 65890, 65891 }, ["description"] = "Hail, outsider. The winds tell me of a group taking shelter in the ruins of Emberwatch. They seem only interested in the past while we centaur choose to live for the present under the grace of Ohn'ahra. Nonetheless, they are guests in our home. I have fashioned for them these wind chimes so they may hear Ohn'ahra's presence. May it bring their hearth some joy and comfort.", ["objectivesText"] = "Bring the Ohn'ir Wind Chimes to Emberwatch. Provided item:", ["rewardGold"] = 42450, ["rewardXP"] = 690, ["rewardItems"] = { 193355, 193357, 193375, 193601, 197407, 198078, 198079, 199174 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 195239, ["x"] = 0.622, ["y"] = 0.364 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190089, ["x"] = 0.66, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70338] = { ["id"] = 70338, ["name"] = "They Took the Kits", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70338 }, ["description"] = "If Sylvie is this distressed, that must mean it's her kits that are in there! While she was infected, the giants must have kit-napped her babies and she was too weak to save them. Kits are energetic at this age, hopefully they've all been quick enough to evade the giants until now... Here, make use of my invisibility charm-- Quickly, you must save them before they're eaten!", ["objectivesText"] = "Rescue the kits.", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 197983, 198336, 198797, 200526 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 192830, ["x"] = 0.646, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 192830, ["x"] = 0.646, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.646, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[70339] = { ["id"] = 70339, ["name"] = "In Tyr's Footsteps: The Ohn'ahran Plains", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70182, 70633 }, ["description"] = "Though you have done well in your first challenge, do not think you shall surpass all so easily. Keeper Tyr meant the Engine of Innovation to be only for those worthy enough to use it wisely. If you are undeterred, the next challenge shall be found in the Ohn'ahran Plains. I look forward to testing your capabilities, adventurer.", ["objectivesText"] = "Find the Second Challenge of Tyr in the Ohn'ahran Plains.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.838, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1370, ["name"] = "Tyr's Second Challenge", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 3, ["flags"] = 0 } } },
[70341] = { ["id"] = 70341, ["name"] = "Well-Earned Victory", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70650 }, ["description"] = "The smallest of things can contain the greatest of treasures. Take the essence to the Engine of Innovation.", ["objectivesText"] = "Return to the Engine of Innovation in Valdrakken.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 195924, ["x"] = 0.662, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.554 }, ["mapCandidates"] = { ["npc"] = { 2023, 2112 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1370, ["name"] = "Tyr's Second Challenge", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 4, ["flags"] = 0 } } },
[70351] = { ["id"] = 70351, ["name"] = "Garden Party", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70351 }, ["description"] = "I've been tending to this garden for years, preparing for the day I'd finally accept my Lifecalling. Now that day is here! I love flowers and all trees and plants--even the bugs that live amongst them. I can feel nature's spirit--the Great Dragon Spirit--when I tend the garden. There's only one thing left to do. I'm going to invoke the Great Dragon Spirit, just like the legends. < Akora smiles brightly.> Meet me down in the garden by the pool where her bones rest. I'll explain more there.", ["objectivesText"] = "Speak to Akora in the Ruby Life Pools.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 193064, 193826, 193918 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191012, ["x"] = 0.618, ["y"] = 0.736 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190866, ["x"] = 0.602, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.736 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70352] = { ["id"] = 70352, ["name"] = "Scaling Ever Higher", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70352 }, ["description"] = "You there, outsider! You have killed proto dragons before, yes? So it stands to reason that your experience combined with my hunting prowess, we can take down quite a few! There are springs around here that attract draconic beasts. Help me prove to my foolish other half that I am the better hunter.", ["objectivesText"] = "Slay hornswogs and territorial proto drakes with Toluiqi . Progress: How goes the hunt?", ["rewardXP"] = 2765, ["rewardItems"] = { 191983, 191984, 191987, 191990, 191991, 191992, 191993, 191996, 191997, 191998, 191999, 192000, 192004, 192005, 192006, 192007, 192008, 192010, 192012, 192013, 192014, 192015, 192037, 193568, 198539, 198542, 198627 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185881, ["x"] = 0.706667, ["y"] = 0.522667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185881, ["x"] = 0.706667, ["y"] = 0.522667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.706667, ["y"] = 0.522667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
