[70374] = { ["id"] = 70374, ["name"] = "Himia, the Blessed", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70374 }, ["description"] = "The Elements lay claim to this land and do not welcome our intrusion. O, Elements, have you forgotten our protector--Air! Invisible, yet omnipresent and vital for all existence! Forgotten, as easy as you breathe it. After facing me, you will never forget again.", ["objectivesText"] = "Defeat the elements.", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 193202, 193206, 193207, 193483 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190950, ["x"] = 0.492, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190164, ["x"] = 0.415, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70376] = { ["id"] = 70376, ["name"] = "Second Challenge of Tyr: Might", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["description"] = "<As you approach, an inscription on the statue lights up with a faint glow.> \"Wield the Keeper's power and show the undaunted determination of one who stands strong.\"", ["objectivesText"] = "Complete the second Challenge of Tyr in the Ohn'ahran Plains.", ["rewardGold"] = 842700, ["rewardXP"] = 8200, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 195924, ["x"] = 0.662, ["y"] = 0.554 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.554 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1370, ["name"] = "Tyr's Second Challenge", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 7, ["flags"] = 0 } } },
[70377] = { ["id"] = 70377, ["name"] = "Derelict Fashion", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70377 }, ["description"] = "<A disgusting set of sunglasses is dripping with slime, but they look extremely expensive. Someone is definitely missing these. This style is very hot right now.>", ["objectivesText"] = "Find the owner of the sunglasses. Progress: I cannot possibly be seen at the VIP area without my sunglasses! You see, I grabbed a glider, and was getting some A-MAZ-ING pictures. I looked below, and saw all of these tiny elementals the size of ants! I thought, hah, ant-size elementals: what a great photo-op. But when I got there, they were at least three times the size of ants. A muddy one chased me, but I am very fast. I hate to think of what has happened to my sunglasses...", ["rewardGold"] = 561800, ["rewardXP"] = 6830, ["rewardItems"] = { 200586 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 198062, ["x"] = 0.394, ["y"] = 0.478667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.478667 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["startItems"] = { 200586 } },
