[70414] = { ["id"] = 70414, ["name"] = "Shaky Grounds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70414 }, ["description"] = "In the name of Khaz'goroth, what goes on here? This magma works with a mind of its own, consuming these elemental cavestones from below. Tis more than chance causin' this... I aim to figure it out! Place these Shattering Totems next to each trapped elemental to free them!", ["objectivesText"] = "Place the Shattering Totems to free the trapped cavestones . Progress: Have ye freed them all?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198980, 200617 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 195234, ["x"] = 0.37, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 195234, ["x"] = 0.37, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
