[70437] = { ["id"] = 70437, ["name"] = "To Tyrhold", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 65935, 65938, 65947, 65948, 65962, 66028, 66029, 66030, 66031, 66032, 66033, 66035, 66036, 66037, 66038, 66039, 66040, 66080, 66081, 66082, 66083, 66084, 66085, 66087, 66159, 66163, 66166, 66167, 66169, 66221, 66244, 66245, 66246, 66247, 66248, 66249, 66250, 66251, 66252, 66320, 66646, 66660, 66675, 66704, 66847, 67073, 70040, 70136, 70371, 70373, 70437, 72269, 72380, 72519 }, ["series"] = { 66675, 66847, 67073, 72380 }, ["description"] = "Centuries have passed since the flights last visited Tyrhold. Nevertheless, we must travel there and investigate if the Mother Oathstone still functions. Come, speak with me at the Seat of the Aspects. We must learn about the dangers we may face at Tyr's former stronghold.", ["objectivesText"] = "Meet Alexstrasza at the Seat of the Aspects. Progress: It is good to see you, <name>.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 71086, 190454, 197921, 206162 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187658, ["x"] = 0.574, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.583778, ["y"] = 0.357111 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5570, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1333, ["name"] = "The Mother Oathstone", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5570, ["name"] = "Thaldraszus", ["orderIndex"] = 48, ["flags"] = 0 } } },
[70438] = { ["id"] = 70438, ["name"] = "Flying Fish", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70438 }, ["description"] = "The fish could be biting better, don't you think? You know, that gives me an idea. Legend says these lakes and rivers did not always have fish. They say, these watering holes were stocked with fish when the dragons soaring overhead dropped them! Can you believe it? Maybe you and your drake could give it a try?", ["objectivesText"] = "Collect fish to restock the fishing hole and mount your drake to drop them from above. Progress: Have you dropped those fish yet?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 198855 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 195338, ["x"] = 0.638, ["y"] = 0.765 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 195338, ["x"] = 0.638, ["y"] = 0.765 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.765 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
