[70444] = { ["id"] = 70444, ["name"] = "The Fields of Ferocity", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70444 }, ["series"] = { 66459 }, ["description"] = "To the bravest Shikaar! Gather your best and head on over to the Fields of Ferocity . You could be crowned the fiercest of them all! Prove your might. Show us your best fight! Terms and conditions apply.", ["objectivesText"] = "Meet Gurgthock at the Fields of Ferocity .", ["rewardGold"] = 42450, ["rewardXP"] = 690, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188868, ["x"] = 0.53, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "group" },
[70446] = { ["id"] = 70446, ["name"] = "A Personal History", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70446 }, ["description"] = "In delving into the archives here, I've found threads that point towards the Obsidian Observatory as a place of personal importance to the Earth-Warder. I can only guess what knowledge it may contain about the history of our flight. Given Emberthal's interest in the subject, I informed her of my discovery. I pray that wasn't a mistake. She has gone ahead to scout. Please, keep an eye on her. She is a competent soldier, but this subject is... troubling. Who knows what truths you may uncover.", ["objectivesText"] = "Meet Emberthal at the Obsidian Observatory.", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193456, ["x"] = 0.25, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 196253, ["x"] = 0.446, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.25, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70450] = { ["id"] = 70450, ["name"] = "Otter Devastation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70450 }, ["description"] = "Hey there, friend. These here ottuks keep stealin' my catch! Personally, I'd blow 'em up, but our Tuskarr friends don't seem too keen on that action. I made this here Ottuk Deterent Device MK-SH4RK, but... I aint a great swimmer. You seem like you got the goods, why don't ya do us all a favor, activate the device, swimmy-swim around over there, and scare 'em off?", ["objectivesText"] = "Scare off the Pesky Ottuks. You may unlock only one extra fishing net per day. Progress: You get rid of them pesky ottuks yet?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 85500, 133755, 194701 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 195444, ["x"] = 0.636, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 195444, ["x"] = 0.636, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.636, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70501] = { ["id"] = 70501, ["name"] = "License to Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70501 }, ["description"] = "Ah, finally ready to prove yourself as a hunter? Keep in mind this is not as simple as running around and hunting everything that moves. The Shikaar hunt with purpose. We hunt to feed and clothe the clan, to prove our strength against mighty foes, and to balance nature. We do not hunt the land barren, we sow the seeds for future Grand Hunts as we go. Prove yourself capable of following these instructions and you may join us. However I do not have confidence in your friend there succeeding.", ["objectivesText"] = "Complete the Grand Hunt training tasks. Progress: Have you completed your training?", ["rewardGold"] = 280900, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 195454, ["x"] = 0.64, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 195454, ["x"] = 0.64, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70502] = { ["id"] = 70502, ["name"] = "Clearing the Skies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["mapID"] = 2022, ["storyline"] = { 70502 }, ["objectivesText"] = "Kill Insects", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Kill Insects", ["amount"] = 50, ["type"] = 0, ["objectID"] = 189803, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[70503] = { ["id"] = 70503, ["name"] = "The Vigilance of Tyr", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66012, 66013, 66094, 66128, 66673, 66814, 69093, 70503, 70507, 70784, 70785 }, ["description"] = "Bodies, broken gear, uncontrolled titan energy. What a disregard for safety, and... and protocol! It looks like they found the stone and it was unstable, bursting into pieces. Fortunately, I'm particularly adept at repairing magical devices. But before I can reform the stone we need to collect each and every piece.", ["objectivesText"] = "Recover the fragments of the stone. Progress: I can't believe it. It's all here! Well done.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 193070, 193072, 200471, 200473, 200474, 200478, 200480 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 193350, ["x"] = 0.538, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 193350, ["x"] = 0.538, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1331, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1331, ["name"] = "A Mystery, Sealed", ["orderIndex"] = 5, ["flags"] = 0 } } },
[70507] = { ["id"] = 70507, ["name"] = "The Insight of Tyr", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66012, 66013, 66094, 66128, 66673, 66814, 69093, 70503, 70507, 70784, 70785 }, ["description"] = "Did ya see Szar Skeleth on your way in? It's that ruined tower to the northeast. We've got a bit of a good news, bad news situation there. The good news is the stone's already been found. Bad news is it was found by the Sundered Flame, specifically a magic-using dracthyr named Makko. And they're using it to control gorlocs. Did I mention the dracthyr's misuse of the stone drove them mad? Well, good luck!", ["objectivesText"] = "Recover the Insight of Tyr . Progress: Turns out gorlocs don't make for good bodyguards, eh? I wonder how dangerous she could've been if she held on to her sanity.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 193070, 193072, 200471, 200473, 200474, 200478, 200480 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 191159, ["x"] = 0.4, ["y"] = 0.674 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 191159, ["x"] = 0.4, ["y"] = 0.674 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.674 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 197, ["title"] = "Dragonscale Expedition", ["questLineID"] = 1331, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1331, ["name"] = "A Mystery, Sealed", ["orderIndex"] = 7, ["flags"] = 0 } } },
[70509] = { ["id"] = 70509, ["name"] = "Third Challenge of Tyr: Persistence", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70621 }, ["description"] = "<It seems those who have reawakened with the Isles have not been kind to Keeper Tyr's creations. Perhaps finding the missing pieces of the statue would help.>", ["objectivesText"] = "Retrieve missing parts and repair the broken statue. Progress: <As you approach, you can feel the warmth of Titan's energy flowing through the statue once more.>", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 190453, 198982, 198983, 198984, 199197, 200108, 200120 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 195737, ["x"] = 0.64, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1371, ["name"] = "Tyr's Third Challenge", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 8, ["flags"] = 0 } } },
[70510] = { ["id"] = 70510, ["name"] = "Victorious", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70881, 70899, 70900 }, ["description"] = "Once again I ask you to bring this essence to the Engine of Innovation.", ["objectivesText"] = "Return to the Engine of Innovation in Valdrakken.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 160335, 160338, 160341, 160344, 160373, 160376, 160379, 160382, 190453, 198982, 198983, 198984, 199197, 200108, 200120, 211279 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 195737, ["x"] = 0.64, ["y"] = 0.414 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 9, ["flags"] = 0 } } },
