[70530] = { ["id"] = 70530, ["name"] = "Examination Week", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70530 }, ["description"] = "The students at Algeth'ar Academy ran out of solutions... again. Forgive me for asking, but could you gather more Dragon's Alchemical Solution so they can continue their studies?", ["objectivesText"] = "Craft 5 Dragon's Alchemical Solution using the Reclaim Concoctions recipe for Conflago in Valdrakken. Progress: The students are getting impatient.", ["rewardXP"] = 1415, ["rewardItems"] = { 191570, 198608 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185545, ["x"] = 0.365, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185545, ["x"] = 0.365, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 38 },
[70531] = { ["id"] = 70531, ["name"] = "Mana Markets", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70531 }, ["description"] = "Demand for mana potions has increased dramatically this week, $p. I will need your assistance filling customers' orders. Surely as a skilled alchemist you can spare a few, yes?", ["objectivesText"] = "Craft 10 Aerated Mana Potions for Conflago in Valdrakken. Progress: Our customers are waiting.", ["rewardXP"] = 1415, ["rewardItems"] = { 191386, 198608 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185545, ["x"] = 0.365, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185545, ["x"] = 0.365, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 38 },
[70532] = { ["id"] = 70532, ["name"] = "Aiding the Raiding", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70532 }, ["description"] = "Oh $p, I am glad to see you. Several champions have been injured in the latest assault against the Primalists. We are greatly in need of healing potions. As an adventurer yourself, I imagine you have several on hand already. We will need many.", ["objectivesText"] = "Craft 10 Refreshing Healing Potions for Conflago in Valdrakken. Progress: Every moment you waste, the Primalists grow stronger.", ["rewardXP"] = 1415, ["rewardItems"] = { 191380, 198608 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185545, ["x"] = 0.365, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185545, ["x"] = 0.365, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 38 },
[70533] = { ["id"] = 70533, ["name"] = "Draught, Oiled Again", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70533 }, ["description"] = "Did you know that Writhefire Oil is an excellent reagent for finishing your draughts? I did. And now I am out of it. I cannot work without a plentiful stock of oils. Please $p, help me restock my laboratory.", ["objectivesText"] = "Craft 6 Writhefire Oils for Conflago in Valdrakken. Progress: A craft without Writhefire Oil is like a dish without salt.", ["rewardXP"] = 1415, ["rewardItems"] = { 191519, 198608 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185545, ["x"] = 0.365, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185545, ["x"] = 0.365, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 38 },
[70539] = { ["id"] = 70539, ["name"] = "And You Thought They Did Nothing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70539 }, ["description"] = "Hey sparky, you know what everyone forgets they need when they're flying around on dragons? Goggles. You know what we sold out of today? Goggles. You know what I need from you right now? You guessed it!", ["objectivesText"] = "Craft 2 Milestone Magnifiers for Clinkyclick Shatterboom in Valdrakken. Progress: <Clinkyclick is muttering to herself as she looks for something.>", ["rewardXP"] = 1415, ["rewardItems"] = { 198329, 198611 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185548, ["x"] = 0.422, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185548, ["x"] = 0.422, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 35 },
[70540] = { ["id"] = 70540, ["name"] = "An Engineer's Best Friend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70540 }, ["description"] = "Hey sparky, have you seen my... Err... maybe hand me the... That's it--I think it's time we start keeping a few more tools around this shop, you know what I'm saying?", ["objectivesText"] = "Craft 2 Draconium Encased Samophlanges for Clinkyclick Shatterboom in Valdrakken. Progress: <Clinkyclick is muttering to herself as she looks for something.>", ["rewardXP"] = 1415, ["rewardItems"] = { 198245, 198611 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185548, ["x"] = 0.422, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185548, ["x"] = 0.422, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 35 },
[70541] = { ["id"] = 70541, ["name"] = "Hunting Tactics: Companion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2022, ["storyline"] = { 70541 }, ["description"] = "Your renown with the Maruuk grows. You may now hunt alongside a tenacious bakar or swift ohuna companion.", ["objectivesText"] = "Choose to fight alongside a bakar or ohuna during the Grand Hunt.", ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192926, ["x"] = 0.518, ["y"] = 0.765 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192926, ["x"] = 0.518, ["y"] = 0.765 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.765 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
