[70545] = { ["id"] = 70545, ["name"] = "Blingtron 8000...?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70545 }, ["description"] = "Hey sparky, I've got a secret project going on. People are going to go wild! But I've run out of the basics.... You wanna be a pal and get me some bolts?", ["objectivesText"] = "Craft 10 Handfuls of Serevite Bolts for Clinkyclick Shatterboom in Valdrakken. Progress: <Clinkyclick is muttering to herself as she looks for something.>", ["rewardXP"] = 1415, ["rewardItems"] = { 198185, 198611 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185548, ["x"] = 0.422, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185548, ["x"] = 0.422, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 35 },
[70549] = { ["id"] = 70549, ["name"] = "Low Hanging Fruit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70549 }, ["objectivesText"] = "Kill a stagbeetle to take its plums Honey plums collected", ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13645 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Kill a stagbeetle to take its plums", ["amount"] = 1, ["type"] = 0, ["objectID"] = 195709, ["orderIndex"] = 0 }, { ["text"] = "Honey plums collected", ["amount"] = 25, ["type"] = 0, ["objectID"] = 195601, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[70550] = { ["id"] = 70550, ["name"] = "Welcome to the Assembly", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70550 }, ["description"] = "We could use your aid. The Sundered Flame have taken control over most of the Cobalt Assembly. Please help us in this fight against them. Our numbers are small, but there are a few things we can do to aid you.", ["objectivesText"] = "Speak with Xavin within the Cobalt Assembly to see what abilities are available within the area. Progress: We can use all the help we can get.", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["rewardItems"] = { 194261, 202117, 202118, 202119 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194680, ["x"] = 0.49, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194680, ["x"] = 0.49, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[70557] = { ["id"] = 70557, ["name"] = "No Scopes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70557 }, ["description"] = "Great gadgets, sparky, do I have a big one for you today! Apparently, some firework fad caught on with the hunters. They try setting them off to scare the ducks into the air. Bet the ducks are way to smart for that, but it won't stop us from profiting! Think you're up to the task?", ["objectivesText"] = "Craft 15 Bronze Fireflight for Clinkyclick Shatterboom in Valdrakken. Progress: <Clinkyclick is muttering to herself as she looks for something.>", ["rewardXP"] = 1415, ["rewardItems"] = { 198550, 198611 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185548, ["x"] = 0.422, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185548, ["x"] = 0.422, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 35 },
[70558] = { ["id"] = 70558, ["name"] = "Disillusioned Illusions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70558 }, ["description"] = "My scribe apprentice, you could not have chosen better timing. There has been a terrible accident! All of the Illusion Parchment I ordered turned out to be real! Can you believe it! Do they think this is some game? Someone might get hurt! Do you think you could rectify this situation and create some real illusions?", ["objectivesText"] = "Craft 5 Illusion Parchment: Spell Shield for Talendara in Valdrakken. Progress: Have you inscribed what I need?", ["rewardXP"] = 1415, ["rewardItems"] = { 194737, 198607 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185540, ["x"] = 0.3868, ["y"] = 0.7324 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185540, ["x"] = 0.3868, ["y"] = 0.7324 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3868, ["y"] = 0.7324 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
[70559] = { ["id"] = 70559, ["name"] = "Quill You Help?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70559 }, ["description"] = "My scribe apprentice, I am delighted to see you. Earlier today I had a few novices come in to try their hand at inscription. They all wrote with too much force and snapped their quill nibs right off! I hate to ask, but could you craft a few more quills to keep in stock?", ["objectivesText"] = "Craft 2 Scribe's Fastened Quill for Talendara in Valdrakken. Progress: Have you fresh quills for my apprentices?", ["rewardXP"] = 1415, ["rewardItems"] = { 194874, 198607 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185540, ["x"] = 0.3868, ["y"] = 0.7324 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185540, ["x"] = 0.3868, ["y"] = 0.7324 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3868, ["y"] = 0.7324 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
[70560] = { ["id"] = 70560, ["name"] = "The Most Powerful Tool: Good Documentation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70560 }, ["description"] = "My scribe apprentice, do you feel ready for writing today? The Dragonscale Expedition has brought copious notes from their adventures, and they have asked that we compile their chicken-scratch penmanship into a suitable compendium for field-ready review. And oh, my hand is simply not up for the task today. Could I rely on you once more?", ["objectivesText"] = "Craft 2 Core Explorer's Compendiums for Talendara in Valdrakken. Progress: Have you inscribed the compendiums?", ["rewardXP"] = 1415, ["rewardItems"] = { 194877, 198607 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185540, ["x"] = 0.3868, ["y"] = 0.7324 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185540, ["x"] = 0.3868, ["y"] = 0.7324 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3868, ["y"] = 0.7324 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
[70561] = { ["id"] = 70561, ["name"] = "A Scribe's Tragedy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70561 }, ["description"] = "My scribe apprentice! It is awful, just terrible! I cannot fathom how I am to go on in my life! < Talendara begins weeping.> ...I have run out of ink! Could you please bottle some more?", ["objectivesText"] = "Craft 5 Blazing Ink for Talendara in Valdrakken. Progress: Have you bottled the ink?", ["rewardXP"] = 1415, ["rewardItems"] = { 194846, 198607 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185540, ["x"] = 0.3868, ["y"] = 0.7324 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185540, ["x"] = 0.3868, ["y"] = 0.7324 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3868, ["y"] = 0.7324 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
[70562] = { ["id"] = 70562, ["name"] = "The Plumbers, Mason", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70562 }, ["description"] = "Jewelcrafter, how would you feel about a chance to practice your prospecting techniques? The architects and plumbers of the Dragonscale Expedition have requested that we acquire some stones for the construction of a new bath house. I think you will find this a suitable task to occupy you and practice your masonry.", ["objectivesText"] = "Craft 15 Crumbled Stones for Tuluradormi in Valdrakken. Progress: Do you have the stones?", ["rewardXP"] = 1415, ["rewardItems"] = { 192880, 198612 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 190094, ["x"] = 0.405, ["y"] = 0.6115 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 190094, ["x"] = 0.405, ["y"] = 0.6115 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.6115 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 43 },
[70563] = { ["id"] = 70563, ["name"] = "The Exhibition", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70563 }, ["description"] = "Oh jewelcrafter, how would you feel about a chance to practice your gemcutting? I was going to put on a display of various cuts, and I suppose I could exhibit your gems as well, so long as you hurry. Submit nothing less than the highest quality for this demonstration.", ["objectivesText"] = "Craft a variety of gems for Tuluradormi in Valdrakken. Progress: Are your gems worthy of display?", ["rewardXP"] = 1415, ["rewardItems"] = { 192902, 192905, 192908, 192912, 198612 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 190094, ["x"] = 0.405, ["y"] = 0.6115 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 190094, ["x"] = 0.405, ["y"] = 0.6115 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.6115 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 43 },
[70564] = { ["id"] = 70564, ["name"] = "Spectacular", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70564 }, ["description"] = "Jewelcrafter, there is an exhibition coming up, and I am concerned that the clients will not be able to see the beauty of each cut without the proper lenses. You do not need anything fancy. Just make a few loupes so our customers can see clearly.", ["objectivesText"] = "Craft 2 Sundered Onyx Loupes for Tuluradormi in Valdrakken. Progress: Do you have the loupes?", ["rewardGold"] = 561800, ["rewardXP"] = 1415, ["rewardItems"] = { 193037, 198612 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 190094, ["x"] = 0.405, ["y"] = 0.6115 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 190094, ["x"] = 0.405, ["y"] = 0.6115 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.6115 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 43 },
[70565] = { ["id"] = 70565, ["name"] = "Separation by Saturation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70565 }, ["description"] = "Oh jewelcrafter, do you like my necklace? Of course you do. But I cannot show it off properly unless it stands out. I know! Why don't you make a few simple pendants and we shall flood the market. Once everyone is wearing your designs, my necklace will be a sparkling cut above the rest!", ["objectivesText"] = "Craft 2 Pendants of Impending Perils for Tuluradormi in Valdrakken. Progress: Do you have the pendants?", ["rewardXP"] = 1415, ["rewardItems"] = { 192996, 198612 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 190094, ["x"] = 0.405, ["y"] = 0.6115 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 190094, ["x"] = 0.405, ["y"] = 0.6115 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.6115 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 43 },
[70567] = { ["id"] = 70567, ["name"] = "When You Give Bakar a Bone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70567 }, ["description"] = "I had some of the most beautiful bonewrought bows, but our bakar got to them before they could be put to use. Bakar love to chew bones, whether bow or not, and now they are ruined! Can you aid me in crafting replacements?", ["objectivesText"] = "Craft 2 Bonewrought Crossbows for Hideshaper Koruz in Valdrakken. Progress: I will be far more wary of the bakar when next I carry these.", ["rewardXP"] = 1415, ["rewardItems"] = { 193383, 194859, 198613 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185551, ["x"] = 0.285333, ["y"] = 0.611333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185551, ["x"] = 0.285333, ["y"] = 0.611333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.285333, ["y"] = 0.611333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 44 },
[70568] = { ["id"] = 70568, ["name"] = "Tipping the Scales", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70568 }, ["description"] = "Our scale bracers are finely crafted and highly in demand. I am finding it difficult to keep up with all of the orders! Would you lend your skill in replenishing my supply?", ["objectivesText"] = "Craft 2 Trailblazer's Scale Bracers for Hideshaper Koruz in Valdrakken. Progress: Our goods are of the finest quality and craftsmanship. I am not surprised they sell so quickly.", ["rewardXP"] = 1415, ["rewardItems"] = { 193393, 198613 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185551, ["x"] = 0.285333, ["y"] = 0.611333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185551, ["x"] = 0.285333, ["y"] = 0.611333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.285333, ["y"] = 0.611333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 44 },
[70569] = { ["id"] = 70569, ["name"] = "For Trisket, a Task Kit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70569 }, ["description"] = "I have many valued customers, but Trisket is one of my favorites. Most recently he came to me because his herbalist's pouch has worn out. I offered to make him a selection of baskets to replace his old pouch. Would you help me with these tasks, $p? Trisket would be appreciative.", ["objectivesText"] = "Craft 2 Herbalist's Floral Baskets for Hideshaper Koruz in Valdrakken. Progress: I think Trisket will be far happier with these sturdy baskets.", ["rewardXP"] = 1415, ["rewardItems"] = { 193479, 198613 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185551, ["x"] = 0.285333, ["y"] = 0.611333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185551, ["x"] = 0.285333, ["y"] = 0.611333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.285333, ["y"] = 0.611333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 44 },
[70571] = { ["id"] = 70571, ["name"] = "Drums Here!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70571 }, ["description"] = "We are known far and wide for our drums--the centaur have been honing these skills for generations. Unfortunately this means that our drums are in short supply these days. You have skills of your own, I see. Perhaps you could help me craft a few drums for our stores?", ["objectivesText"] = "Craft 2 Feral Hide Drums for Hideshaper Koruz in Valdrakken. Progress: Your skills are quite impressive--where did you learn to craft?", ["rewardXP"] = 1415, ["rewardItems"] = { 193208, 193216, 193470, 198613 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185551, ["x"] = 0.285333, ["y"] = 0.611333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 185551, ["x"] = 0.285333, ["y"] = 0.611333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.285333, ["y"] = 0.611333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 44 },
[70572] = { ["id"] = 70572, ["name"] = "The Cold Does Bother Them, Actually", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70572 }, ["description"] = "If there is one thing I have learned in my years as a seamstress, $p, it is that adventurers will always underestimate the cold. I have explorers in the Azure Span begging me for warmer robes. Would you take pity on them and craft a few?", ["objectivesText"] = "Craft 2 Surveyor's Cloth Robes for Fulafong in Valdrakken. Progress: Do you have the robes?", ["rewardXP"] = 1415, ["rewardItems"] = { 193515, 198609 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 193649, ["x"] = 0.316, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 193649, ["x"] = 0.316, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.316, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 37 },
[70582] = { ["id"] = 70582, ["name"] = "Weave Well Enough Alone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70582 }, ["description"] = "If there is one thing I have learned in my years as a seamstress, $p, it is the importance of practice. Always be practicing your craft, even when you believe you have mastered everything. I want you to be able to weave with excellence without my supervision. Why don't you practice this week? Make a few Wildercloth Bolts at the highest quality.", ["objectivesText"] = "Craft 3 Wildercloth Bolts for Fulafong in Valdrakken. Progress: Do you have the bolts?", ["rewardXP"] = 1415, ["rewardItems"] = { 193928, 198609 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 193649, ["x"] = 0.316, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 193649, ["x"] = 0.316, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.316, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 37 },
[70586] = { ["id"] = 70586, ["name"] = "Sew Many Cooks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70586 }, ["description"] = "If there is one thing I have learned in my years as a seamstress, $p, it is that too many cooks spoil everything. In this case, I was going to go out for a drink and an order came in last minute for an entire wardrobe of chef's uniforms. If you could sew the hats, I will take care of everything else.", ["objectivesText"] = "Craft 2 Wildercloth Chef's Hats for Fulafong in Valdrakken. Progress: Do you have the chef's hats?", ["rewardXP"] = 1415, ["rewardItems"] = { 193534, 198609 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 193649, ["x"] = 0.316, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 193649, ["x"] = 0.316, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.316, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 37 },
[70587] = { ["id"] = 70587, ["name"] = "A Knapsack Problem", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70587 }, ["description"] = "If there is one thing I have learned in my years as a seamstress, $p, it is that you can never have enough space for your reagents. In fact, we could use a few more bags around here to hold everything. Would you mind stitching another?", ["objectivesText"] = "Craft 1 Simply Stitched Reagent Bag for Fulafong in Valdrakken. Progress: Do you have the bag?", ["rewardXP"] = 1415, ["rewardItems"] = { 194019, 198609 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 193649, ["x"] = 0.316, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 193649, ["x"] = 0.316, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.316, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 37 },
