[70619] = { ["id"] = 70619, ["name"] = "A Study of Leather", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70619 }, ["description"] = "You there! Perhaps you can help me with my studies of this leather. Some of it is soft and pliable, yet other pieces have a more firm temper--the better for crafting armor, I suspect. Bring me more leathers to investigate. I wish to continue my studies.", ["objectivesText"] = "Gather 40 Resilient Leather for Ralathor the Rugged in Valdrakken. Progress: Were you able to find any leather to study?", ["rewardXP"] = 1415, ["rewardItems"] = { 193210, 199128 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 193846, ["x"] = 0.2855, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 193846, ["x"] = 0.2855, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.2855, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 36 },
[70620] = { ["id"] = 70620, ["name"] = "Scaling Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70620 }, ["description"] = "Many people ask me how I became so good at skinning. To them I say: it is all in the scales. Are you curious to learn more? Bring me some scales, and I will show you what I mean.", ["objectivesText"] = "Gather 40 Adamant Scales for Ralathor the Rugged in Valdrakken. Progress: Have you found any worthy scales?", ["rewardXP"] = 1415, ["rewardItems"] = { 191983, 191984, 191987, 191990, 191991, 191992, 191993, 191996, 191997, 191998, 191999, 192000, 192004, 192005, 192006, 192007, 192008, 192010, 192012, 192013, 192014, 192015, 192037, 193214, 193568, 198539, 198542, 198627, 199128 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 193846, ["x"] = 0.2855, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 193846, ["x"] = 0.2855, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.2855, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 36 },
[70621] = { ["id"] = 70621, ["name"] = "Third Challenge of Tyr: Persistence Embodied", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70180, 70181, 70182, 70339, 70341, 70376, 70509, 70510, 70621, 70633, 70650, 70845, 70881, 70899, 70900, 72783 }, ["series"] = { 70509 }, ["description"] = "Your third challenge was meant to have you overcome unfavorable odds. It was to help show me your persistence in all matters. I believe fighting djaradin and fixing my statue with the expectation that I would issue you a challenge is more than sufficient to fulfill your victory condition. <You think you catch a small smile play across her lips.>", ["objectivesText"] = "Accept the Bottled Essence from Maiden of Inspiration .", ["rewardGold"] = 24100, ["rewardXP"] = 685, ["rewardItems"] = { 199197 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 195737, ["x"] = 0.64, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 198, ["title"] = "Catching Up!", ["questLineID"] = 1375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1371, ["name"] = "Tyr's Third Challenge", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1375, ["name"] = "Professions Quest", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 1390, ["name"] = "The Spark of Ingenuity", ["orderIndex"] = 10, ["flags"] = 0 } } },
