[70627] = { ["id"] = 70627, ["name"] = "What of the Winterpelt Clan?", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70627 }, ["description"] = "We could join another clan... if we knew it to be safe. I worry the Primalists tempted other clans as they did ours. This \"Dragonscale Expedition\" tells me they have a clawhold near the Winterpelt clan. They may be tainted. Or they may heed our warning. With either truth, they need us. There is a \"furbolg expert,\" Sonova Snowden , in Theron's Watch. Please go to him and learn what he knows.", ["objectivesText"] = "Meet Sonova Snowden at Theron's Watch.", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191123, ["x"] = 0.632, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189401, ["x"] = 0.654, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
