[70640] = { ["id"] = 70640, ["name"] = "WANTED: Boss", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["storyline"] = { 70640 }, ["description"] = "<The page's script glows with a soft blue light.> Previously a cherished plaything of Malygos, the elemental Frigellus suffered from his master's neglect. While this once-happy settlement crumbled apace, the churlish and playful creature grew warped and twisted by the evils that plague this land. Please see that it is safely neutralized. Bring word of your success to Custodian Cynegos.", ["objectivesText"] = "Kill Frigellus near Camp Antonidas.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "standard" },
