[70697] = { ["id"] = 70697, ["name"] = "An Expert Opinion", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70647, 70697, 70722, 70732, 70849, 70851, 70853, 70854 }, ["description"] = "Lubbins' wounds may have healed, but I am afraid his confidence may still be injured. I believe it is time to call on others for help. Far to the southwest in a remote section of the Azure Span there is a pet trainer named Patchu . She is one of the world's foremost experts on these matters. Please visit her, I am sure she can help Lubbins!", ["objectivesText"] = "Talk to Patchu in The Azure Span.", ["rewardItems"] = { 92683, 116421, 122457, 163036, 199175, 200519 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 185563, ["x"] = 0.105, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196069, ["x"] = 0.138, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.105, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 2024, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1366, ["name"] = "Born to Be Wilder", ["orderIndex"] = 1, ["flags"] = 0 } } },
