[70766] = { ["id"] = 70766, ["name"] = "The Fractured Flame", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70766 }, ["description"] = "The gorloc clutches a journal, its cover marred by moisture and lack of care. The faded symbol of the Sundered Flame peeks proudly from behind the tears and discoloration. If you find the missing pages, perhaps you can gain insight into Reclaimer Makko and the madness that has fractured her mind.", ["objectivesText"] = "Collect the pages of Makko's Journal from gorlocs in Szar Skeleth. Progress: A journal? Written by who?", ["rewardItems"] = { 199792, 199793, 199794, 199795, 199796, 199797, 200295 }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 191159, ["x"] = 0.4, ["y"] = 0.674 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.674 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["startItems"] = { 199790, 203598 } },
