[70883] = { ["id"] = 70883, ["name"] = "A Hand in Cultivation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70839, 70880, 70882, 70883, 70885, 70887, 70888, 70889, 70891, 70892, 70895, 70896, 70897, 70901, 70902, 70903, 70904, 70905, 70909, 70910, 70911, 70912, 70913, 70914, 70915, 70916, 72282, 72283, 72284, 72329, 72330, 72331, 72332, 72333, 72334, 72335, 72336, 72372, 72669, 72671, 72672, 72673, 72682, 72685, 72687, 72688, 72689, 72690, 72691, 72692, 72693, 72694, 72695, 72696, 72697, 72698, 72701, 72702, 72703 }, ["description"] = "Greetings mortal, I have word from our Head Gardener Gryrmpech . The word is that the gardens are in a state of chaos, but I don't know if that is abnormal. They assured me that they have it in hand--actually, 'in shovel' is the phrase they used. I am not sure what they are meaning; I am sure they will fill you in. Please, seek them out and they will outfit you appropriately for the situation.", ["objectivesText"] = "Seek out Gryrmpech in the Gardens of Unity.", ["rewardItems"] = { 199647, 199651, 199652, 199653, 199654 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 193015, ["x"] = 0.58, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1383, ["name"] = "Valdrakken Accord Renown", ["orderIndex"] = 6, ["flags"] = 0 } } },
