[70937] = { ["id"] = 70937, ["name"] = "What Valthrux Once Was", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70937 }, ["description"] = "< To'tik whispers to you.> I don't like this. Mysterious artifacts whispering promises of greatness does not sound good. But we can't just walk away... otherwise the Sundered Flame will get their hands on it. Whatever \"it\" is... I'm familiar with ruins like this. The blue dragons often left behind notes on their work. Keep your eyes open, and you may find some around. We can use whatever evidence you find to warn Alia and Kattigat.", ["objectivesText"] = "Find clues regarding what the artifact Valthrux really is. Progress: Did you find anything useful in the ruins?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 194747, 195468, 199928, 200067, 200110 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 191715, ["x"] = 0.672, ["y"] = 0.444 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 191715, ["x"] = 0.672, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[70938] = { ["id"] = 70938, ["name"] = "Community Feasts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70938 }, ["description"] = "There you are, <name>! The soup's on! You better hurry up and get to Iskaara. Big Kinook has been looking for you. One time he told me to get a slimy, icky spinefish for the soup and I didn't want to, so I yelled: \"No, chef!\" He was so mad I thought he was going to throw me in the soup!", ["objectivesText"] = "Speak to Big Kinook at Iskaara in The Azure Span.", ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 197631, ["x"] = 0.455, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186126, ["x"] = 0.134667, ["y"] = 0.485333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.554 }, ["mapCandidates"] = { ["npc"] = { 2024, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
