[70970] = { ["id"] = 70970, ["name"] = "Good Intentions", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70970 }, ["description"] = "I may know where the artifact is. Alia was whispering frantically when you brought all the shards back. She kept saying something about a \"cave\" and how the spiders seemed attracted to it. There's no cave in the area in front of us... which leads me to believe there might be one deeper in the ruins. We'll stay here and keep your escape path open, <name>. Please save Alia and destroy this cursed artifact.", ["objectivesText"] = "Stop Alia Sunsoar and destroy the artifact Valthrux . Progress: Let's hope this works...", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 194747, 195468, 199928, 200067, 200110, 201290, 201292, 201293 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196520, ["x"] = 0.672, ["y"] = 0.444 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196520, ["x"] = 0.672, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
