[70975] = { ["id"] = 70975, ["name"] = "Wanted: Everblazing Fireheart", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70975 }, ["description"] = "<The posted sign is written in beautiful calligraphy.> The archivists humbly request that all expedition members seek out the Everblazing Fireheart for our artifact archives. If acquired, please deliver to Cataloger Jakes for processing and compensation. Some expedition members have reported seeing a massive fire elemental under control of the Primalists in the north that may provide an opportunity to acquire one.", ["objectivesText"] = "Find the Everblazing Fireheart . Progress: Do you have something for the archives?", ["rewardItems"] = { 190454, 191984, 191987, 191988, 191990, 191993, 191994, 191996, 191997, 191998, 191999, 192000, 192002, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192019, 192037, 198490, 198529, 198532, 198695, 200119, 205423, 209837, 217242 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70976] = { ["id"] = 70976, ["name"] = "Slacking and Sledding", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70871, 70936, 70939, 70940, 70941, 70942, 70943, 70944, 70945, 70948, 70950, 70952, 70953, 70954, 70955, 70956, 70959, 70960, 70961, 70962, 70963, 70964, 70966, 70967, 70968, 70969, 70971, 70972, 70976, 70977, 70978, 72279, 72280, 72281, 72291, 72292, 72318, 72319, 72320, 72321, 72322, 72323, 72324, 72325, 72326, 72327, 72385, 72386, 72387, 72388, 72389, 72390, 72391, 72392, 72393, 72394, 72395, 72584, 72632, 72633, 72634, 72635, 72636, 72637, 72638, 72639, 72640, 72641, 72642, 72875 }, ["description"] = "As you may know, the children of Iskaara are fiercely independent. They learn from a young age to fend for themselves. It's a rite of passage for many of the older kids to sneak off to the iceberg southeast of here. Kiopo , the eldest of our children, is out there right now. Tell him I sent you, and he should offer you one of our sleds! Ah, that reminds me of my younger days... out there with my friends...", ["objectivesText"] = "Seek out Kiopo on the island to the southeast.", ["rewardItems"] = { 198827, 199899 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 193006, ["x"] = 0.13, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194318, ["x"] = 0.244, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.13, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1382, ["name"] = "Iskaara Tuskarr Renown", ["orderIndex"] = 60, ["flags"] = 0 } } },
