[70978] = { ["id"] = 70978, ["name"] = "Dragon Isles Champion's Tales", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70871, 70936, 70939, 70940, 70941, 70942, 70943, 70944, 70945, 70948, 70950, 70952, 70953, 70954, 70955, 70956, 70959, 70960, 70961, 70962, 70963, 70964, 70966, 70967, 70968, 70969, 70971, 70972, 70976, 70977, 70978, 72279, 72280, 72281, 72291, 72292, 72318, 72319, 72320, 72321, 72322, 72323, 72324, 72325, 72326, 72327, 72385, 72386, 72387, 72388, 72389, 72390, 72391, 72392, 72393, 72394, 72395, 72584, 72632, 72633, 72634, 72635, 72636, 72637, 72638, 72639, 72640, 72641, 72642, 72875 }, ["rewardItems"] = { 201471 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186448, ["x"] = 0.124, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186448, ["x"] = 0.124, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.124, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1382, ["name"] = "Iskaara Tuskarr Renown", ["orderIndex"] = 35, ["flags"] = 0 } } },
[70979] = { ["id"] = 70979, ["name"] = "Magmaton", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70979 }, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["db2VignetteID"] = 5116, ["db2VignetteName"] = "Magmaton" },
[70981] = { ["id"] = 70981, ["name"] = "Savory Seas", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70981 }, ["description"] = "The smell of the sea! Do you smell it, <name>? Do you smell the multitude of minerals, laden with thick sea salt? Do you?? Suspiciously absent from the delights here today is a rare variety of fish I once tasted near the Iskaara's home in Azure Span. Two Tuskarr fellows were simply roasting one over a fire, and it filled that glacial tundra with the most savory aroma! See if you can not find one for us. I know our patrons will be just as ensorcelled by the sea's flavor as I was that day.", ["objectivesText"] = "Speak with Wayun in Whaler's Nook of the Azure Span.", ["rewardGold"] = 42450, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186212, ["x"] = 0.074, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.115 }, ["mapCandidates"] = { ["npc"] = { 2024, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
