[71141] = { ["id"] = 71141, ["name"] = "Gills with Gall", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 71141 }, ["description"] = "Kad'irsza is reckless, but she knows her crabs. The gorlocs have gone too far! I noticed the gorlocs going to Gurblbrblr for everything. Notably, he is instructing them to take crabs prisoner. We cannot allow this to continue, for the balance of life, and for the safety of those who tend it. Defeat Gurblbrblr. Remove their means of expanding beyond this river!", ["objectivesText"] = "Kill Gurblbrblr the Invader in Cliffdrip Camp. Progress: Do not permit the gorlocs to encroach on the wildlife!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193304, ["x"] = 0.596, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193304, ["x"] = 0.596, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[71143] = { ["id"] = 71143, ["name"] = "The Horde Slayer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 66036, 67053, 70135, 70373, 71026, 71143 }, ["description"] = "Wow! Keep it up, soldier! Slay a bit more Horde and you will go down in the record books among the Alliance. But it won't be easy, the Horde have put a bounty on your head, so watch it! For the Alliance!", ["objectivesText"] = "While being hunted by the Horde, slay 10 Horde without dying.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp", ["questLines"] = { { ["id"] = 1406, ["name"] = "10.0 Faction Swap Protection [DNT]", ["orderIndex"] = 5, ["flags"] = 0 } } },
[71144] = { ["id"] = 71144, ["name"] = "The Alliance Slayer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 66110, 66111, 66704, 70371, 71025, 71144 }, ["description"] = "Yes! Keep going, keep slaying those Alliance dogs! Slay a bit more Alliance and you may set a new record, <class>. But it won't be easy, the Alliance have put a bounty on your head, so watch it! For the Horde!", ["objectivesText"] = "With a bounty on your head, slay 10 Alliance without dying.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp", ["questLines"] = { { ["id"] = 1406, ["name"] = "10.0 Faction Swap Protection [DNT]", ["orderIndex"] = 7, ["flags"] = 0 } } },
