[71155] = { ["id"] = 71155, ["name"] = "The Azure Vaults", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71155 }, ["description"] = "We have a problem, <name>. Beneath the Azure Archives rests the Azure Vault. In my life, I stored many important and dangerous magical curiosities in it. A large group of Sundered Flame have broken into the vault, convinced it holds some kind of secrets. Please, you must go in there and stop this brazen assault before they unleash dangers they do not comprehend. These thieves know not what lies within.", ["objectivesText"] = "Stop the Sundered Flame within the Azure Vaults. You can access the Azure Vaults solo by queuing for it in Follower Dungeons. Progress: Do be careful within the vaults.", ["rewardGold"] = 1123600, ["rewardXP"] = 19030, ["rewardItems"] = { 193629, 193641, 193647 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186188, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186188, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "dungeon" },
