[71179] = { ["id"] = 71179, ["name"] = "Look to the Overlook", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 71179 }, ["series"] = { 66468, 66470, 66471, 66472, 66473 }, ["description"] = "<name>, I have another task for you. There have been reports of Primalist activity near the Gelikyr Post that threaten our control of Tyrhold. Speak with Commander Thadezus and see how you can assist.", ["objectivesText"] = "Speak with Commander Thadezus at the Gelikyr Overlook.", ["rewardGold"] = 26915, ["rewardXP"] = 685, ["rewardItems"] = { 192795, 192808, 200670, 200671, 200672 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189842, ["x"] = 0.5676, ["y"] = 0.4108 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 189174, ["x"] = 0.526, ["y"] = 0.672 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.5676, ["y"] = 0.4108 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
