[71209] = { ["id"] = 71209, ["name"] = "Beast of the Plains", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 71209 }, ["description"] = "I think Lizi is ready to be a beast of the plains again. She's so friendly to you and I now, but I can tell she wants to return to the wild. One day, when I am a Windsage, I will explore all of the world beyond these springs. But first--my midseason initiate trials! How time flies. I made a saddle and reins from the wool you gathered. Lizi will be happy to come at your call. Please take her on all the adventures, $p.", ["objectivesText"] = "Accept Lizi's Reins .", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 192799 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.535778, ["y"] = 0.680889 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[71210] = { ["id"] = 71210, ["name"] = "To Dragonbane Keep!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 71210 }, ["description"] = "<Flaps drops a slightly singed note into your hand.> <name>, the Obsidian Outcasts have heard tales of your bravery. Our former home, Dragonbane Keep, has fallen into djaradin hands. We can't let that stand. Join us in reclaiming our territory. - Boss", ["objectivesText"] = "The Siege on Dragonbane Keep is one of the main features you unlock with the Valdrakken Accord reputation . This is a world event in which you help a group of black drakonid, the Obsidian Outcasts, reclaim an area in the Waking Shores that is overrun with djaradin. Unlocking Siege on Dragonbane Keep requires Renown 5 with the Valdrakken Accord, and unlocking it once will unlock it for all characters on your account. You can see from your Waking Shores minimap when the Siege on Dragonbane Keep event is startting, and the event is on a 2 hour loop , alternating every hour at the top of the hour - The event has one hour in which it won't be available ( The Obsidian Outcasts are gathering. The siege will begin soon. ) and one hour in which Dragonbane Keep is available for the taking ( The Obsidian Outcasts are attempting to take Dragonbane Keep. Assistance is requested. ) Once an event is underway, you will go through several stages up to killing a rare NPC. Killing this rare NPC, Inferna the Bound , ends the event. Completing a Siege on Dragonbane Keep event grants 50 Reputation with the Valdrakken Accord. The first completion in the week of the event grants a Dragonbane Keep Strongbox , which contains: 250 Valdrakken Accord reputation; 1-3 Dragon Isles Artifact and Titan Relic 1 piece of gear scaling with your ilvl (capping at ilvl382) 1-3 Depleted Primal Chaos 1 Passing Renascence Subsequent completions of the event grants a Dragonbane Keep Strongbox , which contains 1-3 Dragon Isles Artifact and Titan Relic and 15 Dragon Isles Supplies ; Travel to the Waking Shores and join the Obsidian Outcasts on the Siege of Dragonbane Keep. Progress: We must take the Keep!", ["rewardGold"] = 561800, ["rewardXP"] = 10205, ["rewardItems"] = { 190454, 192017, 192055, 199906, 200072, 200073, 200286, 201921, 201922, 201923, 201924, 202001, 202142 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 197478, ["x"] = 0.455, ["y"] = 0.5545 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 194404, ["x"] = 0.2716, ["y"] = 0.734 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.5545 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
