[71219] = { ["id"] = 71219, ["name"] = "The Wayward Waywatcher", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 71219 }, ["series"] = { 66100, 66448 }, ["description"] = "It seems some of our younger Waywatchers have grown lax in their duties of late. Waywatcher Nori has asked me to check in on her younger sister Alvi, who is stationed at the mouth of the Passage of Time. Apparently her recent performance has been less than satisfactory. If you head east and happen to encounter Waywatcher Alvi , please remind her of the importance of her position, and let her know that her sister is rather worried about her.", ["objectivesText"] = "Find Waywatcher Alvi .", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 191308, 191317, 191405, 191852 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 197533, ["x"] = 0.5015, ["y"] = 0.6195 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 191753, ["x"] = 0.546, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.5015, ["y"] = 0.6195 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
