[71229] = { ["id"] = 71229, ["name"] = "Call of the Plains", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 71229 }, ["description"] = "< Roki drops a message into your hand.> <name>, Clan Aylaag has heard tales of your great deeds. We invite you to meet our clan and share our ways. Hadari Khan", ["objectivesText"] = "Speak to Hadari Khan in the Ohn'ahran Plains.", ["rewardGold"] = 24100, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 197627, ["x"] = 0.455, ["y"] = 0.549667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185853, ["x"] = 0.660667, ["y"] = 0.484667 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.549667 }, ["mapCandidates"] = { ["npc"] = { 2023, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[71230] = { ["id"] = 71230, ["name"] = "Tuskarr Fishing Gear", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 71230 }, ["description"] = "Hi again, <name>. < Rowie looks around and hums a little tune.> Oh right! Tavio was making me a new net and said she could make you one too. She can make some other fishing gear too if you bring her all the stuff. You should go talk to her.", ["objectivesText"] = "Speak to Tavio at Iskaara in The Azure Span.", ["rewardGold"] = 24100, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 197631, ["x"] = 0.455, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 195935, ["x"] = 0.128, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.554 }, ["mapCandidates"] = { ["npc"] = { 2024, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[71231] = { ["id"] = 71231, ["name"] = "Call of the Hunt", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 71231 }, ["description"] = "< Roki drops the note into your hand> <name>, Clan Shikaar invites you to the Grand Hunt. Meet with Trainer Frodrum in the Ohn'ahran Plains.", ["objectivesText"] = "Speak to Trainer Frodrum in the Ohn'ahran Plains.", ["rewardGold"] = 16980, ["rewardXP"] = 345, ["rewardItems"] = { 200468, 237812 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 197627, ["x"] = 0.455, ["y"] = 0.549667 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192926, ["x"] = 0.518, ["y"] = 0.765 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.549667 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[71232] = { ["id"] = 71232, ["name"] = "Renown of the Dragon Isles", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "There is still much that must be done to aid the Dragon Isles. I would ask you speak with Koszaru . He has much information regarding who needs help within this land.", ["objectivesText"] = "Speak with Koszaru within Valdrakken.", ["rewardGold"] = 34100, ["rewardXP"] = 1190, ["rewardItems"] = { 190454, 192017, 200072, 200073, 202142 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2112, ["npcID"] = 213930, ["x"] = 0.48, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.583778, ["y"] = 0.357111 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 0, ["flags"] = 0 } } },
[71233] = { ["id"] = 71233, ["name"] = "Falling Water", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71233 }, ["description"] = "I love waterfalls. Want to know what's better than a waterfall? Two waterfalls. And the only thing better than that is... well, check out Three-Falls to the west of here and you'll see! The innkeeper there is quite nice.", ["objectivesText"] = "Talk to Willa at Three-Falls Lookout in the Azure Span .", ["rewardGold"] = 84900, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194613, ["x"] = 0.284, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190315, ["x"] = 0.188, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71234] = { ["id"] = 71234, ["name"] = "Nook News", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71234 }, ["description"] = "You there, <race>. You look well-travelled. My cousin Wayun was bringing a catch over from Whaler's Nook and mentioned that some... strange folk have set up camp over there. They appear to be behaving themselves, but would you mind checking in on Wayun ? He can be a bit salty.", ["objectivesText"] = "Visit Whaler's Nook in the Azure Span .", ["rewardGold"] = 84900, ["rewardXP"] = 2060, ["rewardItems"] = { 191202, 191680, 192203, 193052 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 193877, ["x"] = 0.14, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186212, ["x"] = 0.074, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.14, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71235] = { ["id"] = 71235, ["name"] = "Field Mages", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71235 }, ["description"] = "Lok'tar, <race>. If you have the time, we have two mages doing fieldwork nearby who I'm sure could use a hand. This is a dangerous land in the best of times. These are not the best of times.", ["objectivesText"] = "Check on the Kirin Tor mages near Slyvern Plunge in the Azure Span .", ["rewardGold"] = 84900, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189751, ["x"] = 0.658, ["y"] = 0.254 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 192825, ["x"] = 0.646, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.254 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71238] = { ["id"] = 71238, ["name"] = "The Ruby Feast!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 71238 }, ["description"] = "Attention to all aspiring culinarians! Does your heart desire the ultimate flavors of this world? Do you seek out opportunities for grand exploration? Are you willing to risk life and limb for complete strangers? If this is you, come speak with the eminently distinguished, world-renowned chef duo, Rumiastrasza and Morsel! Currently hosting The Ruby Feast in the city of Valdrakken !", ["objectivesText"] = "Speak with Chefs Rumiastrasza and Morsel at The Ruby Feast.", ["rewardGold"] = 4365, ["rewardXP"] = 355, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 189479, ["x"] = 0.614, ["y"] = 0.115 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.115 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[71239] = { ["id"] = 71239, ["name"] = "Lost to the Skies", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 71239 }, ["description"] = "I need a favor, and you look like the favor-doing type. An ol' pal of mine, Harleen Chirpsnide , was supposed to meet me in the city a few days ago. We was planning to eat our way through The Ruby Feast, get a trim at the barbershop, then visit that swanky auction house they got here. But she ain't shown up. She gets lost in her work plenty, but I'd feel a lot more comfortable knowing where she was. Try the mountains south of here. She mentioned she'd be swinging by on her way in.", ["objectivesText"] = "Locate Harleen Chirpsnide in the Bluefeather Cliffs.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 189361, 189384, 189453, 189454, 189751, 189899, 189974, 189979, 189981, 190188, 191176, 191177, 191178, 191681, 191763 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 194578, ["x"] = 0.254, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 183912, ["x"] = 0.4495, ["y"] = 0.709 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.254, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[71241] = { ["id"] = 71241, ["name"] = "Duck, Duck, Trap", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 71241 }, ["description"] = "The grove called the Primordial Vale is rich with the magic of the old dragons. A type of slyvern there are prized by my kin for their fur, but they are elusive and hard to find. Instead of having you try to track them down, you can find some of our hunting traps in the area. Use meat from the nearby waterfowl to reset them - I will send some of our clan to retrieve whatever gets caught.", ["objectivesText"] = "Reset the Clan Aylaag hunting traps at the Primordial Vale. Progress: The fowl in the area are the preferred source of food for the slyverns.", ["rewardXP"] = 2765, ["rewardItems"] = { 191984, 191986, 191987, 191991, 191992, 191993, 191996, 191998, 191999, 192000, 192002, 192005, 192006, 192007, 192008, 192010, 192013, 192014, 192015, 192017, 192018, 192021, 192023, 193568, 198539, 198542, 200674 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.491667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
