[72060] = { ["id"] = 72060, ["name"] = "Special Treatment", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72060 }, ["description"] = "<The mud mask looks curious about your intentions, but it is cornered on this branch!>", ["objectivesText"] = "Return the sunglasses to Zeldis . Again. Progress: I know my sunglasses are amazing, but come on now. This is the second time an ooze has run off with them! How am I supposed to be gorgeous in these conditions? Wait, did you find them again?!", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 198818, 200586, 200872 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 198590, ["x"] = 0.389, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 198062, ["x"] = 0.394, ["y"] = 0.478667 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.389, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
