[72122] = { ["id"] = 72122, ["name"] = "Erstwhile Ecologists", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72122 }, ["description"] = "The wounded are stabilized, but something still troubles me, <name>. A pair of dragonspawn ecologists had come to the outpost to study the wetlands. I haven't seen scale nor claw of them since the attack, and it's become worrisome. If you're venturing out, would you mind keeping an eye out, and making sure they're safe? And do take care. Rumor has it those wetlands are gorloc-infested.", ["objectivesText"] = "Check in on the wayward ecologists.", ["rewardGold"] = 1745, ["rewardXP"] = 175, ["rewardItems"] = { 191546, 191549 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 195303, ["x"] = 0.712, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186410, ["x"] = 0.744, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
