[72129] = { ["id"] = 72129, ["name"] = "Aiding Khadgar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 7502, ["storyline"] = { 72129 }, ["series"] = { 72134 }, ["description"] = "Welcome to Dalaran, <name>. I'm glad you made it through safely. Speak to me within the Violet Citadel. There's much to do.", ["objectivesText"] = "Meet Khadgar within the Violet Citadel in Dalaran.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
