[72189] = { ["id"] = 72189, ["name"] = "Garden Variety", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72189 }, ["description"] = "Are you enjoying the butterfly garden? You know, there's a much larger garden just to the south of here. An older drakonid by the name of Gryrmpech tends to it. He could always use an extra pair of hands. He has an 'assistant', but I've never actually seen him. I can't imagine he's of much help. If you stop by, be sure to let him know that Xina sent you.", ["objectivesText"] = "Speak with Gyrympech.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 191473, 191676, 194098 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 189364, ["x"] = 0.774, ["y"] = 0.6672 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 187300, ["x"] = 0.378, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.774, ["y"] = 0.6672 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72190] = { ["id"] = 72190, ["name"] = "Reservoir Reservations", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72190 }, ["description"] = "<class>! I know someone who is in dire need of your skills. Tyrhold Reservoir has just been attacked by Primalists. I was lucky to make my escape when I did. I fear the others may not be so lucky. It's just to the north of here. Find Zuttiki , she'll be able to fill you in on the details. If she's still alive, that is.", ["objectivesText"] = "Find Zuttiki .", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 193043 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 198349, ["x"] = 0.255, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 190527, ["x"] = 0.495, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.255, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72191] = { ["id"] = 72191, ["name"] = "Short-Supply Reward", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 72191 }, ["rewardItems"] = { 69903, 90818, 103533, 120334, 128803, 140591, 141701, 160054, 184522, 201326, 224573, 259086 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[72192] = { ["id"] = 72192, ["name"] = "Halls of Infusion: Entropy to Order", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72192 }, ["description"] = "The Primalists wish to bring elemental chaos back to this world and will stop at nothing to see their goal accomplished. I have received disturbing news that they have infiltrated the Halls of Infusion deep below Tyrhold. They attempt to disrupt the works of Keeper Tyr for their own nefarious purposes. Please, you must put an end to any Primalist threat within those sacred halls, <name>.", ["objectivesText"] = "Enter the Halls of Infusion and defeat the Primal Tsunami. You can access the Halls of Infusion solo by queuing for it in Follower Dungeons. Progress: Have you cleared the halls of Primalist threat, <name>?", ["rewardGold"] = 1123600, ["rewardXP"] = 10930, ["rewardItems"] = { 193725, 193726, 193731, 193735, 193738, 193743 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191369, ["x"] = 0.545, ["y"] = 0.4135 }, { ["mapID"] = 2112, ["npcID"] = 197206, ["x"] = 0.586, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191369, ["x"] = 0.545, ["y"] = 0.4135 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.4135 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "dungeon" },
[72193] = { ["id"] = 72193, ["name"] = "The Algeth'ar Academy", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14032, ["mapID"] = 2112, ["storyline"] = { 72193 }, ["description"] = "I understand that the Algeth'ar Academy is open to the world once more. Long ago, its sacred halls were only open to dragons, but in the years that have passed the Headteacher has seen the wisdom of welcoming any who wish to learn. She has asked for my recommendation on any promising new students. As a great ally to dragonkind, it would be an honor to have you attend our great academy. I leave the decision to enroll up to you, but I am sure Doragosa would love to at least give you a tour.", ["objectivesText"] = "Tour the grounds of Algeth'ar Academy. You can access Algeth'ar Academy solo by queuing for it in Follower Dungeons. Progress: I hope you enjoy your time at the Academy. It really is a remarkable place.", ["rewardGold"] = 1123600, ["rewardXP"] = 19030, ["rewardItems"] = { 193704, 193705, 193708, 193712, 193720, 193721 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187676, ["x"] = 0.609333, ["y"] = 0.364 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187676, ["x"] = 0.609333, ["y"] = 0.364 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.609333, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 14032 } }, ["questType"] = "dungeon" },
[72240] = { ["id"] = 72240, ["name"] = "The Obsidian Warders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 65436, 66577, 66589, 66596, 67700, 70050, 72240 }, ["description"] = "This Toddy's enthusiasm is admirable. But I hope it does not blind her to the dangers awaiting us in the Dragon Isles . Regardless, the Obsidian Warders are duty-bound to protect the expedition. I must speak with Wrathion and the Lord Commander about the mission ahead. My fellow dracthyr are exploring the city. Seek out Dervishian, my trusted lieutenant, and inform her that we are to rally at the docks. She will relay my orders to the rest.", ["objectivesText"] = "Deliver the scalecommander's orders to Dervishian and the Obsidian Warders. Progress: Ye think a dracthyr can fly faster than a gryphon?", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 192493, 199109, 199211, 199337, 199686, 199836, 199837, 199838, 199839, 202188 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 189603, ["x"] = 0.798, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 189077, ["x"] = 0.228, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.798, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 165, ["title"] = "The Dragonscale Expedition", ["questLineID"] = 1289, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 1289, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 1289, ["name"] = "The Dragonscale Expedition", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 6021, ["name"] = "Dragon Isles City Intro Quests", ["orderIndex"] = 8, ["flags"] = 0 } } },
[72241] = { ["id"] = 72241, ["name"] = "Lessons From Our Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65793, 65939, 65956, 65957, 66044, 66048, 66049, 66055, 66056, 66057, 66078, 66079, 66354, 66779, 66780, 72241 }, ["description"] = "I am Emberthal, a scalecommander of the dracthyr. Wrathion aided us after we awakened from our long stasis, and now it is my turn to help him. No doubt you have questions about my people and our history. Until recently, I did as well. But Nozdormu, the Timeless One, has revealed lost truths about the dracthyr. He granted me a vision of our origins... and why we were locked away. Let me tell you of the things I have seen.", ["objectivesText"] = "Speak with Scalecommander Emberthal . Progress: There is much we can learn from one another.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 191131, 192548 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192795, ["x"] = 0.424, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192795, ["x"] = 0.424, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1301, ["questLineOrder"] = 2 }, { ["id"] = 200, ["title"] = "Obsidian Citadel", ["questLineID"] = 1376, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 1301, ["name"] = "Wrathion's Gambit", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 1376, ["name"] = "Obsidian Citadel Alt Skip", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 32, ["flags"] = 0 } } },
