[72373] = { ["id"] = 72373, ["name"] = "Aiding the Accord: The Hunt is On", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "Our allies from the Ohn'ahran Plains have sent word-a request-for any and all who hunt these lands to lend their aid to their cause. Whilst continuing your efforts across these Isles, pay a visit to our allies at one of their hunting camps and assist in their efforts. There is much to be done. Best not delay.", ["objectivesText"] = "Assist the Maruuk on a Hunt within the Dragon Isles. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: Has our renowned traveler returned with more news of success?", ["rewardXP"] = 2125, ["rewardItems"] = { 190454, 192017, 200072, 200073, 201921, 201922, 201923, 201924, 202142 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3026 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 4, ["flags"] = 1 } } },
[72374] = { ["id"] = 72374, ["name"] = "Aiding the Accord: Dragonbane Keep", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "Our allies once again seek your assistance as our efforts continue across the Isles. Words within the walls of Valdrakken whisper a resounding comfort knowing your efforts have helped shape our future. Now then, to business. A lingering djaradin threat moves upon the Waking Shores deep within the smoldering inferno of Dragonbane Keep. We must move to disrupt their advances. We await your return, <name>.", ["objectivesText"] = "Travel to The Waking Shores and lay siege to Dragonbane Keep. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: Do you bring news of your success?", ["rewardXP"] = 2125, ["rewardItems"] = { 190454, 192017, 200072, 200073, 201921, 201922, 201923, 201924, 202142 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2022, ["npcID"] = 199336, ["x"] = 0.765, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2022, ["npcID"] = 199336, ["x"] = 0.765, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3026 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 5, ["flags"] = 1 } } },
