[72584] = { ["id"] = 72584, ["name"] = "Setting Your Very Own Net", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70871, 70936, 70939, 70940, 70941, 70942, 70943, 70944, 70945, 70948, 70950, 70952, 70953, 70954, 70955, 70956, 70959, 70960, 70961, 70962, 70963, 70964, 70966, 70967, 70968, 70969, 70971, 70972, 70976, 70977, 70978, 72279, 72280, 72281, 72291, 72292, 72318, 72319, 72320, 72321, 72322, 72323, 72324, 72325, 72326, 72327, 72385, 72386, 72387, 72388, 72389, 72390, 72391, 72392, 72393, 72394, 72395, 72584, 72632, 72633, 72634, 72635, 72636, 72637, 72638, 72639, 72640, 72641, 72642, 72875 }, ["description"] = "Want to try out your net? Go to the river mouth to the south of Waking Shores, and find a place where the fish are abundant. There should be a good spot for setting up a net.", ["objectivesText"] = "Set up a fishing net in the River Mouth Fishing Hole. Progress: Don't forget, south of Waking Shores. Go.", ["rewardGold"] = 70225, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 195935, ["x"] = 0.128, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 195935, ["x"] = 0.128, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.128, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1382, ["name"] = "Iskaara Tuskarr Renown", ["orderIndex"] = 9, ["flags"] = 0 } } },
[72585] = { ["id"] = 72585, ["name"] = "Open Orientation", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "You have done much for the Dragon Isles, hero. There are many who are grateful for your contributions and want to welcome you more wholly into their communities. Go to them and orient yourselves with each group and their specialties. I think you will find that just as you have much to offer the Dragon Isles, many here have much they wish to offer you in return!", ["objectivesText"] = "Complete the Orientation quests in each major faction hub: Dragonscale Basecamp, Maruukai, Iskaara, and Valdrakken .", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 190454, 192017, 200072, 200073, 202142 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2022, ["npcID"] = 199336, ["x"] = 0.765, ["y"] = 0.342 }, { ["mapID"] = 2112, ["npcID"] = 213930, ["x"] = 0.48, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2112, ["npcID"] = 213930, ["x"] = 0.48, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 1, ["flags"] = 0 } } },
