[72686] = { ["id"] = 72686, ["name"] = "Storm Surge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72686 }, ["description"] = "<name>, the Primalists have managed to summon fierce Elemental Storms all across the Dragon Isles. When a storm is active go to it and slay the imbued creatures there. Then collect the Elemental Overflow from the slain foes. Be aware that the stronger the foe, the more Elemental Overflow you will collect. We must not let the Primalist elemental corruption grow unchecked.", ["objectivesText"] = "Defeat Elementally Imbued creatures to collect Elemental Overflow while in an Elemental Storm. Progress: Have the storms subsided? Have you brought me what I need?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192775, 199691, 199748, 199749, 199750 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196598, ["x"] = 0.382, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196598, ["x"] = 0.382, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.382, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
