[72708] = { ["id"] = 72708, ["name"] = "Dragon Isles Supplies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72708 }, ["series"] = { 72709 }, ["description"] = "<That proto-dragon must've snatched this bag of supplies off of an unlucky Dragonscale Expedition member. Cataloger Jakes in Wingrest Embassy will know what best to do with it.>", ["objectivesText"] = "Deliver Dragon Isles Supply Bag to Cataloger Jakes in Wingrest Embassy. Provided item:", ["rewardItems"] = { 191294, 193852, 193885, 193886, 193887, 193888, 193889, 194540, 198843, 198852, 198854, 198863, 198865, 198866, 198867, 199061, 199062, 199065, 199066, 199067, 199068, 199472, 199473, 199736, 199737, 199738, 199739, 199740, 200738, 200861, 200863, 200864, 200865, 200866, 200867, 201927, 202019, 202081, 202692, 210501 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 198846, ["x"] = 0.765, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["startItems"] = { 202081 } },
[72709] = { ["id"] = 72709, ["name"] = "Funding a Treasure Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72709 }, ["series"] = { 72708 }, ["description"] = "< Cataloger Jakes quickly flips through her own supply bag and pulls out a freshly drawn map.> One of our archeologists just reported some new findings in regards to a lost artifact, suspected to be in this area. If you'll donate those supplies to fund the archeologist's next expedition, you can have this map that points to a nearby treasure.", ["objectivesText"] = "Buy the Archeologist Artifact Notes from Cataloger Jakes . Progress: Our archeologists love their work, but they still need funding to do it.", ["rewardItems"] = { 191294, 193852, 193885, 193886, 193887, 193888, 193889, 194540, 198843, 198852, 198854, 199061, 199062, 199065, 199066, 199067, 199068, 199736, 199737, 199738, 199739, 199740, 200738, 200861, 200863, 200864, 200865, 200866, 200867, 201927, 202019, 202081, 202692 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 198846, ["x"] = 0.765, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 198846, ["x"] = 0.765, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
