[72872] = { ["id"] = 72872, ["name"] = "Culling the Deep", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "Have you seen these deepflayers before? Well, of course you have! You were almost eaten by one! They're getting a little too cozy to me and my people's settlement nearby, and need to be dealt with. Inside the cave, outside the cave, they're all over the place! That's why I came here in the first place. Since I can tell we'll be ramblin' round with each other for a bit, why not give me a hand?", ["objectivesText"] = "Kill 8 Deepflayers. Progress: Not bad, uplander! Have you dabbled in monster hunting before this?", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201587, ["x"] = 0.602, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 5, ["flags"] = 0 } } },
[72873] = { ["id"] = 72873, ["name"] = "It Was Not Enough", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "You're smellin' real down and out there, kid. Can't imagine what you been through to end up here. Well, it don't matter! We niffen ain't the sort to leave anyone behind. Especially not people who're about to be served up as a deepflayer's snack! This master sniffin' snout of mine can smell you didn't come down here to our Zaralek Cavern alone. What say we get you out of those crystals and find your friends!", ["objectivesText"] = "Follow Elder Honeypelt to find Wrathion and Sabellian.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 44785, 44788, 46723, 46800, 46824, 64533, 64534, 64535, 64536, 64537, 64538, 64539, 64540, 64541, 64542, 116404, 132305, 132306, 132308, 132309, 132310, 132311, 132312, 132314, 132316, 132317, 132319, 132320, 132321, 132322, 132323, 132325, 141933, 180901, 180902, 180903, 180904, 197890, 197894, 197898, 198609, 211279, 237812 }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201587, ["x"] = 0.602, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 6, ["flags"] = 0 } } },
[72875] = { ["id"] = 72875, ["name"] = "Dragon Isles Supplies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70871, 70936, 70939, 70940, 70941, 70942, 70943, 70944, 70945, 70948, 70950, 70952, 70953, 70954, 70955, 70956, 70959, 70960, 70961, 70962, 70963, 70964, 70966, 70967, 70968, 70969, 70971, 70972, 70976, 70977, 70978, 72279, 72280, 72281, 72291, 72292, 72318, 72319, 72320, 72321, 72322, 72323, 72324, 72325, 72326, 72327, 72385, 72386, 72387, 72388, 72389, 72390, 72391, 72392, 72393, 72394, 72395, 72584, 72632, 72633, 72634, 72635, 72636, 72637, 72638, 72639, 72640, 72641, 72642, 72875 }, ["rewardItems"] = { 198863, 198865, 198866, 198867, 199472, 199473, 210501 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 193006, ["x"] = 0.13, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 193006, ["x"] = 0.13, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.13, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1382, ["name"] = "Iskaara Tuskarr Renown", ["orderIndex"] = 10, ["flags"] = 0 } } },
[72876] = { ["id"] = 72876, ["name"] = "Multiple Dragon Isles Artifacts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72876 }, ["objectivesText"] = "Progress: Do you have something for the archives?", ["rewardItems"] = { 192055 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[72877] = { ["id"] = 72877, ["name"] = "Multiple Dragon Isles Artifacts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72877 }, ["objectivesText"] = "Progress: Do you have something for the archives?", ["rewardItems"] = { 200443 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[72878] = { ["id"] = 72878, ["name"] = "Slime Time Live", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72878 }, ["description"] = "$p, if I could grab your ear again, my dear? Since making it back to Loamm, I've noticed that some of our incense pots have gone missing. Incense is what we use to mark our trade routes, and find our way back to Loamm. It's very important that we replace the missing incense as soon as possible. By the way, we make our incense from snail slime , so you're going to have to wrangle some snails first! Once you're done, Citros can help you out with the rest. Say hello to Marie Shellie for me!", ["objectivesText"] = "Lasso 8 Dripping Redolent Whelks to collect Snail Slime in Zaralek Cavern . Progress: Snail slime is the base that most of our incense is built upon.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 203442, 205980 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200054, ["x"] = 0.5728, ["y"] = 0.5488 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200055, ["x"] = 0.568, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.5728, ["y"] = 0.5488 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[72879] = { ["id"] = 72879, ["name"] = "Smells like Kith Spirit", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72879 }, ["description"] = "Well, it's not too often we see uplanders around here! Honeypelt must have a good reason for sending you my way, she doesn't trust just anyone with her incense. A kith's incense is their pride and joy. Each one smells unique, and we use them to identify each other. Making incense is a delicate business. Just head over to that cauldron and Marie Shellie and I will help ya out with whipping up some replacements.", ["objectivesText"] = "Make Niffen Incense with Citros . Progress: It's starting to smell really good!", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200055, ["x"] = 0.568, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200055, ["x"] = 0.568, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[72880] = { ["id"] = 72880, ["name"] = "Incense Gratification", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72880 }, ["description"] = "That's some real potent incense you made! Usually it takes time to get this good! Now, I've got some of my own brewing to do, so you're gonna have to go out and set those up by yourself. Once you're finished I'm sure Honeypelt will be mighty keen on hearing about it! Best follow up with her when you're done.", ["objectivesText"] = "Place 9 Missing Incense in Zaralek Cavern .", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 205249 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200055, ["x"] = 0.568, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200054, ["x"] = 0.5728, ["y"] = 0.5488 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[72881] = { ["id"] = 72881, ["name"] = "A Swallow's Tale", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72881 }, ["description"] = "Uplander! I'm Effervesta , Lady Redolence to the niffen of Loamm--the daughter of their leader. No need for formalities though, you can just call me Effie! Keep this between you and me, but we're a bit behind on some shipments to Glimmerogg, and the Drogbar are definitely not happy one bit! You've already been so helpful to Elder Honeypelt... maybe you can give me a hand too? Our swallows keeper, Nevroll, might be able to dig up some dirt on the issue. Will you go talk to him, please?", ["objectivesText"] = "Speak with Swallows Keeper Nevroll in Zaralek Cavern .", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200053, ["x"] = 0.546, ["y"] = 0.546 }, { ["mapID"] = 2133, ["npcID"] = 204544, ["x"] = 0.569, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200056, ["x"] = 0.551, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[72882] = { ["id"] = 72882, ["name"] = "Flown the Coop", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72882 }, ["description"] = "They're gone! Just... gone! The swallows, Nevroll, all of it! And now you say that Effervesta told you that we're behind on our shipment of swallow nests to the Drogbar? This is really bad, Uplander. If you want to help, you can start by bringing back as many birds as you can find. I'll see if I can scrape together any useable nests for the Drogbar in the meantime.", ["objectivesText"] = "Find 6 Lost Swallows in Zaralek Cavern . Progress: If Nevroll or the Drogbar show up before we find those birds, we're toast!", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 39337, 39383, 39435, 39455 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200056, ["x"] = 0.551, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200056, ["x"] = 0.551, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.551, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[72883] = { ["id"] = 72883, ["name"] = "A Bitter Pill to Swallow", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72883 }, ["description"] = "<The corpse of a single cave swallow rests on the cavern floor. You should tell Cinnam.>", ["objectivesText"] = "Take the dead swallow to Cinnam. Progress: Oh no...", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200238, ["x"] = 0.578, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200052, ["x"] = 0.561333, ["y"] = 0.554667 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[72884] = { ["id"] = 72884, ["name"] = "Expedition Effervesta", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72884 }, ["description"] = "My daughter's gone missing--we have to find her! As High Redolence, I may be the next target. $p, will you come with me? I can still smell her, faintly. She has to still be in Loamm somewhere. We have to hurry!", ["objectivesText"] = "Search for clues about Effervesta's whereabouts in Zaralek Cavern .", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200052, ["x"] = 0.561333, ["y"] = 0.554667 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200052, ["x"] = 0.561333, ["y"] = 0.554667 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.561333, ["y"] = 0.554667 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[72886] = { ["id"] = 72886, ["name"] = "Suss Out the Imposter", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72886 }, ["description"] = "Do I smell... Nevroll ? If he's the kidnapper, that must mean he's also behind the missing shipment! I don't think it's safe for me to go in there, $p. Please, rescue Effie!", ["objectivesText"] = "Defeat Nevroll and rescue Effervesta in Zaralek Cavern .", ["rewardGold"] = 619600, ["rewardXP"] = 4925, ["rewardItems"] = { 205250 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200052, ["x"] = 0.561333, ["y"] = 0.554667 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200052, ["x"] = 0.561333, ["y"] = 0.554667 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.561333, ["y"] = 0.554667 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[72900] = { ["id"] = 72900, ["name"] = "Keeper of the Ossuary", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2112, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Greetings, <name>. While I continue to search for the remaining blue dragons, I could use your aid in another matter. Alexstrasza and I plan on laying to rest the remaining essences of Malygos and Sindragosa. She has held on to their lingering essences after both were slain years ago. Senegos said there was a time where dragons would be laid to rest in the Veiled Ossuary. Unfortunately, the place is a mess. He's gone ahead to clean the area up with Stellagosa. Could you aid them?", ["objectivesText"] = "Meet Senegos in the Veiled Ossuary. Progress: Ah, here to help are we?", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["rewardItems"] = { 71086, 206162 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187676, ["x"] = 0.609333, ["y"] = 0.364 }, { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199923, ["x"] = 0.622, ["y"] = 0.178 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.609333, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025, 2112 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 0, ["flags"] = 0 } } },
[72908] = { ["id"] = 72908, ["name"] = "Sight Beyond Sight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "I had not expected to find djaradin here, though it does not surprise me. Legends tell of their elders slumbering beneath the earth. It makes sense that some would delve underground in search of them. Their forces are heavily guarding this outer area. I recognize the magic their scouts are using--it is farsight, powered by those totems near them. I spotted a larger totem at the top of the nearby tower. If you can figure out how to power it, we can use it to search the caldera from afar.", ["objectivesText"] = "Inspect nearby Flamesight Totems to find a way to activate the Greater Flamesight Totem atop the guard tower. Progress: This tower provides the best vantage point in the caldera. If there is any evidence that Fyrakk came through here--or worse--we will see it.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 203385, 204586, 204594, 204602, 204610, 204694 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200080, ["x"] = 0.41, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199852, ["x"] = 0.354, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 26, ["flags"] = 0 } } },
[72909] = { ["id"] = 72909, ["name"] = "Legends of the Zaqali", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "Because of our recent conflicts, I have been researching the djaradin. Our archives had little information on their elders. Legends say that they were once great warlords who now slumber beneath the earth. The djaradin believe they will awaken and lead them to a brutal victory against the dragonflights. We need to know what we are up against. There is an empty shrine just below us that resembles the ones housing the elders. We may find some answers there.", ["objectivesText"] = "Inspect the Zaqali belongings left near the Elder's shrine.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199852, ["x"] = 0.354, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199948, ["x"] = 0.302, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 27, ["flags"] = 0 } } },
[72910] = { ["id"] = 72910, ["name"] = "Know Thy Enemy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "That djaradin called her people the \"Zaqali\"--but my troops did not report any information regarding a second active djaradin tribe in the Dragon Isles. I detest an unknown in war. We will need to learn what we can about them--and quickly--in order to assess their strengths and weaknesses. I have found the best way to know a culture is to examine how they make war. Slay any you find in the nearby area and take their armaments. I will expect your report.", ["objectivesText"] = "Gather 8 pieces of Zaqali equipment from Zaqali djaradin near the empty shrine. Progress: No detail about an enemy is insignificant. Everything can be used against them.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 203454, 204454, 204459, 204620, 204624, 204625, 204626, 204627, 204628, 204629, 204630 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199851, ["x"] = 0.354, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199949, ["x"] = 0.302, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 28, ["flags"] = 0 } } },
[72911] = { ["id"] = 72911, ["name"] = "Take Out the Head", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "While you and Ebyssian were away, I had an epiphany. That corrupted caldera is at the center of the Zaqali elder's slumbering prison and their war camps. Whatever is located within is the key to what the Primalists are planning. It is lightly guarded as well. Only a Primalist and a Zaqali priest. If we take them out, we can discover what I believe will be the truth behind all of this.", ["objectivesText"] = "Kill Shrinekeeper Qanosh and Earthrender Ku'siva .", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199949, ["x"] = 0.302, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199863, ["x"] = 0.344, ["y"] = 0.463 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.302, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 29, ["flags"] = 0 } } },
[72912] = { ["id"] = 72912, ["name"] = "Consequences", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "Shadowflame... Did Iridikron know this was here? Did he corrupt his brother? Or has Fyrakk fallen to the temptation? Only ignorance or arrogance tempts fools to seek it out, believing they can master dark forces that not even Neltharion could. It infected him, slowly, like a gangrenous lesion until finally he succumbed to madness. So too will Fyrakk. I will not take that risk with Sabellian. He was burned badly before I was able to fly you to safety. Let us assess the extent of the damage.", ["objectivesText"] = "Inspect Sabellian's injuries. Progress: I will not lose a single person to shadowflame. Not Sabellian. Not anyone.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 211279, 237812, 256334, 256335 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199863, ["x"] = 0.344, ["y"] = 0.463 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199863, ["x"] = 0.344, ["y"] = 0.463 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.463 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 30, ["flags"] = 0 } } },
[72913] = { ["id"] = 72913, ["name"] = "Battlefield Triage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "Our situation is less than ideal, we will have to improvise. I can conduct flame to earth to create magma. Shadowflame could behave similarly. The Primalists are summoning earth elementals nearby. If we extract their cores, I can use them to contain the shadowflame infecting Sabellian's burn. The Zaqali's totems should already be attuned to the elements here. It will make the siphoning process much more efficient. Sabellian will need to come with us. I must keep an eye on him--for his sake.", ["objectivesText"] = "Collect 5 Vacant Elemental Cores and 1 Zaqali Flame Totem . Progress: We cannot delay. Shadowflame deteriorates both mind and body with insidious haste. I will do everything I can to halt it.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 203653, 203654 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199863, ["x"] = 0.344, ["y"] = 0.463 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.463 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 31, ["flags"] = 0 } } },
[72914] = { ["id"] = 72914, ["name"] = "Rushing Quality", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "Look ahead! The djaradin have cleared away from the northeastern side of the caldera to augment their forces near the elders. There is an altar bordering the lava pool that appears safe for now. We can set up our spell components there. Let us hurry before the djaradin return.", ["objectivesText"] = "Cleanse the shadowflame from Sabellian's injury. Progress: Fyrakk and the elders can wait. If Sabellian is lost, we will fail regardless.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 203682, 204386 }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201581, ["x"] = 0.33, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 32, ["flags"] = 0 } } },
[72915] = { ["id"] = 72915, ["name"] = "Alliance of Convenience", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "The Primalists have a sizeable force of djaradin guarding them while they complete their work. Even in small numbers, djaradin prove to be formidable opponents when allowed to engage in battle on their own terms. It is far better to bring the fight to them, leaving as little time to react as possible. Take them out. We cannot have them encroaching on the space we have managed to carve out thus far.", ["objectivesText"] = "Kill 4 Zaqali djaradin guarding Igira's shrine. Progress: I am certain there will be no lack of djaradin this close to the elders' shrines.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 204616, 204617, 204618, 204619 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 33, ["flags"] = 0 } } },
[72916] = { ["id"] = 72916, ["name"] = "Shut Them Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "Up ahead, the Primalists are working to awaken the Zaqali's final elder. When we used the farsight totem earlier, I observed that they were draining something from the elder. Now I realize it is likely an attempt to dispel the magic keeping the elder in stasis. They are using elemental cores to contain the magic in the same way we did to cleanse Sabellian. Fyrakk absorbing shadowflame is disastrous. We cannot add an elder awakening to that threat. We must halt their efforts.", ["objectivesText"] = "Destroy 3 Earthdrainer Conduits and 4 Extracted Elemental Cores . Progress: I cannot be certain if this will stop them entirely, but it will at least slow their progress.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201581, ["x"] = 0.33, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 34, ["flags"] = 0 } } },
[72917] = { ["id"] = 72917, ["name"] = "From Hell's Heart", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "No longer can we allow Fyrakk to lie here peacefully, twisting himself with shadowflame and becoming a threat on par with Deathwing. We must act! Is it dangerous? Yes. But not to do anything would be catastrophic. I have ripped gronn apart with my bare claws before. Those battles were gambles, this one is not. Slaying a proto-dragon with a weapon meant for dragonslaying is obvious. It is logical. It is guaranteed. I will not tremble before an opportunity to end this now.", ["objectivesText"] = "Help Sabellian slay Fyrakk.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 204581, 204589, 204597, 204605 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199952, ["x"] = 0.295333, ["y"] = 0.495333 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199877, ["x"] = 0.41, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.295333, ["y"] = 0.495333 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 36, ["flags"] = 0 } } },
[72918] = { ["id"] = 72918, ["name"] = "No Dragon Left Behind", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "I... cannot move so long as this spear remains in my side. But we need to follow Fyrakk's trail. < Ebyssian grunts sharply, his breathing labored, claws digging into the dirt.> Remove it. I can... bear the pain it will cause.", ["objectivesText"] = "Find a way to remove the spear from Ebyssian 's side. Progress: He did not leave me. I cannot leave him.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204388 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199877, ["x"] = 0.41, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199876, ["x"] = 0.412, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 37, ["flags"] = 0 } } },
[72919] = { ["id"] = 72919, ["name"] = "Raked Over the Coals", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "The shadowflame has already corrupted Fyrakk irreparably. Every place in Zaralek darkened by his wings has been lit ablaze with shadowflame. We cannot leave it behind and let it fester--it will need to be extinguished while it is still kindling, lest we allow its corruption to take root. < Ebyssian coughs, then winces.> Sabellian and I cannot take to the air in this state. Disperse the flames with your drake. We will follow you below and meet you back at Loamm.", ["objectivesText"] = "Disperse 12 patches of shadowflame by dragonriding through them.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199877, ["x"] = 0.41, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199958, ["x"] = 0.56, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 38, ["flags"] = 0 } } },
[72920] = { ["id"] = 72920, ["name"] = "The Endless Burning Sky", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72966, 74494, 75145 }, ["description"] = "Fyrakk must have breathed shadowflame upon the niffen on his way out of the cavern. There is too much fire for it to have merely sloughed off of him. He did this on purpose. < Ebyssian clenches his staff tightly. He looks weary for a moment. Only a moment.> We will save Loamm. All of Loamm. No more lives will be lost.", ["objectivesText"] = "Extinguish the fires consuming Loamm and rescue 5 Loamm villagers.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 203707 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199958, ["x"] = 0.56, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201784, ["x"] = 0.56, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1394, ["name"] = "The Ancient Bargain", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 39, ["flags"] = 0 } } },
[72921] = { ["id"] = 72921, ["name"] = "On the Trail Again", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Ah... the Veiled Ossuary. I was given the task to be a sort of gravekeeper, which included keeping wildlife away from the area. I had a rather fun spell split up within several tomes kept within this place to deal with such pests. The other blue dragons did not approve of my... reckless methods, so I had to keep the tomes hidden. Here, allow me to cast a spell on you to grant you the sight to find these old tomes. Once they are all gathered, we can cleanse this place of the invasive wildlife.", ["objectivesText"] = "Receive Senegos 's special sight, then recover the missing tomes. Progress: Did you find my old tomes?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 202240, 202241, 202242 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199923, ["x"] = 0.622, ["y"] = 0.178 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199961, ["x"] = 0.638, ["y"] = 0.122 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 1, ["flags"] = 0 } } },
[72922] = { ["id"] = 72922, ["name"] = "Fading Embers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "This is a difficult situation, my friend. Wounds and insecurities cannot be easily dismissed. Only time--and cooperation--can soothe the sting born of longstanding rivalries. But there are more urgent matters to address. If there is a large force of drakonids still loyal to the memory of Neltharion, this land is much more dangerous than any of us expected. Emberthal still pursues Sarkareth--alone. She must be made aware of the threats that surround her. We must find her and give her aid.", ["objectivesText"] = "Help Emberthal stop Sarkareth at the Brimstone Garrison.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202523, ["x"] = 0.535, ["y"] = 0.302 }, { ["mapID"] = 2133, ["npcID"] = 202995, ["x"] = 0.535, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 51, ["flags"] = 0 } } },
[72923] = { ["id"] = 72923, ["name"] = "A Whisper to Sabellian", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "Our assault on Brimstone Garrison will not work without Sabellian and his relentless and mighty dragons. We must convince him that our objectives are aligned. If we appeal to him as a tactician and general, I'm sure he will help us... I hope. We will find him with his troops at the Djaradin Assault.", ["objectivesText"] = "Speak to Sabellian at the Djaradin Assault.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.483, ["y"] = 0.28225 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 52, ["flags"] = 0 } } },
[72924] = { ["id"] = 72924, ["name"] = "Appealing to the Black Prince", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "Our assault will not be successful without the stealth and cunning of Wrathion and his Blacktalon agents. We must convince him to help us. Thankfully, I know in his heart he will not deny someone in need--especially if they flatter him. Let us go to Wrathion at the Obsidian Rest and try to sway him.", ["objectivesText"] = "Speak to Wrathion at the Obsidian Rest. Progress: I only hope that his temper has cooled by now.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.483, ["y"] = 0.28225 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 53, ["flags"] = 0 } } },
[72925] = { ["id"] = 72925, ["name"] = "With Our Powers Combined", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "Emberthal is waiting for us in front of the Brimstone Garrison. Come, <name>. She will be pleased to see we have rallied the full might of the black dragonflight to aid her cause.", ["objectivesText"] = "Speak to Emberthal at the Brimstone Garrison.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 204447 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.483, ["y"] = 0.28225 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 54, ["flags"] = 0 } } },
[72926] = { ["id"] = 72926, ["name"] = "In the Right Hands", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "There are several weapons of historical value that I believed were lost to time. I would bet my talons that they are here at this garrison. The dragonspawn and drakonid loyally cling to the memory of my long-dead father. Misguided fools. They have access to my father's forges and weapons, and it is likely the very weapons I thought lost are stored nearby. If they find out what they have, they will use the weapons against us. They cannot remain in their claws.", ["objectivesText"] = "Retrieve the Ebon Eviscerator and the Resting Blade from the Brimstone Garrison. Progress: These fools must be parted with such powerful blades.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204184, 204877, 256197, 256205, 256213, 256221 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200101, ["x"] = 0.475333, ["y"] = 0.230667 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200101, ["x"] = 0.475333, ["y"] = 0.230667 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.475333, ["y"] = 0.230667 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 55, ["flags"] = 0 } } },
[72927] = { ["id"] = 72927, ["name"] = "Finding Sarkareth", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "Now that we have a foothold within the garrison, we can extend our search. We will hold off the forces of Aberrus here while you find Emberthal and aid her in reaching Sarkareth. We will join you as soon as we secure the front here.", ["objectivesText"] = "Meet Emberthal within the Aberrus Approach.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199964, ["x"] = 0.474, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.483, ["y"] = 0.28225 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 58, ["flags"] = 0 } } },
[72928] = { ["id"] = 72928, ["name"] = "Wipe Them Out", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "Do you know what I see when I gaze upon the Brimstone Garrison? Traitors. These soldiers believe themselves followers of the black dragonflight, yet they ignore us, the true heirs to Neltharion, and bend a knee to the specter of our malevolent father. This cannot be allowed to stand. Show them the error of their ways.", ["objectivesText"] = "Defeat the Brimstone forces loyal to Neltharion in the Brimstone Garrison. Progress: I know that I rule with an iron claw... but it is only because I see what must be done to preserve our people.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204193 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199973, ["x"] = 0.4572, ["y"] = 0.236 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199973, ["x"] = 0.4572, ["y"] = 0.236 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4572, ["y"] = 0.236 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 57, ["flags"] = 0 } } },
[72929] = { ["id"] = 72929, ["name"] = "Cracking His Shell", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "We have seen shields like this before. Sarkareth is drawing on the power of Aberrus to protect himself while he finds his way in. Cowardly, but clever. Disrupt the conduits that are supplying his shield power, and we should be able to reach him.", ["objectivesText"] = "Destroy the conduits generating the shield at the Aberrus Approach. Progress: We must bring that shield down!", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 224807 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199964, ["x"] = 0.474, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199964, ["x"] = 0.474, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 59, ["flags"] = 0 } } },
[72930] = { ["id"] = 72930, ["name"] = "Stopping Sarkareth", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "This is our last chance, <name>. If we allow Sarkareth to slip in to Aberrus, he may gain power that puts him beyond our reach. We must stop him now!", ["objectivesText"] = "Defeat the Dreadful Defender at the Aberrus Approach.", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 204195, 205998 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199964, ["x"] = 0.474, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199964, ["x"] = 0.474, ["y"] = 0.194 }, { ["mapID"] = 2133, ["npcID"] = 201728, ["x"] = 0.48, ["y"] = 0.12 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 60, ["flags"] = 0 } } },
[72931] = { ["id"] = 72931, ["name"] = "Forward Camp", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931 }, ["description"] = "Since Sarkareth now wields the power of Aberrus's defenses, he has an army that will shield him from us. The next step for us will be to establish a stronghold inside the garrison. That way we can search it without interruption. Meet me there.", ["objectivesText"] = "Find Ebyssian in the Brimstone Garrison. Progress: I have full faith we will carve a path through the garrison.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.483, ["y"] = 0.28225 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1396, ["name"] = "Inevitable Confrontation", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 56, ["flags"] = 0 } } },
[72934] = { ["id"] = 72934, ["name"] = "Lest We Forget", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "We will be joined shortly by Kalecgos and Alexstrasza. Before then, I have a request. There was a tradition to have gravestones set before your death. It allowed you to choose where you would rest when you passed. It was the job of the caretakers to update the gravestones and deposit the lingering essence of arcana at the site. Before our guests join us, would you help me in this task? Take this list, and these graves. Update the existing graves and place the new ones.", ["objectivesText"] = "Update the gravestones of the departed blue dragons.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 35709, 71086, 132409, 258990 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 199969, ["x"] = 0.666, ["y"] = 0.12 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 200447, ["x"] = 0.67, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.666, ["y"] = 0.12 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 3, ["flags"] = 0 } } },
[72935] = { ["id"] = 72935, ["name"] = "Archives Return", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "It is not unusual that Malygos and Sindragosa would have such powerful memories. From what I understand, their deaths were particularly painful. Both slain by adventurers. It breaks my heart to think of Sindragosa enduring death not once, but twice after being raised by the Lich King. But enough of this old dragon's ramblings. Stellagosa and I will meet you back at the Azure Archives.", ["objectivesText"] = "Return to Kalecgos in the Azure Archives.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["rewardItems"] = { 248651 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 200447, ["x"] = 0.67, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 4, ["flags"] = 0 } } },
[72936] = { ["id"] = 72936, ["name"] = "Azuregos's Support", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Many blue dragons have returned, and many others have informed me of their plans to make their ways to the Isles. There are a few key members of the flight, however, that I have not heard from. One of them may be able to help: Azuregos , stationed within the Nexus in Northrend. You, myself, and Sindragosa will travel to meet Azuregos . He has ignored all of my attempts to contact him from afar. Thanks to the oathstone being empowered, Sindragosa can now travel further than ever before.", ["objectivesText"] = "Travel to the Nexus in Northrend to meet Azuregos .", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 199976, ["x"] = 0.225, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 114, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 114, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 5, ["flags"] = 0 } } },
[72937] = { ["id"] = 72937, ["name"] = "Unusual Disruptions", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3537, ["mapID"] = 114, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Of course I can help track down the missing blue dragons. However, I have a mess on my hands that must be addressed first. Moments ago, several bursts of arcane energy swept through the Nexus, followed by attacks of strange arcane creations. I can create a method of tracking down the blue dragons if you can put down the locations of this wild arcana. Take this staff--do not break it--and use it on three locations within the Nexus. Oh, and prepare yourself for a fight.", ["objectivesText"] = "Put down strange arcane attackers in the Nexus. Progress: Do you need even more help? Just place the the staff at the disruption.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 205931, 258995, 258997, 258998 }, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 199976, ["x"] = 0.225, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 199976, ["x"] = 0.225, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.225, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 3537 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 114, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 6, ["flags"] = 0 } } },
[72938] = { ["id"] = 72938, ["name"] = "Archival Arrival", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 3537, ["mapID"] = 114, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "I have crafted a magical globe to help you find the remaining blue dragons. It should give you their rough locations. Now go. On top of everything else I was working on, I must now investigate these \"memories\" that attacked the Nexus. I shall get to the bottom of it.", ["objectivesText"] = "Return to the Azure Archives.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["rewardItems"] = { 204076 }, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 199976, ["x"] = 0.225, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.225, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 114, 2024 }, ["zone"] = { 3537 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 7, ["flags"] = 0 } } },
[72939] = { ["id"] = 72939, ["name"] = "Theramore", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72656, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72939, 72940, 73026, 73069, 73091, 73227, 73399, 73404, 73405, 73406, 75023 }, ["description"] = "According to Azuregos's notes, the blue dragon Surigosa was last seen investigating a sect of rogue mages known as the Sullied Banner. Surigosa's last missive stated that she intended to travel to the ruins of Theramore. Perhaps she uncovered traces of the Sullied Banner there. Either way, if Surigosa is to be found, Theramore seems the best place to search for her.", ["objectivesText"] = "Speak to Kalecgos about Surigosa's last known location.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 } }, ["db2AdventureMapPoiID"] = 185, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 16, ["flags"] = 0 } } },
[72940] = { ["id"] = 72940, ["name"] = "Where in the World is a Lost Blue Dragon?", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Azuregos has narrowed down the locations of the missing blue dragons. Each of us will handle finding several of them. I would entrust you to aid us in finding a few others. Choose where you'd like to go first.", ["objectivesText"] = "Choose an area to investigate the missing blue dragons.", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardItems"] = { 206162 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 }, { ["id"] = 334, ["title"] = "The Azure Span", ["questLineID"] = 6125, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 6125, ["name"] = "Welcome to the Waking Shore", ["orderIndex"] = 0, ["flags"] = 0 } } },
[72942] = { ["id"] = 72942, ["name"] = "Veiled Trouble", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "I was hoping that we would find a way to dispel these strange arcane memories from what remains of Malygos and Sindragosa. It appears they've grown more out of control than I expected. Please, accompany some of the gathered blue dragons to the Veiled Ossuary and help Azuregos . Sindragosa and I will remain here, and investigate what to do about this situation.", ["objectivesText"] = "Investigate the arcane disturbances within the Veiled Ossuary.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 200019, ["x"] = 0.662, ["y"] = 0.122 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1404, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1404, ["name"] = "United Again", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 53, ["flags"] = 0 } } },
[72946] = { ["id"] = 72946, ["name"] = "Veiled Ossuary Chaos", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Malygos and Sindragosa's essences have created this massive arcane disruption. Their memories are running around the Veiled Ossuary trying to drain the arcana out of the graves! Our combined efforts are merely keeping the energies at bay. We need the memories in the nearby area disrupted. Once they are dispelled, we should be able to remove this barrier to reach the essences inside.", ["objectivesText"] = "Weaken the arcane invader's control over the Veiled Ossuary. Progress: Hurry! We need to deplete the arcana in this area.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 200019, ["x"] = 0.662, ["y"] = 0.122 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 200019, ["x"] = 0.662, ["y"] = 0.122 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.122 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1404, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1404, ["name"] = "United Again", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 54, ["flags"] = 0 } } },
[72947] = { ["id"] = 72947, ["name"] = "Memories of Old", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Three incredibly powerful memories have formed throughout the Veiled Ossuary. Soon their energy will be so vast that they will be able to create their own arcane constructs... thus overwhelming this place. Take them down, so we can weaken this barrier and reach Malygos and Sindragosa's essences!", ["objectivesText"] = "Slay three powerful memories within the Veiled Ossuary. Progress: Have you handled those memories yet?", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 200019, ["x"] = 0.662, ["y"] = 0.122 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 200019, ["x"] = 0.662, ["y"] = 0.122 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.122 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1404, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1404, ["name"] = "United Again", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 55, ["flags"] = 0 } } },
[72948] = { ["id"] = 72948, ["name"] = "What Still Remains", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "The barrier is weakening, thanks to your aid. In a moment it will be broken down. Our main priority is recovering Malygos and Sindragosa's essences. Something has gone very wrong with laying them to rest. There are a few theories I have regarding their current state. We can speak about it as we enter. Let me know when you are ready.", ["objectivesText"] = "Go beyond the arcane barrier to recover Malygos and Sindragosa's essences. Progress: It seems the blue dragons still cannot leave behind our legacy.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 203183, 203184 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 200019, ["x"] = 0.662, ["y"] = 0.122 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 201061, ["x"] = 0.67, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.122 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1404, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1404, ["name"] = "United Again", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 56, ["flags"] = 0 } } },
[72949] = { ["id"] = 72949, ["name"] = "Swiftly to the Archives", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "I can hear the pained cries of rage and agony from these essences. I suspect this was triggered after attempting to put them to rest. They were dormant for a time, but the combined rage of both Malygos and Sindragosa merged together to create this phenomenon. Quickly, we must make for the Azure Archives and inform Kalecgos and Sindragosa of this! Together, we may be able to finally give them the peace that they deserve.", ["objectivesText"] = "Meet Kalecgos back within the Azure Archives.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["rewardItems"] = { 204076 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 201061, ["x"] = 0.67, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1404, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1404, ["name"] = "United Again", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 57, ["flags"] = 0 } } },
[72950] = { ["id"] = 72950, ["name"] = "The Last Conflict", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Malygos and myself both suffered horribly violent ends. The remains of our essences have been trapped in an endless loop. They must be reformed, and broken out of that loop. To do so will require a tremendous amount of concentrated power. We will have to utilize every amount of arcane energy within the Azure Archives... along with all of the assembled blue dragons. It is the only chance we have to reform these spirits... and to put an end to their suffering.", ["objectivesText"] = "Subdue the restless spirits of Malygos and Sindragosa within the Azure Vault.", ["rewardGold"] = 289300, ["rewardXP"] = 4925, ["rewardItems"] = { 197134, 259000 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186188, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 201128, ["x"] = 0.392, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1404, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1404, ["name"] = "United Again", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 59, ["flags"] = 0 } } },
[72951] = { ["id"] = 72951, ["name"] = "A Peaceful Farewell", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "It brightens my heart to see everyone reunited, and Malygos and Sindragosa at peace at long last. It is time that I give you all one last gift, something the blue dragons have not seen in quite some time. The peaceful passing of one of their own. It is my time, <name>. I should have flown beyond some time ago, but I could not leave with my kin still in disarray. Would you do an old dragon the honor of seeing me off on one last adventure?", ["objectivesText"] = "Speak with Senegos one last time.", ["rewardGold"] = 578600, ["rewardXP"] = 6155, ["rewardItems"] = { 205908, 205958, 205959, 205970, 259018, 259021, 259024, 259025 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 201125, ["x"] = 0.392, ["y"] = 0.636 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.636 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1404, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1404, ["name"] = "United Again", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 60, ["flags"] = 0 } } },
[72958] = { ["id"] = 72958, ["name"] = "Save-A-Mole", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72958, 72959, 72961, 72962, 72963, 72964, 72965, 74334, 74375, 75419 }, ["description"] = "Perisimona told me about her life-mate, Tuberros , and what she knows about his disappearance. Tuberros was guiding a client from the Dragonscale Expedition around some ruins here. It sounds as though they may have run into the Sundered Flame. I would rather not go after the Sundered Flame myself. Doing so would announce my presence to Sarkareth. Will you aid us by finding and rescuing Tuberros and his client? Maybe then he can help guide us to Neltharion's vault.", ["objectivesText"] = "Find and save Tuberros and his uplander client.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204587, 204595, 204603, 204611 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200049, ["x"] = 0.6016, ["y"] = 0.6984 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200049, ["x"] = 0.6016, ["y"] = 0.6984 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.6016, ["y"] = 0.6984 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1393, ["name"] = "Sundered Legacy", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 16, ["flags"] = 0 } } },
[72959] = { ["id"] = 72959, ["name"] = "Whose Vault Is It Anyway?", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72958, 72959, 72961, 72962, 72963, 72964, 72965, 74334, 74375, 75419 }, ["description"] = "I do not know what we will find in the vault or why Sarkareth wants access to it, but I hope we are not too late. Before we continue any further, Tuberros should lead Rannan and Perisimona back to Loamm. Come and talk to me once you are ready to move forward.", ["objectivesText"] = "Talk to Emberthal once you are ready to go.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200049, ["x"] = 0.6016, ["y"] = 0.6984 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201619, ["x"] = 0.625, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.6016, ["y"] = 0.6984 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1393, ["name"] = "Sundered Legacy", ["orderIndex"] = 3, ["flags"] = 1 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 18, ["flags"] = 0 } } },
[72961] = { ["id"] = 72961, ["name"] = "Charging Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72958, 72959, 72961, 72962, 72963, 72964, 72965, 74334, 74375, 75419 }, ["description"] = "Emberthal wanted this guy Sarkareth dealt with yesterday. I understand! I hate waiting too! This door is frustratingly hard to crack... But! I have a plan because I always have a plan! My recipe for success is being one step ahead of everyone else. It's worked for me so far! Sorta. So, about this plan... I might need your help!", ["objectivesText"] = "Gather 6 buzzing orb core for Rannan Korren . Progress: Were you able to get me some of those orbs?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204387, 204833 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200074, ["x"] = 0.625, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200074, ["x"] = 0.625, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.625, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1393, ["name"] = "Sundered Legacy", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 19, ["flags"] = 0 } } },
[72962] = { ["id"] = 72962, ["name"] = "Open That Door!", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72958, 72959, 72961, 72962, 72963, 72964, 72965, 74334, 74375, 75419 }, ["description"] = "I am glad we are making progress but... I cannot shake a sense of foreboding of what awaits us inside. As Sarkareth learns about Neltharion, his intentions seem to get ever darker... I can only imagine what he is telling his people now--about me and about the other dracthyr. He will fracture our people forever. Talk to Rannan and see how much longer we have to wait. We can't waste more time.", ["objectivesText"] = "Talk to Rannan about his progress.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201619, ["x"] = 0.625, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200075, ["x"] = 0.627, ["y"] = 0.735 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.625, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1393, ["name"] = "Sundered Legacy", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 20, ["flags"] = 0 } } },
[72963] = { ["id"] = 72963, ["name"] = "The Upper Hand", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72958, 72959, 72961, 72962, 72963, 72964, 72965, 74334, 74375, 75419 }, ["description"] = "It troubles me that Dezran would sacrifice himself so willingly for Sarkareth... And that Amythora and Marithos would leave Dezran to save him. We both know the loss of waking in a new world. But Sarkareth wallows in the darkness of our past. I cannot let him continue to recruit our people. Sarkareth awaits in the next room. I do not wish to kill him, but we must bring him to justice. Let me know when you are ready.", ["objectivesText"] = "Defeat Scalecommander Sarkareth .", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204582, 204590, 204598, 204606 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202857, ["x"] = 0.63, ["y"] = 0.74 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204571, ["x"] = 0.634, ["y"] = 0.746 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1393, ["name"] = "Sundered Legacy", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 22, ["flags"] = 0 } } },
[72964] = { ["id"] = 72964, ["name"] = "Singed", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72958, 72959, 72961, 72962, 72963, 72964, 72965, 74334, 74375, 75419 }, ["description"] = "Standing here, seeing these two Sundered Flame before me, there is no more anger. I see the confusion in their eyes and how they look at each other... They are so uncertain of their future. They remind me of myself and the moment I emerged alone, my creche dead and forgotten by passing ages. I have to talk to them, <name>. Will you accompany me? As a friend?", ["objectivesText"] = "Talk to Marithos and Amythora . Progress: I want to help them... be there for them when no one was there for me.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 204571, ["x"] = 0.634, ["y"] = 0.746 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200064, ["x"] = 0.633333, ["y"] = 0.744667 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.746 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1393, ["name"] = "Sundered Legacy", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 23, ["flags"] = 0 } } },
[72965] = { ["id"] = 72965, ["name"] = "Aspects of Our Legacy", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72958, 72959, 72961, 72962, 72963, 72964, 72965, 74334, 74375, 75419 }, ["description"] = "I am proud to see that Emberthal is blossoming into a confident leader once more. Her people need her. But that Sarkareth found Oathbinder is a reminder of the horrors of Neltharion's legacy and the folly of following him. I have a feeling that we will discover more than his trinkets and whispers here in these caverns. Come. We have much to discuss. Let us go back to Loamm and see if my brothers have found a way to subdue Fyrakk.", ["objectivesText"] = "Meet Ebyssian in Loamm.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204585, 204593, 204601, 204609, 205991 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202670, ["x"] = 0.634, ["y"] = 0.746 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199849, ["x"] = 0.566, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.746 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1393, ["name"] = "Sundered Legacy", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 24, ["flags"] = 0 } } },
[72970] = { ["id"] = 72970, ["name"] = "Niffen and Goliath", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "I didn't just come all the way out here to save your sniffers, ya know! The deepflayers are vicious and stubborn, like obsidian ore. We've tried to lead them from our town by leaving out food and such, but they're all too keen to attack our sparrow caravans. It's the big'un ruling over them that'll be trouble. Want to pay me back? Let's you, me, and your cologne-scented friend hunt it down together. I've got the perfect bait we can use too!", ["objectivesText"] = "Slay the Deepflayer Broodmatron .", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 204588, 204596, 204604, 204612 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201587, ["x"] = 0.602, ["y"] = 0.378 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201584, ["x"] = 0.590667, ["y"] = 0.377333 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 10, ["flags"] = 0 } } },
[72972] = { ["id"] = 72972, ["name"] = "The Waking Shores Reverse Tour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2022, ["storyline"] = { 72972 }, ["description"] = "It's time to send you backwards. Not backwards in time, although we could do that, but have you fly the courses in reverse. Get ready to see these courses in a different way. Let's start with Serohs Gnikaw! Wait. Waking Shores!", ["objectivesText"] = "Fly each of the reverse courses in Waking Shores.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193411, ["x"] = 0.732, ["y"] = 0.52 }, { ["mapID"] = 2025, ["npcID"] = 199120, ["x"] = 0.46, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193411, ["x"] = 0.732, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 2022, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[72974] = { ["id"] = 72974, ["name"] = "Welcome to the City of Smells", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "Ain't it incredible, uplander! Now for the backbreaking labor. We've got to deliver this deepflayer meat to all my customers and collect their pay. I'd carry it all myself, but I'm just a poor, old, frail, gorgeous woman in need now, aren't I? <Honeypelt gives you an expertly practiced wink.> Why don't you handle it for me? Brynnsahce will do the heavy lifting while you take a little tour of the place. Put your best smell forward--we're a friendly sort!", ["objectivesText"] = "Deliver deepflayer parcels around Loamm and return to Elder Honeypelt with the profits. Progress: It'd be a waste not to keep those nostrils open here in Loamm!", ["rewardGold"] = 619600, ["rewardXP"] = 6155, ["rewardItems"] = { 204448, 204449, 204450, 204451, 204452, 204453, 204455, 204456, 204457, 204458 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200054, ["x"] = 0.5728, ["y"] = 0.5488 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200054, ["x"] = 0.5728, ["y"] = 0.5488 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.5728, ["y"] = 0.5488 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 12, ["flags"] = 0 } } },
[72977] = { ["id"] = 72977, ["name"] = "Where the Flames Fell", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "The Aspects have requested our help. As protectors of the Isles and dragonkind, we are more than willing. I must locate Emberthal and ask her to join. I believe I can recruit her to our cause as long as we remain committed to hers against the Sundered Flame in the future. Meet Sabellian and Wrathion at the site of the Incarnates' devastation.", ["objectivesText"] = "Meet Sabellian and Wrathion in Cascades Canyon.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 201281, ["x"] = 0.6036, ["y"] = 0.4068 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201311, ["x"] = 0.872, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.6036, ["y"] = 0.4068 }, ["mapCandidates"] = { ["npc"] = { 2023, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 2, ["flags"] = 0 } } },
[72978] = { ["id"] = 72978, ["name"] = "Scar of Earth and Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "This centaur practically attacked us upon our arrival. He seems quite protective over this burning pile of ashes. I know you have worked alongside the Shikaar before. Would you speak to him? I would like to confirm what happened here. There is no chance that this is all a coincidence. If it connects to the Incarnates at all, we must learn all we can.", ["objectivesText"] = "Investigate the scene. Progress: Have you learned anything of value?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 201311, ["x"] = 0.872, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201311, ["x"] = 0.872, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.872, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 3, ["flags"] = 0 } } },
[72979] = { ["id"] = 72979, ["name"] = "The Earth Gives Way", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "You may stay here to see what comes of this relic, or meet me afterward in Loamm. That is Honeypelt's home, which she offered us respite at while you were still in the cave. I would only ask that you check on Wrathion . He may be a ceaselessly buzzing pest, yes, but... these recent events force me to admit I care for his well-being too. There are only so many black dragons left. We must look out for each other.", ["objectivesText"] = "Speak with Wrathion .", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201589, ["x"] = 0.605, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201583, ["x"] = 0.59, ["y"] = 0.377333 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 8, ["flags"] = 0 } } },
[72980] = { ["id"] = 72980, ["name"] = "Brother's Keeper", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "By my scales, I needed that win! That blasted Incarnate swatting us like flies did a number on my ego, and I assume Sabellian feels no different. As infuriating as I find his lack of humor, groaning voice, and ugly shoes... I would ask that you check in on him. He is still family, after all, and I do not wish him to become dinner to these deepflayers. Meet Honeypelt and I outside these dreadful nests when you finish up with Sabellian .", ["objectivesText"] = "Speak with Sabellian .", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["rewardItems"] = { 252754 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201583, ["x"] = 0.59, ["y"] = 0.377333 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201589, ["x"] = 0.605, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.377333 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 9, ["flags"] = 0 } } },
[72981] = { ["id"] = 72981, ["name"] = "The Patience of Princes", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "The centaur's report of Primalist forces pushing into the underground after Fyrakk changes the situation. Wrathion and I believe it would be a tactical mistake to dawdle here any longer, waiting for Ebyssian and his devotee to arrive. We still wish for you to join us. If you are ready, then we three should proceed together.", ["objectivesText"] = "Delve underground and fell the Primalist blockade.", ["rewardGold"] = 929400, ["rewardXP"] = 7390, ["rewardItems"] = { 204389 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 200085, ["x"] = 0.874, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.874, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2184, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 4, ["flags"] = 0 } } },
[72982] = { ["id"] = 72982, ["name"] = "The Ohn'ahran Plains Reverse Tour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72982 }, ["description"] = "Time to go forward to go backward once more. More races await you in Ohn'ahran plains . Head over there now, make sure you go in the right direction.", ["objectivesText"] = "Fly each of the reverse courses in Ohn'ahran Plains .", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193411, ["x"] = 0.732, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 199118, ["x"] = 0.88, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 2022, 2023 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[72984] = { ["id"] = 72984, ["name"] = "The Azure Span Reverse Tour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 72984 }, ["description"] = "The next set of backward courses are back in the Azure Span . When you're ready you should head back over there and retrace your previous steps to the previous races.", ["objectivesText"] = "Fly each of the reverse courses in the Azure Span .", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 199118, ["x"] = 0.88, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 199119, ["x"] = 0.632, ["y"] = 0.136 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.88, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 2023, 2024 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[72985] = { ["id"] = 72985, ["name"] = "The Thaldraszus Reverse Tour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72985 }, ["description"] = "Once more you'll be heading back to where it all finished. Or started. I can't remember anymore. Seek out my bronze colleagues to fly the reverse courses to complete your rewinding.", ["objectivesText"] = "Fly each of the reverse courses in Thaldraszus .", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 199119, ["x"] = 0.632, ["y"] = 0.136 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199120, ["x"] = 0.46, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.136 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[72988] = { ["id"] = 72988, ["name"] = "The Booty Bay Journal", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72988, 73181 }, ["description"] = "You will not believe who I read about today in the Booty Bay Journal. What is that look, $p? I too enjoy light reading about world affairs. Booty Bay is fascinating! Regardless, I read about Zeros --he was once the captive of an evil mage who hated all blue dragons. He seems to have found his own way in the world since his rescue. A bit of advice for you, young one. Debt is a foolish thing to be in, especially in Booty Bay, and especially to the Baron. Let's retrieve him before the sharks do.", ["objectivesText"] = "Speak to Senegos to temporarily neutralize your standing with Booty Bay, and then find Zeros in Booty Bay in the Eastern Kingdoms.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 186240, ["x"] = 0.588, ["y"] = 0.482 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 199185, ["x"] = 0.421333, ["y"] = 0.747333 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 210, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1401, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 210, ["questLines"] = { { ["id"] = 1401, ["name"] = "Chapter 3A - Booty Bay", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 36, ["flags"] = 0 } } },
[72989] = { ["id"] = 72989, ["name"] = "The Ruby Hatchling", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72989 }, ["description"] = "An egg from the red dragonflight is ready to hatch. Report to Amella in the Ruby Lifeshrine to pick up the egg. Then, I request that you bring the egg to the Ruby Oathstone to hatch in a location strong with our flight's power. Once this is complete, return here with the hatchling, where we will further take care of it.", ["objectivesText"] = "Collect the Red Dragon Egg at the Ruby Lifeshrine then hatch it at the Ruby Oathstone. Progress: Have you brought the newest hatchling?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72990] = { ["id"] = 72990, ["name"] = "Crimson Comfort", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72990 }, ["description"] = "I am looking forward to our red whelp. They are, after all, my specialty! I have already spoken with Amella, and I would like to handle the nest myself. Here is a list of materials. Bring them to me when you are done, and I can fashion the most comfortable cushion you have ever seen! < Lasztak hands you a list of supplies.>", ["objectivesText"] = "Gather supplies for the Ruby Hatchling's nest. Progress: Red whelplings are my specialty.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 202697, 203712, 204869, 204870 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72991] = { ["id"] = 72991, ["name"] = "Warm Dragonfruit Pie", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72991 }, ["description"] = "When I think of red dragon comfort food, I immediately think of the pies back at the Ruby Life Pools. You can always tell when our blacksmith, Krendisc, has downtime between orders--the entire mountain smells of delicious baked dragonfruit! My pie may not be as good as his, but I am sure our ruby hatchling will love it. If you bring me the ingredients I will bake the best pie I can!", ["objectivesText"] = "Gather Ripened Dragonfruit near the Ruby Life Pools and Pre-Made Pie Crust from Erugosa in Valdrakken, then bring them to Lasztak to bake a pie for the Ruby Hatchling. Progress: < Lasztak cracks his knuckles.> It has been a while since I baked anything, but I am confident!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193826, 202693, 204868 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72992] = { ["id"] = 72992, ["name"] = "You're Playing Wrong!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72992 }, ["description"] = "Our red hatchling seems to be having quite the trouble making friends. Any time she tries to get one to play, it tends to end quickly. She can be a bit pushy, but whelps are whelps. Why don't you get her in the right mindset to play with some tag?", ["objectivesText"] = "Play with the Ruby Hatchling . Progress: Every whelp loves a game of tag!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72993] = { ["id"] = 72993, ["name"] = "I'm the Boss!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72993 }, ["description"] = "Never have I met such a bossy child! She has a list. A list! Please, take Belastrasza off our claws for a bit. I just... I need to sit down.", ["objectivesText"] = "Assist Belastrasza . Progress: <The bags under Agapanthus 's eyes are even deeper than usual.>", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 158639, 158640, 158642, 158643, 158644, 158645, 158648, 158649, 160207, 184519, 202173, 202250, 219766, 219767, 219768, 219769, 224784, 228654, 228655, 228656, 228657, 237812, 246815, 254677, 256763, 258265 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72994] = { ["id"] = 72994, ["name"] = "A Cavalier Pet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72994 }, ["description"] = "I believe that the only way we can teach Belastrasza to be less self-obsessed is to show her firsthand how it makes others feel. Vorquin are beautiful creatures, but they are incredibly high maintenance companions who need a lot of care. Lysindra in Valdrakken has a baby vorquin for Bela. Perhaps she will learn through getting a taste of her own medicine.", ["objectivesText"] = "Obtain a Baby Vorquin battle pet for Belastrasza. Progress: A stubborn pet for a stubborn whelp.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72995] = { ["id"] = 72995, ["name"] = "Patience, Please", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72995 }, ["description"] = "Belastrasza has learned much through her vorquin foal, but I have thought of one more lesson that should be excellent for her. Her lack of patience has been stumping me for quite some time. Recently I was reflecting by the water, watching the turtles go about their day. Then I was hit by a revelation! Wurallie has the perfect battle to test Belastrasza 's patience, but poor Princess Vorquistrasza doesn't have the endurance. Can you meet them in the Waking Shores to lend a hand?", ["objectivesText"] = "Help Belastrasza learn patience by defeating a turtle in a pet battle. Progress: Slow and steady, Bela. Slow and steady.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 205232, 206758 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72996] = { ["id"] = 72996, ["name"] = "The Bronze Hatchling", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72996 }, ["description"] = "An egg from the bronze dragonflight is ready to hatch. Report to Xius in the Ruby Lifeshrine to pick up the egg. Then, I request that you bring the egg to the Bronze Oathstone to hatch in a location strong with their flight's power. Once this is complete, return here with the hatchling, where we will further take care of it.", ["objectivesText"] = "Collect the Bronze Dragon Egg at the Ruby Lifeshrine then hatch it at the Bronze Oathstone. Progress: Have you brought the newest hatchling?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72997] = { ["id"] = 72997, ["name"] = "Nothing Like a Sandy Nap", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72997 }, ["description"] = "While red dragons enjoy their surroundings lush and lively, bronze dragons prefer their environments dry and sandy. I am sure you can find many materials for our hatchling's nest in the Temporal Conflux in Thaldraszus. I have read that bronze whelps also enjoy an appropriately sized basin to curl themselves in. My friend at the inn in the Bronze Enclave has exclaimed often about an excess of bowls... I am sure she would not mind if we took one off her hands.", ["objectivesText"] = "Gather supplies for the Bronze Hatchling's nest. Progress: Bronze dragons are like cats. They defy time and space.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 202643, 202644, 202645 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72998] = { ["id"] = 72998, ["name"] = "Artisanal Aging", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72998 }, ["description"] = "I have been learning much about bronze dragons since arriving in Valdrakken. While they take their charge of time seriously, they have found many hobbies for their free time that their magic can aid them with. My friend Gorgonzormu swears by his cheeses for all stages of dragon life. He mentioned that he has a type of parmesan that is excellent for bronze whelps. It seems that our hatchling's first meal is figured out!", ["objectivesText"] = "Buy Temporal Parmesan from Gorgonzormu in Valdrakken for the Bronze Hatchling. Progress: Cheese is best when aged over time, but bronze dragons have perfected rapid aging with their control of time!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 201415 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72999] = { ["id"] = 72999, ["name"] = "Here? There? Everywhere!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72999 }, ["description"] = "Our bronze hatchling has been staying away from the other whelps, mostly hanging out in the sand. Sometimes we find him in the sandbox with the others, but we never see him moving around! He could use some friendship. Why don't you treat him to a game of tag?", ["objectivesText"] = "Play with the Bronze Hatchling . Progress: Every whelp loves a game of tag!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73000] = { ["id"] = 73000, ["name"] = "Sneezing Through Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73000 }, ["description"] = "Zhusa is throwing us for quite the loop, <name>. Since he is so young, his control over time is not fully developed. Unfortunately, he has a strange reflex. Every time he sneezes he disappears, popping up elsewhere in any form! To top it off, he seems to have many allergies. Please, help Zhusadormu figure out what he is allergic to so we can keep him in one place!", ["objectivesText"] = "Find Zhusadormu throughout Valdrakken. Progress: < Agapanthus rubs his temples.> Oh, bronze whelps...", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73001] = { ["id"] = 73001, ["name"] = "A Scaly Pet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73001 }, ["description"] = "We have been trying to decide on the perfect pet for Zhusadormu. His allergies limit our options by quite a bit, but I believe I have thought of a pet for him. I know for a fact that Zhusa is not allergic to scales. A baby hornswog is hypoallergenic and I believe Lysindra could acquire one for us.", ["objectivesText"] = "Obtain a Baby Hornswog battle pet for Zhusadormu. Progress: The whelps love hornswogs. They will love having one in the daycare!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73002] = { ["id"] = 73002, ["name"] = "Temporal Immunity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73002 }, ["description"] = "Zhusadormu has been trying hard to keep his powers in check. While we may not be able to prevent his allergies, he does not have to jump through time with each sneeze. Wurallie believes she can test his control. Please go to the Waking Shores and help them with this lesson.", ["objectivesText"] = "Help Zhusadormu confront his allergies during a pet battle. Progress: I believe in Zhusa. I hope you do too.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 206971 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73003] = { ["id"] = 73003, ["name"] = "The Azure Hatchling", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73003 }, ["description"] = "An egg from the blue dragonflight is ready to hatch. Report to Axkall in the Ruby Lifeshrine to pick up the egg. Then, I request that you bring the egg to the Azure Oathstone to hatch in a location strong with our flight's power. Once this is complete, return here with the hatchling, where we will further take care of it.", ["objectivesText"] = "Collect the Blue Dragon Egg at the Ruby Lifeshrine then hatch it at the Azure Oathstone. Progress: Have you brought the newest hatchling?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73004] = { ["id"] = 73004, ["name"] = "A Scholar's Delight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73004 }, ["description"] = "Blue dragons are seekers of knowledge, even from an early age. They seem drawn to books and scrolls, finding the most comfort when surrounded by them. For our azure hatchling, the best nest is truly amongst our many books. I request that you collect the following for his nest--a quill of his own to learn to write, something to keep him nice and cold, and a bedtime story from Azure Span. I have heard tale of one that many blue dragons remember fondly.", ["objectivesText"] = "Gather supplies for the Azure Hatchling's nest. Awakened Frost can be collected from many elementals across the Dragon Isles, created by combining 10 Rousing Frost, or bought from the auction house. Progress: I have raised dozens of blue whelps at all stages of life. At this point, their needs are second nature to me.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 190329, 202330, 202332 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73005] = { ["id"] = 73005, ["name"] = "Crystal Nutrition", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73005 }, ["description"] = "Yes, blue dragons eat normal food, but the most important part of their diet is magical in nature. Wherever the blue flight can be found, you can be sure there is a source of nutritious ley crystals nearby. Of course, the homelands of the blue dragons became home to many others during their absence. The brackenhide gnolls have settled in our lands with the most ley crystals and taken them for themselves. You will need to enter their camps to reclaim the crystals for our whelp.", ["objectivesText"] = "Gather 6 Bite-Sized Ley Crystals from Brackenhide Hollow for the Azure Hatchling. Progress: From the moment they hatch, dragons have incredibly sharp teeth.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 202404 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73006] = { ["id"] = 73006, ["name"] = "Well, Actually...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73006 }, ["description"] = "As expected, our dear blue whelp is quite the little \"bookwyrm\". I knew many hatchlings just like him in Aszuna, though we only had a small collection of scrolls. While there are books aplenty here in Valdrakken, whelps need to get up and moving! Why don't you play some tag?", ["objectivesText"] = "Play with the Azure Hatchling .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73007] = { ["id"] = 73007, ["name"] = "New Lenses", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73007 }, ["description"] = "Zalethgos is a bright child, but as he has gotten older we have realized something very clear about him. He has terrible eyesight! He is constantly speaking of things being fuzzy and of not being able to tell where one thing ends and the next begins. There is a salon just across the bridge in Valdrakken. Please, accompany Zalethgos to try to find him the perfect pair of glasses to aid his vision.", ["objectivesText"] = "Bring Zalethgos to the Victorious Visage in Valdrakken to find a suitable pair of glasses. Progress: I look forward to Zalethgos learning that sharp edges exist!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 202409 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73008] = { ["id"] = 73008, ["name"] = "A Scholar's Pet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73008 }, ["description"] = "Long ago in Aszuna, young blue whelps from Azurewing Repose often studied magic alongside the elves of Nar'thalas Academy. I have many fond memories of the place, but one stands out among the others. The enchanted books, while excellent to study, were quite the rascals. I have heard Lysindra acquired a similar book. I think this would be the perfect pet for Zalethgos!", ["objectivesText"] = "Obtain an Enchanted Book pet for Zalethgos. Progress: Enchanted books are the perfect companions. They are full of magic, knowledge, and fun! Additionally, you do not need to feed them.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73009] = { ["id"] = 73009, ["name"] = "Sight Isn't Everything", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73009 }, ["description"] = "Since getting his glasses, Zalethgos has been relying heavily on his eyesight. Of course, this is normal, but he needs to remain flexible in case he loses them. I believe it is time to turn out the lights. I think Wurallie has the perfect trick. She believes she can teach Zalethgos to find victory even when he cannot use his eyes. Please join them in the Waking Shores.", ["objectivesText"] = "Help Zalethgos overcome his insecurity about his eyesight. Progress: In order to grow into a well-rounded dragon, Zalethgos must use everything at his disposal.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 206974 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73010] = { ["id"] = 73010, ["name"] = "The Emerald Hatchling", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73010 }, ["description"] = "An egg from the green dragonflight is ready to hatch. Report to Zahkrana in the Ruby Lifeshrine to pick up the egg. Then, I request that you bring the egg to the Emerald Oathstone to hatch in a location strong with their flight's power. Once this is complete, return here with the hatchling, where we will further take care of it.", ["objectivesText"] = "Collect the Green Dragon Egg at the Ruby Lifeshrine then hatch it at the Emerald Oathstone. Progress: Have you brought the newest hatchling?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73011] = { ["id"] = 73011, ["name"] = "Home Sweet Dirt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73011 }, ["description"] = "Green dragons prefer a home that is both natural and mystical, imbued with the power of the Emerald Dream. The Emerald Gardens will certainly have many materials with which to build an appropriate nest for this little one. Perhaps we should speak to a member of their flight to find something to bring them comfort as well.", ["objectivesText"] = "Gather supplies for the Emerald Hatchling's nest. Progress: We will have to maximize this hatchling's comfort to allow them to rest well and grow.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 67108, 202694, 202695, 202696 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73013] = { ["id"] = 73013, ["name"] = "So... Tired...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73013 }, ["description"] = "I have some worries about our new green friend. They are not sleeping as much as most green whelps tend to do. They seem to be having trouble sleeping. Why don't you get them up and moving around with a game of tag?", ["objectivesText"] = "Play with the Emerald Hatchling . Progress: Every whelp loves a game of tag!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73014] = { ["id"] = 73014, ["name"] = "A Green Who Can't Sleep?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73014 }, ["description"] = "<name>... we have a problem. Posidriss has insomnia. I did not even know it was possible for a green dragon to not be able to fall asleep! How are they to learn to protect the Dream if they cannot enter it? Please, try anything you can think of to help Posidriss fall asleep.", ["objectivesText"] = "Try to help Posidriss fall asleep. Progress: Every green dragon needs to be able to sleep!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 196584, 203621 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73015] = { ["id"] = 73015, ["name"] = "A Sleepy Pet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73015 }, ["description"] = "Posidriss's sleeping troubles are still causing them many problems. This is preventing them from developing their connection to the Dream. Bears hibernate, bears dream, bear cubs are soft, warm and cuddly. Some of the cubs in the Dragon Isles are even connected to the Dream. Can you fetch one from Lysindra for Posidriss?", ["objectivesText"] = "Obtain a Bear Cub pet for Posidriss. Progress: Where there are bears, there are druids. And where there are druids, there are green dragons!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73016] = { ["id"] = 73016, ["name"] = "Hibernation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73016 }, ["description"] = "Posidriss 's companion has been helping them with their severe insomnia, but I worry that they are still falling behind other whelps in their connection to the Dream. Perhaps we can aid them through a pet battle! Green dragons often protect the Dream from the Nightmare, and Wurallie has found the perfect critter for them to practice this on. It is mostly harmless.", ["objectivesText"] = "Help Posidriss defeat the Nightmare critter.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 206979 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73021] = { ["id"] = 73021, ["name"] = "A Lesson in Responsibility", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73021 }, ["description"] = "The daycare is always looking for new activities to enrich the education of the whelps. Lasztak has suggested a class pet might help teach the whelps responsibility. Sir Pringly has been my personal companion for some time, and I believe his calm demeanor and sense of fun would serve the position well. Sir Pringly will need his own habitat for the daycare, however. If you would gather materials, we can prepare a space just for him.", ["objectivesText"] = "Gather materials for Sir Pringly's habitat. Progress: There is a particular way that Sir Pringly likes his habitat constructed. If you get the materials I listed, he should like it.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 203445, 203446, 203451 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73026] = { ["id"] = 73026, ["name"] = "Booty Bay", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Land of pirates, swindlers, and raiders! Zeros, once just a captive whelpling, has built a mighty reputation as an auction house trader in one of the most cutthroat places on Azeroth. However, his recent investment blunder made the front page of the Booty Bay Journal. Rescue him before his debt is collected by the Baron.", ["objectivesText"] = "Speak to Senegos for more information.", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 186240, ["x"] = 0.588, ["y"] = 0.482 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2AdventureMapPoiID"] = 189, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 37, ["flags"] = 0 } } },
[73036] = { ["id"] = 73036, ["name"] = "Medicinal Fungi", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "When we happened upon these poor souls, it was clear they were attacked by djaradin. The poison on those brutes' weapons is preventing me and their leader, Narvra, from healing them. I noticed peculiar mushrooms on some crystals nearby. I have seen their like before, and I may be able to fashion an antidote from them. Can you harvest some while Voraxian and I keep watch here?", ["objectivesText"] = "Collect 10 Drooping Mushroom Cuttings from the Viridian Throne. Progress: Do you have the cuttings? I'm not sure how long these poor people have.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 202873 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200298, ["x"] = 0.465, ["y"] = 0.4805 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200298, ["x"] = 0.465, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 0, ["flags"] = 0 } } },
[73037] = { ["id"] = 73037, ["name"] = "Healing Crystals", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "Greetings! Apologies if I seem... distracted. I have been beside myself worrying about my injured friends. But maybe you, gentle<class>, can assist us? Narvra needs aid in healing us. Shards from crystal elementals have healing properties. I feel terrible asking to harm a fellow elemental, but if you could... obtain some from them, that would greatly aid my friends. Don't worry--the elementals will regenerate in time. My friends' needs come first, however impolite our gathering methods may be.", ["objectivesText"] = "Collect 10 Viridian Heartcrystals from enemies in the Viridian Throne. Progress: Have you retrieved the crystals? I'm worried about Butterfingers; he's not doing well.", ["rewardGold"] = 289300, ["rewardXP"] = 4925, ["rewardItems"] = { 24129, 24130, 24131, 131819, 203012 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200291, ["x"] = 0.428667, ["y"] = 0.566 }, { ["mapID"] = 2133, ["npcID"] = 203176, ["x"] = 0.534667, ["y"] = 0.794667 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 1, ["flags"] = 0 } } },
[73038] = { ["id"] = 73038, ["name"] = "A Room Without a View", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "This vault is of Black Dragon make which means its contents are my flight's property. Normally I would have suggested we venture in together, but I was not expecting aggressive watchers. I will protect Rupert while you search for artifacts for us to examine. To keep you safe, I will cast a spell on you I use when fighting the gronn.", ["objectivesText"] = "Recover artifacts from the Buried Vault. Progress: Did you find anything of interest?", ["rewardGold"] = 232300, ["rewardXP"] = 3695, ["rewardItems"] = { 203394, 203395, 203396 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200290, ["x"] = 0.4892, ["y"] = 0.6112 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200290, ["x"] = 0.4892, ["y"] = 0.6112 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4892, ["y"] = 0.6112 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 2, ["flags"] = 0 } } },
[73039] = { ["id"] = 73039, ["name"] = "Restless Death", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "What could lead someone to do this... I can perform a ritual that might aid these poor creatures passing on. Take these totems and place them along the river. With enough anchor points, I should be able to help them move on. We'll move ahead to look for a ritual site.", ["objectivesText"] = "Place anchor totems in the Acidbite Ravine to allow Narvra to start a cleansing ritual. Progress: Have you placed the anchor totems?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4655, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 7, ["flags"] = 0 } } },
[73040] = { ["id"] = 73040, ["name"] = "Bringing Disorder to Order", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "How incredibly rude! I know we did not bring gifts, but this is hardly the way to greet visitors! There is no excuse for such terrible manners! Scoundrels! Cads! Brutes! <Rupert coughs into his hand.> What I meant to say was these watchers appear to be a threat. Anyone who tunnels in here could be in danger. Would you be able to make this place safer by eliminating them?", ["objectivesText"] = "Eliminate 6 Enraged Watchers in the Buried Vaults.", ["rewardGold"] = 216900, ["rewardXP"] = 3695, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 203176, ["x"] = 0.534667, ["y"] = 0.794667 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200291, ["x"] = 0.428667, ["y"] = 0.566 }, { ["mapID"] = 2133, ["npcID"] = 203176, ["x"] = 0.534667, ["y"] = 0.794667 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.534667, ["y"] = 0.794667 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 3, ["flags"] = 0 } } },
[73041] = { ["id"] = 73041, ["name"] = "Respite", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "Thank you for everything you have done for us. We've been able to get back on our feet now, and Butterfingers has cooked up a meal. We lost a member of our team and everyone is still a bit shaken... We could do with the morale boost of a good meal. Would you like to join us?", ["objectivesText"] = "Join the Dragonscale team in the Zaralek Cavern for a meal. Progress: Thank you, <name>. I think we needed that small break.", ["rewardGold"] = 154900, ["rewardXP"] = 2465, ["rewardItems"] = { 168846, 197855, 237812 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4655, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 4, ["flags"] = 0 } } },
[73042] = { ["id"] = 73042, ["name"] = "A Tower Yonder", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "$p, I... don't want to ask more of you, but could you help us finally complete our mission? We were ordered to investigate the Gaze of Neltharion. We were defeated on our first approach, but with an escort of two dragons and the mighty $p, I'm not as worried about the djaradin. I want us to move out soon. Could you scout out the tower first for us?", ["objectivesText"] = "Investigate the Gaze of Neltharion in the Sulfur Wastes. Progress: Did you scout out the tower?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204334 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4655, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 5, ["flags"] = 0 } } },
[73043] = { ["id"] = 73043, ["name"] = "A Ghastly Legacy", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "We need to give these creatures peace. While you are down there assisting Voraxian, please end their suffering. Even a temporary release from this existence will help relieve their burden. In the meantime, Narvra can work on her ritual.", ["objectivesText"] = "Eliminate 10 Ghostly Researchers and Failed Experiments in the Acidbite Ravine.", ["rewardGold"] = 289300, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200298, ["x"] = 0.465, ["y"] = 0.4805 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200298, ["x"] = 0.465, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 6, ["flags"] = 0 } } },
[73044] = { ["id"] = 73044, ["name"] = "Cataloging Horror", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "I... I need to bring the evidence of this insanity back to my flight. It may destroy us, but my people need to know what happened here. I borrowed some cataloging cameras from Tellywin. Can you join me in documenting these atrocities? I can provide you with a similar protection to that which I gave in the vault. I will leave any fighting to you; I cannot bring myself to cause any more suffering than my flight has already wrought. Let us be done with this as swiftly as possible.", ["objectivesText"] = "Use the Cataloging Camera to take pictures of experiment dumping sites in the Acidbite Ravine. Progress: I can barely believe what was done here...", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 204698 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200290, ["x"] = 0.4892, ["y"] = 0.6112 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4892, ["y"] = 0.6112 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 8, ["flags"] = 0 } } },
[73045] = { ["id"] = 73045, ["name"] = "Stain Removal", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "We can begin the ritual whenever you are ready. Let's help these spirits pass on.", ["objectivesText"] = "Complete the cleansing ritual. Progress: We need to complete this ritual, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 205254 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4655, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 9, ["flags"] = 0 } } },
[73046] = { ["id"] = 73046, ["name"] = "Cavernous Capers", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73036, 73037, 73038, 73039, 73040, 73041, 73042, 73043, 73044, 73045, 73046 }, ["description"] = "While we wait for Veritistrasz and Narvra to nurse the rest of the camp back to health, I thought we might take a short jaunt. I sensed a cavern on our way here, and... I feel like I may need a bit of spelunking to take my mind off what just happened... Fancy joining me?", ["objectivesText"] = "Travel with Rupert from the Dragonscale Camp in the Zaralek Cavern . Progress: Well! I say! Gosh!", ["rewardGold"] = 70225, ["rewardXP"] = 1230, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200291, ["x"] = 0.428667, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203176, ["x"] = 0.534667, ["y"] = 0.794667 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5353, ["name"] = "The Dragons and the Scale Expedition", ["orderIndex"] = 10, ["flags"] = 0 } } },
[73047] = { ["id"] = 73047, ["name"] = "Terrestrial Tunneling", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73047 }, ["description"] = "I have to say that I am quite done with this place. Would you like to return to camp?", ["objectivesText"] = "Return to the Dragonscale Expedition camp in the Zaralek Cavern .", ["rewardGold"] = 77400, ["rewardXP"] = 1230, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 203176, ["x"] = 0.534667, ["y"] = 0.794667 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200291, ["x"] = 0.428667, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.534667, ["y"] = 0.794667 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[73064] = { ["id"] = 73064, ["name"] = "Spellwrought Snowman", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["storyline"] = { 73064 }, ["rewardXP"] = 4115, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[73069] = { ["id"] = 73069, ["name"] = "Sindragosa and Malygos's Rest", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "The preparations are now complete. Kalecgos and Alexstrasza should be here soon with the remaining essences of Sindragosa and Malygos. Both suffered such violent ends. I heard even with his last breath, Malygos cursed Alexstrasza. And Sindragosa--she was slain ten thousand years ago by Nelthar... by Deathwing. Yet she was reanimated by the Lich King and slain by adventurers. I can only imagine the state this essence is in... Forgive my ramblings. Kalecgos and Alexstrasza should be here shortly.", ["objectivesText"] = "Observe Kalecgos and Alexstrasza putting Sindragosa and Malygos's remains to rest.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 200447, ["x"] = 0.67, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 200007, ["x"] = 0.67, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 9, ["flags"] = 0 } } },
[73077] = { ["id"] = 73077, ["name"] = "This Might Sting", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73077 }, ["description"] = "Relax. This Sundered Flame is merely poisoned. He won't die. Probably. He will just be in pain. < Patroclosa looks at you, then sighs.> I suppose if you wanted to spare him this fate, you could collect bile from the Quartzite Sporebats that roam this valley. It contains a natural antivenom that would ease his suffering. But I will not waste my healing magic on a murderer. And you may as well bring back loamshrooms, to help him keep the bile down. Though it's a kindness he doesn't deserve.", ["objectivesText"] = "Collect 8 Spongy Loamshrooms and 6 helpings of Quartzite Spore Bile . Progress: We all have to find our own path. I just wish ours was a little bit easier...", ["rewardGold"] = 303800, ["rewardXP"] = 4925, ["rewardItems"] = { 203393, 204088 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200550, ["x"] = 0.594, ["y"] = 0.638 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200582, ["x"] = 0.594, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.594, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[73081] = { ["id"] = 73081, ["name"] = "Stress Fractures", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73081 }, ["description"] = "Another member of the Sundered Flame has been apprehended on Scalecommander Emberthal's behalf. A messenger, Amythora thinks. We must decide what to do with him. In the meantime, it would be helpful if you could see if he has any important information. He is well-guarded, so don't worry about him putting up a fight. Some passing Dracthyr offered their aid-- said they were companions of the Scalecommander! And they knew just how to handle Sundered Flame prisoners.", ["objectivesText"] = "Investigate the captured Sundered Flame messenger. Progress: I know you want me to talk, but I can't. Whatever you do to me, Sarkareth's punishment would be a thousand times worse.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 203233, ["x"] = 0.564, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200876, ["x"] = 0.556, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[73085] = { ["id"] = 73085, ["name"] = "Cold Feet", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73085 }, ["description"] = "If Marithos and Amythora want to run off and play adventurer, that's their choice. I have a sense of loyalty. <Despite his bold words, the messenger looks uncertain.> You don't know what Sarkareth is capable of, all right? Look through my things and draw whatever conclusions you'd like. But I won't tell you anything. I can't.", ["objectivesText"] = "Examine the apprehended dracthyr's belongings for clues about the Sundered Flame. Progress: Did you find anything? And why do you look like you've been in a scuffle? ...Oh. I see. That's quite troubling. < Marithos sighs.>", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204436 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200876, ["x"] = 0.556, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203233, ["x"] = 0.564, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[73086] = { ["id"] = 73086, ["name"] = "Healthy Competition", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73086 }, ["description"] = "More of my creche mates have been welcomed under Emberthal's leadership, but there are still tensions between the former Sundered Flame and the dracthyr we've hurt. Fortunately, I think I've found a way to work out those tensions in a productive, dracthyrian method that will reinforce our bonds as evokers. Sparring! Now, come on. Try me! We can show all these louts how it's done.", ["objectivesText"] = "Beat Amythora at sparring.", ["rewardGold"] = 262100, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203325, ["x"] = 0.262, ["y"] = 0.356 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 203325, ["x"] = 0.262, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.262, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73090] = { ["id"] = 73090, ["name"] = "Regrets in Crystal", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72670, 72674, 72679, 73090, 74783 }, ["description"] = "I have some idea of what Lanigosa might be doing in Crystalsong Forest, although I cannot imagine why she has taken it upon herself to do it. That forest conceals within it the ruins of Shandaral, a former highborne settlement and the site of one of the mortal race's first clashes with the blue dragonflight. If Lanigosa truly is in Crystalsong, then it may well have something to do with Shandaral. Seek her out there, <name>, and try to convince her to return to us.", ["objectivesText"] = "Speak to Lanigosa in Crystalsong Forest.", ["rewardGold"] = 280900, ["rewardXP"] = 615, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 127, ["npcID"] = 199184, ["x"] = 0.914, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 127, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1399, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 127, ["questLines"] = { { ["id"] = 1399, ["name"] = "Chapter 2A - Crystalsong Forest", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 26, ["flags"] = 0 } } },
[73091] = { ["id"] = 73091, ["name"] = "Crystalsong Forest", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72656, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72939, 72940, 73026, 73069, 73091, 73227, 73399, 73404, 73405, 73406, 75023 }, ["description"] = "The blue dragon Lanigosa lent her aid to mortals during the most recent war against the Burning Legion. However, she failed to respond to the call of the Isles. Has something befallen her? Or has she simply chosen not to return? Whatever her reasons, Azuregos's globe seems to suggest that she was last seen in Crystalsong Forest.", ["objectivesText"] = "Speak to Kalecgos .", ["rewardGold"] = 28090, ["rewardXP"] = 615, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 } }, ["db2AdventureMapPoiID"] = 187, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 19, ["flags"] = 0 } } },
[73093] = { ["id"] = 73093, ["name"] = "Empty Chairs", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73093 }, ["description"] = "I don't want to detract from the festivities, but there's someone missing who should be here. This is a time for all dracthyr to come together, but Rathane might not see it that way-- he was Sundered Flame, just like us. And though he left them after what happened at the Aberrus, I fear he's still grappling with the guilt. He seemed rather distressed. Would you go find him? And make sure he's alright, and that he knows he's welcome?", ["objectivesText"] = "Find Rathane .", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204824, 204830, 205252 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203629, ["x"] = 0.2392, ["y"] = 0.36 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 203852, ["x"] = 0.242, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.2392, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73119] = { ["id"] = 73119, ["name"] = "A Wealth of Whelp Snacks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73119 }, ["description"] = "Agapanthus says there are more snack orders ready to be retrieved, but we both have our hands full. Would you run out and collect snacks while we tend the whelps?", ["objectivesText"] = "Gather snack orders from vendors in Valdrakken. Progress: Luckily we are not meant to eat the snacks ourselves, just understand what the whelps want so we can provide that. Cheese and crackers are clearly what they desire.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 202265, 202266, 203386, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73120] = { ["id"] = 73120, ["name"] = "Appetizing Aftermath", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73120 }, ["description"] = "Today's activities were interrupted by a spontaneous food fight. This has attracted several undesirable visitors to the daycare! Please help clean up.", ["objectivesText"] = "Help put the Little Scales Daycare back into order. Progress: It is interesting, being a janitor, educator, and minder, but I suppose that is what all caretakers become.", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73124] = { ["id"] = 73124, ["name"] = "Hoard Behavior", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73124 }, ["description"] = "The whelps like to spend time with Sir Pringly, but their treading over the space has worn down his habitat. Would you retrieve another shrubbery for him? And while you are out, he could use an adorable new toy. And incense. We cannot let his space fall into disrepair, of course.", ["objectivesText"] = "Gather materials for Sir Pringly's habitat. Progress: Beyond the particular shade of green, Sir Pringly only cares that a natural material adorn his space.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 202399, 202400, 202690, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73126] = { ["id"] = 73126, ["name"] = "Arts and Crafts and Baths", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73126 }, ["description"] = "Our arts and crafts activities today have gotten well out of hand. One of the whelps enchanted their brush and the rest followed suit. Now there is a coat of paint over everything. Please clean up the daycare while we get the paint off the whelps.", ["objectivesText"] = "Help clean up paint around the Little Scales Daycare. Progress: This paint was supposed to be washable, but it sticks to whelp scales like nothing else.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73128] = { ["id"] = 73128, ["name"] = "Off the Page", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73128 }, ["description"] = "$p, the whelps are begging us to tell them a story from their favorite anthology, but we are absolutely exhausted. The book the whelps gravitate towards is enchanted and makes every retelling a workout. Would you mind taking over for a spell and tackle story time for us?", ["objectivesText"] = "Battle the villains of various stories for the whelps at the Little Scales Daycare. Progress: I have heard these stories many times now. Battling them every day is tiring, to say the least.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73130] = { ["id"] = 73130, ["name"] = "Fowl Runic Scribblings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73130 }, ["description"] = "Our magic rune lesson yesterday has apparently bled into today. The whelps are keen on practicing their runes anywhere they can, prudent or not. This fascination has led to an interesting playtime period! Please, help us return the toys to their proper place and dispel any runes you come across.", ["objectivesText"] = "Help put the Little Scales Daycare back into order. Progress: We really ought to teach them runes for something helpful, like stone polishing... That would have gone a long way here.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73131] = { ["id"] = 73131, ["name"] = "Dignified Disguises", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73131 }, ["description"] = "$p! I have crafted masterful disguises for me and my friends, but there is only one way to know if they are perfect. Let's play hide and seek! Find us in Valdrakken and I will know my disguises need work!", ["objectivesText"] = "Find Belastrasza and her friends in Valdrakken.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199990, ["x"] = 0.105, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199990, ["x"] = 0.105, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.105, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73132] = { ["id"] = 73132, ["name"] = "Scanning the Stacks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73132 }, ["description"] = "Hi, $p! Do you want to play a game? I have been reading about the greatest hide and seek game in all of Azeroth! I think I can improve on the strategies this book suggests. Let us play a round and test my hypothesis!", ["objectivesText"] = "Find Zaleth and his friends in Valdrakken.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199985, ["x"] = 0.098, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199985, ["x"] = 0.098, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.098, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73133] = { ["id"] = 73133, ["name"] = "Cozy Camouflage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73133 }, ["description"] = "< Posidriss yawns.> I just can't sleep. Let's play a game instead! Maybe there's a comfy hiding spot out there somewhere. I bet you can't find me in the city!", ["objectivesText"] = "Find Posidriss and their friends in Valdrakken.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199987, ["x"] = 0.16, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199987, ["x"] = 0.16, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.16, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73134] = { ["id"] = 73134, ["name"] = "Eternal Escapades", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73134 }, ["description"] = "Ah--ACHOO! Sorry. Do you want to play hide and seek? I found new places to hide and I want to play! I hope my allergies don't stir up any trouble!", ["objectivesText"] = "Find every Zhusa in Valdrakken. Progress: I don't remember you coming back so soon. You were fast this time!", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199986, ["x"] = 0.139333, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199986, ["x"] = 0.139333, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.139333, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73135] = { ["id"] = 73135, ["name"] = "Obsidian Obfuscation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73135 }, ["description"] = "Hi, $p. <Ruszi looks around nervously.> Do you want to play hide and seek with me? I think it would be very good training. I need to watch out for danger, so it is good to know where to hide. Will you help me practice?", ["objectivesText"] = "Find Ruszi and her friends in Valdrakken. Progress: If I am hiding, then maybe they will not find me!", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 198612, ["x"] = 0.115, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 198612, ["x"] = 0.115, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.115, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73169] = { ["id"] = 73169, ["name"] = "The Lunar Festival", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Lunar Festival", ["expansion"] = 9, ["zoneID"] = 14771, ["mapID"] = 2112, ["storyline"] = { 73169 }, ["series"] = { 8867, 8870, 8871, 8872, 8873, 8874, 8875, 8883, 73170 }, ["description"] = "It's that time of the year, <name>! The Cenarion Circle invites all denizens of Azeroth to partake in a celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in Stormwind at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.", ["objectivesText"] = "Talk to the Lunar Festival Harbinger in Stormwind City.", ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199261, ["x"] = 0.390667, ["y"] = 0.61 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 }, { ["mapID"] = 2339, ["npcID"] = 220870, ["x"] = 0.41, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 15895, ["x"] = 0.3335, ["y"] = 0.5165 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.390667, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 37, 2112, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard" },
[73170] = { ["id"] = 73170, ["name"] = "The Lunar Festival", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Lunar Festival", ["expansion"] = 9, ["zoneID"] = 14771, ["mapID"] = 2112, ["storyline"] = { 73170 }, ["series"] = { 8867, 8870, 8871, 8872, 8873, 8874, 8875, 8883, 73169 }, ["description"] = "It's that time of the year, <name>! The Cenarion Circle invites all denizens of Azeroth to partake in a celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in Orgrimmar at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.", ["objectivesText"] = "Talk to the Lunar Festival Harbinger in the Valley of Wisdom in Orgrimmar.", ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199261, ["x"] = 0.390667, ["y"] = 0.61 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 }, { ["mapID"] = 2339, ["npcID"] = 220870, ["x"] = 0.41, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 15895, ["x"] = 0.3335, ["y"] = 0.5165 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.390667, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 37, 2112, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard" },
