[74291] = { ["id"] = 74291, ["name"] = "Blue is My Favorite Color", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 72650, 72651, 72652, 72653, 72654, 72655, 74291 }, ["description"] = "Oh, Kiry's here! I wonder if she has made her decision. Please ask her for thoughts, $p.", ["objectivesText"] = "Speak to Kirygosa and then return to the Azure Archives.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204076, 258985, 258986, 258987 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 201019, ["x"] = 0.480667, ["y"] = 0.428667 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.480667, ["y"] = 0.428667 }, ["mapCandidates"] = { ["npc"] = { 371, 2024 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1402, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1402, ["name"] = "Chapter 3B - Jade Forest", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 50, ["flags"] = 0 } } },
