[74393] = { ["id"] = 74393, ["name"] = "Report: Battlefield Ruins", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72987, 74393, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75367 }, ["series"] = { 72987, 75367 }, ["description"] = "Our situation is worse than we thought. Their dominance of the air keeps us at a disadvantage. They plan on freeing their powerful Elder from Aberrus. Allowing them to accomplish this could result in us permanently forfeiting control of this area. Seek out Field Commander Ignax in the Battlefield Ruins and see what can be done to turn the tide of this battle. We will join you shortly.", ["objectivesText"] = "Find Field Commander Ignax in the Battlefield Ruins.", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200046, ["x"] = 0.5, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200051, ["x"] = 0.466, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1395, ["name"] = "Inherited Sin", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 43, ["flags"] = 0 } } },
[74436] = { ["id"] = 74436, ["name"] = "Storm Warning", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 74376, 74436, 74437 }, ["description"] = "Ah, <class>! I knew I would find you at the right place at the right time. The elements do not just threaten the Dragon Isles in our current time, but also from beyond. Go to the Temporal Conflux and travel through the rift into the future the primalists have overrun. There, speak to Soridormi . She will have more details for you when you arrive.", ["objectivesText"] = "Speak to Soridormi in the Primalist Future. The portal to the Primalist Future can be found at the Temporal Conflux in Thaldraszus. Progress: It is good to see you again.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 192800, 193855, 201960, 201961, 201962, 202015, 202020, 202039, 202371, 203469, 203476, 203478, 203669, 203670, 203681 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 201492, ["x"] = 0.634, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2085, ["questLines"] = { { ["id"] = 1418, ["name"] = "The Storm's Fury", ["orderIndex"] = 0, ["flags"] = 0 } } },
[74437] = { ["id"] = 74437, ["name"] = "Resisting the Storm", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13992, ["mapID"] = 2085, ["storyline"] = { 74376, 74436, 74437 }, ["description"] = "The Primalists are growing in strength in this future timeline, despite our best efforts. If they overrun this valley and threaten the Temporal Conflux, they may become a problem for the rest of the timeways. We are already protecting the timeways from enough threats. Push back on them, <name>. We need to keep this peril in check. Speak to Tarnormu to gather any supplies you might need.", ["objectivesText"] = "Stock up on any necessary supplies and complete \"The Storm's Fury\" event in the Primalist Future. Progress: We cannot let the Primalists become a threat to other periods in our history.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 192800, 193855, 201960, 201961, 201962, 202015, 202020, 202039, 202371, 203469, 203476, 203478, 203669, 203670, 203681 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13992 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2512, ["db2PoiUiMapID"] = 2085, ["questLines"] = { { ["id"] = 1418, ["name"] = "The Storm's Fury", ["orderIndex"] = 1, ["flags"] = 0 } } },
