[74948] = { ["id"] = 74948, ["name"] = "Snailspiration: Amethyst Softshell", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74948 }, ["description"] = "I smell a snail on you, but it's strange. You holding out on me? Not many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", ["objectivesText"] = "Summon a max-level Amethyst Softshell battle pet and show it to Briggul . Progress: Show me that snail! Let's inspire Slick to be his best slimy self.", ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
