[75023] = { ["id"] = 75023, ["name"] = "Memories of Sindragosa and Malygos", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "I admit, I forgot about this phenomenon. Blue dragons who meet violent ends occasionally have some lingering arcane energy. That energy may manifest in various ways once their essences are laid to rest. Luckily, it is a simple enough process to dispel them. Simply wave anything through the energy and it will dissipate. I shall investigate the essences of Sindragosa and Malygos within this gravestone while you handle that.", ["objectivesText"] = "Dispel the lingering memories of Sindragosa and Malygos. Progress: How strange that these memories still linger...", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 200447, ["x"] = 0.67, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 200447, ["x"] = 0.67, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1398, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 10, ["flags"] = 0 } } },
[75028] = { ["id"] = 75028, ["name"] = "All the Broken Pieces", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["mapID"] = 2174, ["storyline"] = { 74521, 74522, 74523, 74525, 75018, 75028, 75029, 75417 }, ["description"] = "Emberthal is in mourning. In truth, she has been grieving for Sarkareth for some time now. The way forward is for her to determine. We can only be there to support her along the way. There are shards of Sarkareth's signet scattered all over this room. Would you gather them? I believe she would appreciate the gesture.", ["objectivesText"] = "Collect the shards of Sarkareth's signet. Progress: <Emberthal is in no mood to speak just yet.>", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2600, ["db2PoiUiMapID"] = 2174, ["questLines"] = { { ["id"] = 1397, ["name"] = "A Flame, Extinguished", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 67, ["flags"] = 0 } } },
[75029] = { ["id"] = 75029, ["name"] = "A Legacy, Reforged", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 74521, 74522, 74523, 74525, 75018, 75028, 75029, 75417 }, ["description"] = "Grief is a painful burden to bear. It warms my heart to see Emberthal emerge from her sorrow and focus on her people. The pain of her loss will ebb, in due time. We need to inform Alexstrasza and the others of what has transpired here... and of the future of the black dragonflight. With all that you have done to ensure that we have a chance at a future, I would like you to be there.", ["objectivesText"] = "Meet Ebyssian at the Seat of the Aspects in Valdrakken. Progress: We shall see you there, <name>.", ["rewardXP"] = 1770, ["rewardItems"] = { 206006 }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 203011, ["x"] = 0.584, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1397, ["name"] = "A Flame, Extinguished", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 68, ["flags"] = 0 } } },
