[75168] = { ["id"] = 75168, ["name"] = "Air Control", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 75168 }, ["description"] = "We will never make progress while those shadowflame drakes have us pinned down from the air. Get up there and knock them from the skies.", ["objectivesText"] = "Slay or knock Primal Nightflames from the air with Whirling Surge. Progress: They are not the only ones who can fly.", ["rewardItems"] = { 198048, 198059, 200454, 204075, 204673, 204732, 204733, 204735, 204736, 204745, 204746, 204747, 204748, 204749, 204750, 204751, 204752, 204754, 204755, 204756, 204757, 204758, 204759, 204760, 204761, 204762, 204763, 204764, 204765, 204767, 204769, 204770, 204771, 204772, 204773, 204775, 204777, 204778, 204779, 204781, 204783, 204784, 204785, 204786, 204788, 204896, 204898 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 201090, ["x"] = 0.75, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201090, ["x"] = 0.75, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.75, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[75181] = { ["id"] = 75181, ["name"] = "Volunteer Fire Fighters", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 75181 }, ["description"] = "We must contain the fires these rituals are causing. We are too far from the river to take advantage of the waters there but luckily we have two... volunteers... from beyond the plains that claim they can help. They need another pair of hands. Please go find the goblin and gnome. I appreciate their help but they need a third party to direct them.", ["objectivesText"] = "Use the Water Elemental to diffuse fires in the Suffusion Camp. Progress: Quickly, before they spread.", ["rewardItems"] = { 198048, 200454, 204075, 204673, 204735, 204745, 204746, 204748, 204749, 204750, 204751, 204752, 204754, 204756, 204762, 204763, 204764, 204765, 204766, 204771, 204772, 204773, 204774, 204777, 204778, 204779, 204780, 204782, 204783, 204784, 204785, 204786, 204787, 204789, 204897 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 201861, ["x"] = 0.755, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201861, ["x"] = 0.755, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.755, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[75182] = { ["id"] = 75182, ["name"] = "Grand Theft Mammoth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 75182 }, ["description"] = "The djaradin have loaded a mammoth with the spoils of their labor here for delivery to Fyrakk. Redirect that shipment. We can make use of whatever supplies they've gathered.", ["objectivesText"] = "Mount an Overladen Mammoth and return it to your lines. Progress: It should be hard to miss. They are quite large, after all.", ["rewardItems"] = { 198048, 200454, 204075, 204673, 204735, 204742, 204758, 204759, 204761, 204763, 204764, 204766, 204769, 204772, 204774, 204778, 204780, 204785 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 201860, ["x"] = 0.756, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201860, ["x"] = 0.756, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.756, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
