[75223] = { ["id"] = 75223, ["name"] = "Warcraft Rumble Minis: New Look!", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["storyline"] = { 75223 }, ["description"] = "<You find a message etched into the foil.> This Rumble Foil can be used at a Warcraft Rumble machine . Go and get a new look for one of your minis!", ["objectivesText"] = "Go to the Warcraft Rumble machine in Valdrakken .", ["rewardGold"] = 31500, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[75230] = { ["id"] = 75230, ["name"] = "Reconcilable Dissidents", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "My hope, <name>, is that our work to understand the rebels will allow us to find a path to peace. My concern is if we are not able to come to an understanding with Belaphon, other rebels may see her as a martyr for the cause. Whatever happens, you have my gratitude for your assistance throughout this rebellion.", ["objectivesText"] = "Listen to Alexstrasza's conversation with Instigator Belaphon. Progress: I hope Belaphon can see the way forward for Dragonkin.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 200839, ["x"] = 0.765, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 200839, ["x"] = 0.765, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 12, ["flags"] = 0 } } },
[75232] = { ["id"] = 75232, ["name"] = "Fallen Effects", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75232 }, ["description"] = "<You wrap Sheridon's effects into a bundle, and place them in your pack to return to the camp members.>", ["objectivesText"] = "Return Sheridon Hastle's Effects to Earthmender Narvra in the Dragonscale Expedition camp in Zaralek Cavern . Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 204642 }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4655, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["startItems"] = { 204642 } },
