[75351] = { ["id"] = 75351, ["name"] = "Keep a Leather Eye Open", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75351 }, ["description"] = "The kith of Loamm request the skills of a leatherworker! We've heard of the wonders you uplanders make with hides and scales! We have leatherworkers of our own down below! Miss Garram has heard there's a set of magical drums that make you faster! Is such a thing possible? Make a delivery to Loamm as soon as you can, won't you?", ["objectivesText"] = "Deliver Feral Hide Drums to Garamm in Loamm. Progress: Did Kayann send you? Do you have what I asked for?", ["rewardItems"] = { 193470, 204985, 205188 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203644, ["x"] = 0.572, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 44 },
[75353] = { ["id"] = 75353, ["name"] = "Dinn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily", "elite" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["storyline"] = { 75353 }, ["rewardGold"] = 137400, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14022 } }, ["questType"] = "world", ["db2QuestInfoID"] = 111, ["db2QuestInfoName"] = "Elite World Quest" },
[75354] = { ["id"] = 75354, ["name"] = "Mycelium Mastery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75354 }, ["description"] = "Hey there, stranger! I had an idea to run by you. The mushrooms that grow down in Zaralek Cavern have thick and powerful mycelium capable of gripping into even the hardest crystals. Imagine the possibilities with such a material! I had a friend down in Loamm who was trying to work out how to make it into a leather! Interested? Bring my friend Garram some mushrooms!", ["objectivesText"] = "Collect 10 Nightlight Conkerbell Samples and deliver them to Garram in Loamm. Progress: We call those crystal clinging mushrooms Nightlight Conkerbells. Not only do they give off light, they even have a strong enough scent to help guide our noses!", ["rewardItems"] = { 198613, 204792 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203644, ["x"] = 0.572, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
