[75367] = { ["id"] = 75367, ["name"] = "The Obsidian Rest", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72987, 74393, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75367 }, ["series"] = { 72987, 74393 }, ["description"] = "It is a miracle this outpost survived so long after Neltharion's... disappearance. For weeks now local scouts have reported increased djaradin activity in the area. They are amassing an army, and they are also becoming increasingly aggressive in their efforts to expand their territory. We must take every possible precaution and try to understand our enemy's motivations.", ["objectivesText"] = "Gather information and resources at the Obsidian Rest. Progress: These are trying times for all of us.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204819 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200046, ["x"] = 0.5, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200046, ["x"] = 0.5, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1395, ["name"] = "Inherited Sin", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 42, ["flags"] = 0 } } },
[75368] = { ["id"] = 75368, ["name"] = "Stones and Scales", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2112, ["storyline"] = { 75368 }, ["description"] = "I'm sure you've run into some of the mean beasties we have down in Zaralek while you were on your adventures! Have you seen any rock vipers yet? They're covered in both scales and stones! And have massive fangs! Mister Garram has offered a reward for anyone brave enough to bring him some of their hides! I'm sure he will make it worth your while!", ["objectivesText"] = "Collect 10 Scaly Stone Hides from rock vipers in Zaralek Cavern . Progress: Have you collected those hides yet? Those snakes are a little scary, but I think a <class> like you can handle them!", ["rewardXP"] = 1415, ["rewardItems"] = { 198613, 204800 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203644, ["x"] = 0.572, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 14022 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
[75369] = { ["id"] = 75369, ["name"] = "Use Your Coin!", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 75369 }, ["description"] = "Use that coin on the Warcraft Rumble machine over there.", ["objectivesText"] = "Use that coin on the Warcraft Rumble machine over there.", ["rewardItems"] = { 202162, 202163, 204731 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[75370] = { ["id"] = 75370, ["name"] = "Smellincense", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "bonusobjective" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["storyline"] = { 75370 }, ["objectivesText"] = "Delvert's Incense Pot filled", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Delvert's Incense Pot filled", ["amount"] = 1, ["type"] = 0, ["objectID"] = 203701, ["orderIndex"] = 0 } }, ["db2QuestInfoID"] = 283, ["db2QuestInfoName"] = "Bonus Objective with Completion Toast", ["db2VignetteID"] = 5702, ["db2VignetteName"] = "Smellincense" },
[75371] = { ["id"] = 75371, ["name"] = "Fascinating Fungi", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75371 }, ["description"] = "Ah, Uplander! Can I ask for your assistance? The cavern below is full of mushrooms that are useful for all kinds of things! Miss Mistie has asked for help gathering them for her alchemical experiments. She says the Gelcap mushrooms produce sticky spores that she can make into a balm, good for easing achy joints and bunions! I sure could use some after standing around on these hard stones all day! If you can find her some, I'm sure she will make it worth your while!", ["objectivesText"] = "Collect 10 Gelcap Spores . Progress: Have you collected the spores? I'm eager to get my hands on them!", ["rewardXP"] = 1415, ["rewardItems"] = { 198608, 204801 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203607, ["x"] = 0.56, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
[75372] = { ["id"] = 75372, ["name"] = "Drive Them Before Us", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75372 }, ["description"] = "Drive these whelks from our lands, <name>! For Imbu! For the Azure Span!", ["objectivesText"] = "Slay djaradin and Primalists assaulting the Azure Span. Progress: Glorious.", ["rewardItems"] = { 198048, 198059, 200453, 204075, 204673, 204732, 204733, 204735, 204743, 204744, 204747, 204748, 204749, 204750, 204751, 204752, 204754, 204756, 204757, 204763, 204764, 204765, 204767, 204771, 204772, 204775, 204777, 204778, 204780, 204781, 204784, 204785, 204786, 204787, 204788, 204789, 204896, 204897, 204898 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 203601, ["x"] = 0.578, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 203601, ["x"] = 0.578, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[75373] = { ["id"] = 75373, ["name"] = "Charge of the Ottuk Brigade", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75373 }, ["description"] = "Bah! They hide behind their barricades, hoping that will protect them from our vengeance. Clear the way and we will ride them down like the cowards they are!", ["objectivesText"] = "Destroy djaradin barricades . Progress: Soon we shall ride again, <name>.", ["rewardItems"] = { 198048, 198059, 200453, 204075, 204673, 204732, 204735, 204736, 204744, 204745, 204760, 204762, 204765, 204766, 204768, 204770, 204773, 204774, 204776, 204780, 204782, 204783, 204787, 204789, 204896, 204898, 204901 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 203601, ["x"] = 0.578, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 203601, ["x"] = 0.578, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[75374] = { ["id"] = 75374, ["name"] = "To Defend the Span", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75374 }, ["description"] = "The djaradin struck without warning, <name>. Our people are capable fighters, but no one escapes a battle like this unscathed. Please, help with the wounded. Many are trapped behind the enemy lines and can't make their way back in their current state.", ["objectivesText"] = "Heal 6 Gruff Fishers using the provided bandages or your own abilities. Progress: There are always more wounded that need healing.", ["rewardItems"] = { 198048, 198059, 200453, 203731, 204075, 204735, 204737, 204738, 204740, 204741, 204742, 204743, 204744, 204745, 204750, 204752, 204753, 204758, 204759, 204760, 204761, 204762, 204764, 204767, 204768, 204769, 204770, 204772, 204773, 204775, 204776, 204778, 204779, 204780, 204781, 204782, 204783, 204785, 204786, 204788, 204789, 204901 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 203603, ["x"] = 0.586, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 203603, ["x"] = 0.586, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[75375] = { ["id"] = 75375, ["name"] = "Burning Ice", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75375 }, ["description"] = "Whatever magic the djaradin are employing is lighting the ice on fire out there, <name>. We can't let this spread to the wider Span. It has to be stopped before it consumes everything. Gather as much water as you can while on that drake of yours and drown the fires. Hopefully that will be enough to extinguish them.", ["objectivesText"] = "Extinguish fires across the djaradin camp. Progress: The sight of burning ice unnerves me.", ["rewardItems"] = { 198059, 200453, 204075, 204673, 204732, 204733, 204737, 204738, 204739, 204740, 204742, 204743, 204744, 204750, 204752, 204753, 204758, 204759, 204761, 204764, 204766, 204769, 204772, 204774, 204776, 204780, 204781, 204785, 204787, 204896, 204897, 204898 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 203603, ["x"] = 0.586, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 203603, ["x"] = 0.586, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[75376] = { ["id"] = 75376, ["name"] = "Suffuse, Reuse, Recycle", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75376 }, ["description"] = "If Fyrakk is willing to openly attack the surface in pursuit of these materials, they must be vital to his plans. Grab whatever you can. There must be a way to turn these to our advantage.", ["objectivesText"] = "Recover infusion supplies from Fyrakk's forces. Progress: We'll strengthen ourselves even as we deny our enemies.", ["rewardItems"] = { 198048, 200453, 204075, 204699, 204743, 204744, 204747, 204748, 204750, 204752, 204754, 204758, 204759, 204761, 204766, 204769, 204774, 204780, 204787, 204896, 204898 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 203522, ["x"] = 0.584, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 203522, ["x"] = 0.584, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[75377] = { ["id"] = 75377, ["name"] = "Maintaining the Barricade", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75377 }, ["description"] = "It's all I can do to keep this shield up under the barrage these shadowflame drakes are putting out. Thin their ranks before we're pinned down for good.", ["objectivesText"] = "Slay or knock Primal Nightflames from the air with Whirling Surge. Progress: Incoming!", ["rewardItems"] = { 198048, 200453, 204075, 204746, 204748, 204749, 204751, 204754, 204756, 204757, 204760, 204762, 204763, 204764, 204770, 204771, 204772, 204777, 204778, 204781, 204783, 204784, 204785 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 203522, ["x"] = 0.584, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 203522, ["x"] = 0.584, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
