[75388] = { ["id"] = 75388, ["name"] = "The Azure Vaults", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75388 }, ["description"] = "There's a problem in the Azure Vault, <name>. Beneath the Azure Archives rests the Azure Vault. Sindragosa stored many important and dangerous magical curiosities in it. A large group of Sundered Flame have broken into the vault to unlock its secrets. You need to go in there and stop the Sundered Flame!", ["objectivesText"] = "Stop the Sundered Flame within the Azure Vaults. Progress: Take care within the vaults.", ["rewardGold"] = 1123600, ["rewardXP"] = 19030, ["rewardItems"] = { 193629, 193647 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "dungeon" },
