[75407] = { ["id"] = 75407, ["name"] = "Silk Scavenging", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75407 }, ["description"] = "Hello friend! You're a tailor, right? So you must know about silk! Mister Rossmar down in Loamm knows how to make special silk from the cocoons of the Underlight Moths, but could use some help gathering them up! You should be able to find them in the mushroomy area near Glimmerogg. I'll sure he will make it worth your while!", ["objectivesText"] = "Collect 10 Underlight Cocoons Fibers in Zaralek Cavern . Progress: Hey, uplander! Do you have those cocoons yet?", ["rewardItems"] = { 198609, 204817 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203608, ["x"] = 0.56, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
[75408] = { ["id"] = 75408, ["name"] = "Calling All Dracthyr!", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75408 }, ["description"] = "<This flyer is illustrated with inviting sketches of dracthyr eating, sparring, and having fun.> Calling all dracthyr! Do you feel adrift after the events of the underground? Do you want to bond with your creche mates? Do you just need someone to talk to? Come join us at Weyrnrest for food, fun, and camaraderie! ALL dracthyr welcome!", ["objectivesText"] = "Go to the party at Weyrnrest in Valdrakken .", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 201766, ["x"] = 0.24, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.24, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
