[75417] = { ["id"] = 75417, ["name"] = "Symbol of Hope", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 74521, 74522, 74523, 74525, 75018, 75028, 75029, 75417 }, ["description"] = "Champion--Ebyssian, Sabellian, and Wrathion have come to an agreement of who should lead, and are presenting a unified front. All three were quite eager to speak of your contributions and aid in Zaralek Cavern as well. It seems that they are also in agreement that they could not have succeeded without you. High praise indeed--and well deserved. Please, stay for a little longer. The other Aspects and I have matters to discuss, and I believe you should be here as well.", ["objectivesText"] = "Speak with Alexstrasza. Progress: Please, stay for a little longer. The other Aspects and I have matters to discuss, and I believe you should be here as well.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.583778, ["y"] = 0.357111 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1397, ["name"] = "A Flame, Extinguished", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 69, ["flags"] = 0 } } },
[75419] = { ["id"] = 75419, ["name"] = "Sundered Flames", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72958, 72959, 72961, 72962, 72963, 72964, 72965, 74334, 74375, 75419 }, ["description"] = "Did Neltharion keep this place as his hoard? No wonder that Sarkareth was looking for it. Neltharion's \"treasures\" litter every corner of it. There's no telling what Sarkareth has gotten his claws on here. Stay close!", ["objectivesText"] = "Find Sarkareth.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200075, ["x"] = 0.627, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204040, ["x"] = 0.63, ["y"] = 0.74 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.627, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 1393, ["name"] = "Sundered Legacy", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 21, ["flags"] = 0 } } },
