[75462] = { ["id"] = 75462, ["name"] = "Mouse Rescuers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75462 }, ["description"] = "I feel bad for everything I did working for Malrogg . He was just so big and scary, I never felt like I had a choice... < Agrul slowly shakes his head.> No more excuses. We need to get that sniffin' mouse back home to Yarren . I was never strong enough to take on Malrogg alone. But you... You can save Persii .", ["objectivesText"] = "Kill Malrogg . Progress: Did you find that drogbar?", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 205253 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 202600, ["x"] = 0.4875, ["y"] = 0.7735 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202597, ["x"] = 0.51, ["y"] = 0.74 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4875, ["y"] = 0.7735 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
