[75493] = { ["id"] = 75493, ["name"] = "Surveying the Riverbed", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Hope you brought your boots, 'cause this is gonna be a wet one! This river carries artifacts down from the mountains, and they wash up here in the silt. The centaur have found loads of stuff here over the years. We're here to take a deeper look and see if there's anything interesting below the surface.", ["objectivesText"] = "Speak with Roska to start the dig, then excavate artifacts from the riverbed.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 210435 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 204094, ["x"] = 0.674, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 204643, ["x"] = 0.664, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5468, ["name"] = "Azerothian Archives - Excavation Sites", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 8, ["flags"] = 0 } } },
