[75517] = { ["id"] = 75517, ["name"] = "Sneak and Sniff", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "bonusobjective" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["storyline"] = { 75517 }, ["objectivesText"] = "Chest opened", ["rewardItems"] = { 205412 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Chest opened", ["amount"] = 1, ["type"] = 2, ["objectID"] = 401816, ["orderIndex"] = 1 } }, ["db2QuestInfoID"] = 283, ["db2QuestInfoName"] = "Bonus Objective with Completion Toast" },
[75518] = { ["id"] = 75518, ["name"] = "The Body on the Banks", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "<The state of the corpse of this centaur woman is surprising. Her clothing is in a style unfamiliar to you, and her skin is emblazoned with intricate tattoos. Her body is intact, so it seems as though she could not have been dead long... or could she? Conditions here may have led to better preservation. Roska will want to have a look at this!>", ["objectivesText"] = "Speak to Roska to begin carefully excavating the centaur corpse. Progress: Nothing like silt, eh <name>? Never know what you'll find!", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 210435 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 204245, ["x"] = 0.664, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 204643, ["x"] = 0.664, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5468, ["name"] = "Azerothian Archives - Excavation Sites", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 9, ["flags"] = 0 } } },
[75519] = { ["id"] = 75519, ["name"] = "The Long Hunt", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13983, ["mapID"] = 85, ["storyline"] = { 75519 }, ["description"] = "< Dori'thur hovers silently, peering at you with keen, expectant eyes. With a taloned foot, the noble owl offers you an imbued crystal. Within that crystal, you sense a message.>", ["objectivesText"] = "Witness the message.", ["rewardGold"] = 157900, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 204250, ["x"] = 0.485333, ["y"] = 0.485333 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 204250, ["x"] = 0.485333, ["y"] = 0.485333 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.485333, ["y"] = 0.485333 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 13983 } }, ["questType"] = "standard" },
[75528] = { ["id"] = 75528, ["name"] = "A Tester's Guide to Entering Zaralek", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 75528 }, ["description"] = "Hail, and well met! While the story of Zaralek has yet to unfold, there is plenty to see within the cavern! Make way to Loamm, home of the Niffen.", ["objectivesText"] = "Enter Zaralek Cavern through Iridikron's Gambit.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[75538] = { ["id"] = 75538, ["name"] = "Beginning Impositions", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5861, ["mapID"] = 84, ["storyline"] = { 75538, 75539, 75540, 75541, 75542, 75543, 75544, 75639, 76155, 76163, 76410 }, ["description"] = "Darkest greetings, <race>. Ahem, yes. Yes! Darkest greetings indeed. <The lanky man seems to suddenly remember where he is.> On behalf of my patron, I bid you travel to the Darkmoon Faire. The Faire! Who doesn't love it? Yes. Yes! Ahem. She requires your presence, she does! Our Lady of the Midnight Moon. The Damsel of Darkness! The Mother of Crows... ... Madam Shadow .", ["objectivesText"] = "Travel to the Darkmoon Faire. Progress: Everyone knows the way to the Faire...", ["rewardGold"] = 126360, ["rewardXP"] = 2060, ["rewardItems"] = { 206681, 207101, 207294, 208226 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 204198, ["x"] = 0.490667, ["y"] = 0.769333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.490667, ["y"] = 0.769333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 5861 } }, ["questType"] = "standard", ["db2PoiMapID"] = 974, ["db2PoiUiMapID"] = 407, ["questLines"] = { { ["id"] = 5383, ["name"] = "Some Wicked Things", ["orderIndex"] = 0, ["flags"] = 0 } } },
[75539] = { ["id"] = 75539, ["name"] = "Some Wicked Things This Way Come", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5861, ["mapID"] = 407, ["storyline"] = { 75538, 75539, 75540, 75541, 75542, 75543, 75544, 75639, 76155, 76163, 76410, 76427, 76430 }, ["description"] = "Phineas did well in bringing you to me, $p. There is much work to be done. We'd best get to it! As a master of the dark arts, I need you to help me whip these newcomers into shape. Talk to them. They come from many walks of life--all of them unfamiliar with the dark arts. Learn their wishes. Their hopes. Their dreams. This path we walk can bestow gifts unending and power unimaginable. One just needs to know what one truly desires...", ["objectivesText"] = "Talk to the newly arrived warlocks around the Darkmoon Faire. Progress: What have you learned, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard", ["db2PoiMapID"] = 974, ["db2PoiUiMapID"] = 407, ["questLines"] = { { ["id"] = 5383, ["name"] = "Some Wicked Things", ["orderIndex"] = 1, ["flags"] = 0 } } },
[75540] = { ["id"] = 75540, ["name"] = "Hermetic Insurance", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5861, ["mapID"] = 407, ["storyline"] = { 75538, 75539, 75540, 75541, 75542, 75543, 75544, 75639, 76155, 76163, 76410, 76427, 76430 }, ["description"] = "Ah, the latest group have gathered beneath my wings like chicks to a mother crow. You've done well so far, $p. They trust you. I trust you. The next step in shepherding these simple souls along in their diabolical journeys is to safeguard them against the void. Against oblivion. Against death. Take my soulstone and use it to gird the willing... and the damned.", ["objectivesText"] = "Use Madam Shadow 's Soulstone on willing initiates in the Darkmoon Faire. Progress: Is it done?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard", ["db2PoiMapID"] = 974, ["db2PoiUiMapID"] = 407, ["questLines"] = { { ["id"] = 5383, ["name"] = "Some Wicked Things", ["orderIndex"] = 2, ["flags"] = 0 } } },
[75541] = { ["id"] = 75541, ["name"] = "Those Who Hesitate", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5861, ["mapID"] = 407, ["storyline"] = { 75538, 75539, 75540, 75541, 75542, 75543, 75544, 75639, 76155, 76163, 76410, 76427, 76430 }, ["description"] = "Hm. There is one who has been counted amongst our number, but is not here. The draenei. < Madam Shadow inhales.> I can taste the Light about him. Go, see to it that he rejoins us. There is much work to be done.", ["objectivesText"] = "Talk to Initiate Oman in the Darkmoon Faire. Progress: This view reminds me of... many things.", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard", ["db2PoiMapID"] = 974, ["db2PoiUiMapID"] = 407, ["questLines"] = { { ["id"] = 5383, ["name"] = "Some Wicked Things", ["orderIndex"] = 3, ["flags"] = 0 } } },
[75542] = { ["id"] = 75542, ["name"] = "Curses & Cultists", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5861, ["mapID"] = 407, ["storyline"] = { 75538, 75539, 75540, 75541, 75542, 75543, 75544, 75639, 76155, 76163, 76410, 76427, 76430 }, ["description"] = "The wheat has been separated from the chaff. Now the fun can truly begin. I have an exciting... field trip... planned for our students. But they are not yet ready. Take my grimoire and have the pandaren, zandalari, and tauren try their hand at curses. I found some uninvited guests loitering on the edges of our fairground. They should make excellent, if unwilling, test subjects. Oman will have the honor of summoning the group far afield, and I will instruct him as such.", ["objectivesText"] = "Teach the initiates curses from Madam Shadow 's grimoire in the Darkmoon Faire.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard", ["db2PoiMapID"] = 974, ["db2PoiUiMapID"] = 407, ["questLines"] = { { ["id"] = 5383, ["name"] = "Some Wicked Things", ["orderIndex"] = 4, ["flags"] = 0 } } },
[75543] = { ["id"] = 75543, ["name"] = "Last Rites By Accident", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5861, ["mapID"] = 36, ["storyline"] = { 75538, 75539, 75540, 75541, 75542, 75543, 75544, 75639, 76155, 76163, 76410, 76427, 76430 }, ["description"] = "<You can hear the faint sound of screaming coming from the other side of the portal.>", ["objectivesText"] = "Go through the Demonic Gateway and help the Initiates.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["ends"] = { { ["mapID"] = 36, ["npcID"] = 205575, ["x"] = 0.085, ["y"] = 0.36 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.085, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = { 36 }, ["zone"] = { 5861 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 36, ["questLines"] = { { ["id"] = 5383, ["name"] = "Some Wicked Things", ["orderIndex"] = 6, ["flags"] = 0 } } },
[75544] = { ["id"] = 75544, ["name"] = "When Revenge Burns Green", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 46, ["mapID"] = 36, ["storyline"] = { 75538, 75539, 75540, 75541, 75542, 75543, 75544, 75639, 76155, 76163, 76410, 76427, 76430 }, ["description"] = "Whatever game this Madam Shadow has been playing, it appears as though we're nearing the end of it. <Oman grunts in pain.> From what we've heard, it sounds like our next destination is somewhere in the Blasted Lands . I must rest, but please $p... go and see this through. Bring Madam Shadow to account. Avenge our fellow warlocks.", ["objectivesText"] = "Confront Madam Shadow in the Blasted Lands .", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 166242, 208227 }, ["starts"] = { { ["mapID"] = 36, ["npcID"] = 205575, ["x"] = 0.085, ["y"] = 0.36 } }, ["ends"] = { { ["mapID"] = 17, ["npcID"] = 205818, ["x"] = 0.331333, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.085, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = { 17, 36 }, ["zone"] = { 46 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 17, ["questLines"] = { { ["id"] = 5383, ["name"] = "Some Wicked Things", ["orderIndex"] = 7, ["flags"] = 0 } } },
[75569] = { ["id"] = 75569, ["name"] = "Blacksmith, Black Dragon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75569 }, ["description"] = "The black dragonkin in the north of Zaralek Cavern are said to be fine blacksmiths. They're quick to claim it has something do with a \"dominion over the earth\", but I'd like to see them try burrowing like a proper niffen! Still, you can't argue with the results. Grab a few examples and bring them to Kilnmaster Crubus in Loamm so he can study their techniques.", ["objectivesText"] = "Collect 8 Blackened Plate . Progress: I wonder if I could use one of their helmets as a tub?", ["rewardItems"] = { 198606, 205117 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203170, ["x"] = 0.57, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 33 },
[75573] = { ["id"] = 75573, ["name"] = "Proclamation Reclamation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75573 }, ["description"] = "You know who likes to hear themselves talk, loves bureaucracy, and enchants their own records? Dragons! Go poke around in the old black dragon fort north of Loamm. I'm sure they'll be all sort of magic-ish decrees, proclamations, and shopping lists just lying around! Bring whatever you uncover to Scridorsa the Chiseler back in Loamm. I'm sure she'd love something new and heavily enchanted to read!", ["objectivesText"] = "Collect 10 Infused Proclamations . Progress: Can't do anything simply, can they?", ["rewardItems"] = { 198607, 205124 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203171, ["x"] = 0.558, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
[75575] = { ["id"] = 75575, ["name"] = "Ballistae Bits", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75575 }, ["description"] = "Those djaradin might smell like brutes, but their engineering corps must be top notch to keep churning out ballistae strong enough to threaten a dragon! Northeast of Loamm there's an ongoing scrap between them and some black dragons. There ought to be lots of spare parts scattered around. Or slightly used, moderately on fire ones, anyway! Haul them all back to Loamm! A little scorching won't stop our top minds from reverse niffeneering them.", ["objectivesText"] = "Collect 10 Ballistae Bits . Progress: I wonder what they use for torsion?", ["rewardItems"] = { 198611, 205125 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203610, ["x"] = 0.558, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 35 },
[75576] = { ["id"] = 75576, ["name"] = "Grim Guzzler Invasion!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 75576 }, ["objectivesText"] = "Invasion repelled", ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Invasion repelled", ["amount"] = 1, ["type"] = 0, ["objectID"] = 204096, ["orderIndex"] = 0 } } },
[75598] = { ["id"] = 75598, ["name"] = "Snailed It", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75598 }, ["description"] = "Hmm. You ever mount a snail before? I've trained generations of racing snail champions, but lately I've come across my toughest case yet. Simply put, he's too crokin' big. Straight up barred from competition. It's a shame to keep such a prize specimen stuck in a bucket, though. If you can help me train Slick up to be the speedster I know he is, we'll call him yours!", ["objectivesText"] = "Introduce yourself to Slick.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 205155 }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75600] = { ["id"] = 75600, ["name"] = "Silk's Silk", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2112, ["storyline"] = { 75600 }, ["description"] = "We may not have access to all those fancy plant fibers you surface types use up here, but we do have a lot of options I bet you don't! The spiders near Loamm make the most interesting smelling silk I ever did sniff. I think it might have something to do with their diet? If you round some up, I'm sure Rossmar back in Loamm will be happy to teach you a thing or two about how to use it!", ["objectivesText"] = "Collect 8 Calcisilk Bundles . Progress: Just follow the bone-y smells!", ["rewardGold"] = 105000, ["rewardXP"] = 2765, ["rewardItems"] = { 80704, 80705, 80706, 80707, 80708, 80709, 80710, 80711, 80712, 84339, 84340, 84341, 84342, 84343, 124124, 124437, 137961, 137963, 137964, 138012, 138013, 138014, 140255, 198609, 205158, 211279, 237812, 242241 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203608, ["x"] = 0.56, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 14022 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 37 },
[75602] = { ["id"] = 75602, ["name"] = "Chips off the Old Crystal Block", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2112, ["storyline"] = { 75602 }, ["description"] = "The crystalline creatures back home are as mysterious as they are stompy. What allows them to move? Are they even really alive? What do they taste like? Bring Fanilly a few samples to start studying. Just not any big enough to step on anyone in Loamm, ok?", ["objectivesText"] = "Collect 10 Living Chips . Progress: Who knows what we could learn?", ["rewardItems"] = { 198612, 205167 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203612, ["x"] = 0.566, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 14022 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 43 },
[75604] = { ["id"] = 75604, ["name"] = "Antiquated Antics", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Well, there's two factors at play here, eh? We should do our due diligence and figure out who this was a statue of. But between you and me? I'm much more interested in learning about the jokesters that turned it into this work of art. I'm sure there's a historian of the black dragonflight somewhere near Aberrus. And why don't you poke around Loamm to see if there are any stories surrounding this kind of... artistic license.", ["objectivesText"] = "Find experts from both Loamm and the black dragonflight to weigh in on your find. Progress: <Roska looks pleased with your work.>", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 208055, ["x"] = 0.476, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 208055, ["x"] = 0.476, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5468, ["name"] = "Azerothian Archives - Excavation Sites", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 25, ["flags"] = 0 } } },
[75608] = { ["id"] = 75608, ["name"] = "Titan Trash or Titan Treasure?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75608 }, ["description"] = "The watchers left all sorts of amazing technology just laying around when they went to sleep. We could learn so much from their ancient castoffs. Even the least of contraptions are marvels to behold! If only there was someone brave, intelligent, and dare I say handsome enough to go retrieve a few examples for our finest niffeneers back in Loamm to examine... sound familiar?", ["objectivesText"] = "Collect 10 Hololithic Gears . Progress: I wonder if we'll ever truly understand their technology?", ["rewardItems"] = { 198611, 205177 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203610, ["x"] = 0.558, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 35 },
