[75662] = { ["id"] = 75662, ["name"] = "A Race to the Finish", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75662 }, ["description"] = "You look like someone that enjoys a good snail race! And what makes a snail race good you ask? Each snail must have a chance to win! And sometimes the snails might need a little bit of help. If you grab a bag of treats from the chef and toss it in their path that'll get them moving. How about we give Bashful a nudge to victory?", ["objectivesText"] = "Help Bashful win a race. Progress: Has your snail won the race?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 205119, 205121, 205123 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201099, ["x"] = 0.444, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201099, ["x"] = 0.444, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75665] = { ["id"] = 75665, ["name"] = "A Worthy Ally: Loamm Niffen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75665 }, ["description"] = "Djaradin, dracthyr, and dragons! Oh my! You can't help but smell the danger in these here caverns. We sure could use some armed assistance. You scratch my back, and I'll make sure the kith scratch yours! We got loads of good stuff... for the right clientele. How about it? Get out there and bury the competition?", ["objectivesText"] = "Aid the niffen and their allies throughout Zaralek Cavern . Progress: Are our enemies six feet under?", ["rewardItems"] = { 205249, 205288, 205342, 205367, 205983, 205985 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 204254, ["x"] = 0.565, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204254, ["x"] = 0.565, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
