[75694] = { ["id"] = 75694, ["name"] = "Aberrus, the Shadowed Crucible: Sarkareth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72872, 72873, 72874, 72908, 72909, 72910, 72911, 72912, 72913, 72914, 72915, 72916, 72917, 72918, 72919, 72920, 72922, 72923, 72924, 72925, 72926, 72927, 72928, 72929, 72930, 72931, 72958, 72959, 72961, 72962, 72963, 72964, 72965, 72966, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 72987, 74334, 74375, 74393, 74494, 74521, 74522, 74523, 74525, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75018, 75028, 75029, 75145, 75367, 75417, 75419, 75643, 75644, 75694, 91691, 91695 }, ["description"] = "I have no interest in following my brothers within Aberrus, but I continue to care for their safety. Neltharion fell so deeply into madness that his secret stronghold is no doubt filled with any number of unspeakable dangers. Go with them, <name>. Stand with them. They will need your support in what is to come.", ["objectivesText"] = "Enter Aberrus, the Shadowed Crucible, and defeat Sarkareth. Progress: Aberrus holds mysteries and dangers alike. They must be dealt with, before any of them fall into the wrong hands.", ["rewardGold"] = 1239200, ["rewardXP"] = 2830, ["rewardItems"] = { 204682 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 }, { ["mapID"] = 2133, ["npcID"] = 201727, ["x"] = 0.48, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 199965, ["x"] = 0.483, ["y"] = 0.28225 }, { ["mapID"] = 2133, ["npcID"] = 201727, ["x"] = 0.48, ["y"] = 0.118 }, { ["mapID"] = 2112, ["npcID"] = 204287, ["x"] = 0.6056, ["y"] = 0.4176 }, { ["mapID"] = 2112, ["npcID"] = 214851, ["x"] = 0.603333, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.483, ["y"] = 0.28225 }, ["mapCandidates"] =