[75706] = { ["id"] = 75706, ["name"] = "A Race to the Finish", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75706 }, ["description"] = "Everyone loves a good snail race! In the most exciting races, every snail has a chance to win. You can help a snail win by giving it treats. Watch how fast it makes them go! Grab a bag of treats and toss them in the path of the snails. See if you can get Tricky to win!", ["objectivesText"] = "Help Tricky win a race. Progress: Has your snail won the race?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 205119, 205121, 205123 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201099, ["x"] = 0.444, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201099, ["x"] = 0.444, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75707] = { ["id"] = 75707, ["name"] = "A Race to the Finish", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75707 }, ["description"] = "Everyone loves a good snail race! In the most exciting races, every snail has a chance to win. You can help a snail win by giving it treats. Watch how fast it makes them go! Grab a bag of treats and toss them in the path of the snails. See if you can get Brulee to win!", ["objectivesText"] = "Help Brulee win a race. Progress: Has your snail won the race?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 205119, 205121, 205123 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201099, ["x"] = 0.444, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201099, ["x"] = 0.444, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75709] = { ["id"] = 75709, ["name"] = "Find a Rumble Coin", ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 84, ["storyline"] = { 75709 }, ["series"] = { 75625 }, ["description"] = "To use this game machine, you need a Rumble Coin . There are a bunch of coins hidden all around the Dragon Isles. We'll chat about those later. I stashed one coin here at the docks. If you find it, it's all yours, pal. Insert that Rumble Coin into the Rumble machine and watch the fun begin!", ["objectivesText"] = "Find a Rumble Coin in Stormwind Harbor and insert it into the Warcraft Rumble machine . Progress: <The Warcraft Rumble machine stands before you. A small sign reads:> Insert Rumble Coin to play.", ["rewardItems"] = { 202162, 202163 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 201230, ["x"] = 0.423333, ["y"] = 0.468333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.423333, ["y"] = 0.468333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[75711] = { ["id"] = 75711, ["name"] = "Find a Rumble Coin", ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 84, ["storyline"] = { 75711 }, ["series"] = { 75626 }, ["description"] = "To use this game machine, you need a Rumble Coin . There are a bunch of coins hidden all around the Dragon Isles. We'll chat about those later. I stashed one coin over in the inn. If you find it, it's all yours, pal. Insert that Rumble Coin into the Rumble machine and watch the fun begin!", ["objectivesText"] = "Find a Rumble Coin in the Broken Tusk and insert it into the Warcraft Rumble machine . Progress: <The Warcraft Rumble machine stands before you. A small sign reads:> Insert Rumble Coin to play.", ["rewardItems"] = { 202162, 202163, 202395 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 201230, ["x"] = 0.423333, ["y"] = 0.468333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.423333, ["y"] = 0.468333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[75712] = { ["id"] = 75712, ["name"] = "Warcraft Rumble Minis: New Look!", ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["storyline"] = { 75712 }, ["description"] = "<You find a message etched into the foil.> This Rumble Foil can be used at a Warcraft Rumble machine . Go and get a new look for one of your minis!", ["objectivesText"] = "Go to the Warcraft Rumble machine in Stormwind Harbor.", ["rewardGold"] = 28090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[75713] = { ["id"] = 75713, ["name"] = "Warcraft Rumble Minis: New Look!", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["storyline"] = { 75713 }, ["description"] = "<You find a message etched into the foil.> This Rumble Foil can be used at a Warcraft Rumble machine . Go and get a new look for one of your minis!", ["objectivesText"] = "Go to the Warcraft Rumble machine in Orgrimmar 's Valley of Strength.", ["rewardGold"] = 28090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[75720] = { ["id"] = 75720, ["name"] = "Care to Barter?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75720 }, ["description"] = "Hey, Uplander! I hear you like helping. Maybe you could help me out? I need some packages sent to Valdrakken. If you don't peek and don't ask, I can make it worthwhile. Stop by when you're in Loamm. We can work out a deal! Your new friend, Ponzo .", ["objectivesText"] = "Talk to Ponzo in Loamm.", ["rewardGold"] = 16980, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205127, ["x"] = 0.564, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204693, ["x"] = 0.58, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75721] = { ["id"] = 75721, ["name"] = "Bartering 101", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75721 }, ["description"] = "So here's what I need you to do. A friend of mine, Kayann , went all the way up to Valdrakken . He's expecting a delivery from me. Can you get it to him? No questions, though. Don't look, don't smell, don't taste. This is for Kayann 's nose only! If that's all right with you, I'll send you on your way--with my thanks, of course!", ["objectivesText"] = "Deliver Ponzo 's box to Kayann in Valdrakken .", ["rewardItems"] = { 204985 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 204693, ["x"] = 0.58, ["y"] = 0.538 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75722] = { ["id"] = 75722, ["name"] = "Bag of Gold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75722 }, ["description"] = "Hello, $p! I heard you've been helping us out! Good deeds should be rewarded--and I've got something special for you! Why don't you meet me in Loamm? Keep up the good work, Mimuup", ["objectivesText"] = "Talk to Mimuup in Loamm.", ["rewardItems"] = { 204195 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205127, ["x"] = 0.564, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204254, ["x"] = 0.565, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75723] = { ["id"] = 75723, ["name"] = "Cavern Drakewatching", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75723 }, ["description"] = "Well hey there, Uplander! Word is, you've been helping us out a lot! We got a little something for you in return. See me in Loamm and I'll hand it over! Best, Harlowe Marl", ["objectivesText"] = "Talk to Harlowe Marl in Loamm.", ["rewardItems"] = { 203310, 203316, 203327 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205127, ["x"] = 0.564, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202468, ["x"] = 0.564, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75724] = { ["id"] = 75724, ["name"] = "Like the Niffen Do", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75724 }, ["description"] = "Hello there, $p! We want to thank you for all the help you've given us. It's only right! Meet me in Loamm and I'll teach you to dig like we niffen do! Sincerely, Mimuup", ["objectivesText"] = "Talk to Mimuup in Loamm.", ["rewardItems"] = { 205255 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205127, ["x"] = 0.564, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204254, ["x"] = 0.565, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
