[75726] = { ["id"] = 75726, ["name"] = "Sweaty Armor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 75726 }, ["description"] = "Well hey there, friend! Word is starting to spread about your continued support! We found some armor that might help you out, in thanks for all your troubles. Make sure to swing by Loamm so we can get you situated. Best, Harlowe Marl", ["objectivesText"] = "Talk to Harlowe Marl in Loamm.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[75727] = { ["id"] = 75727, ["name"] = "The Smelliest Tabard", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75727 }, ["description"] = "Greetings, $p! You just keep doing us amazing favors, don't you? Come on back to Loamm for an extra special reward! Sincerely, Mimuup", ["objectivesText"] = "Talk to Mimuup in Loamm.", ["rewardItems"] = { 205286 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205127, ["x"] = 0.564, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204254, ["x"] = 0.565, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75728] = { ["id"] = 75728, ["name"] = "Bartering Boulders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75728 }, ["description"] = "Oh hey, Uplander! I could use your help again. I like your battering style. But you know these bricks? They're useless! Boulders are where it's at! Come see me in Loamm, and I'll give you all the details. Ponzo", ["objectivesText"] = "Talk to Ponzo in Loamm.", ["rewardItems"] = { 204985, 205188 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205127, ["x"] = 0.564, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204693, ["x"] = 0.58, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75729] = { ["id"] = 75729, ["name"] = "Attune to the Observer", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Can you believe this used to be an observatory? Our records indicate that the dragonkin here were mapping heavenly bodies in an attempt to predict the future. How do you think they did it? I'm picking up a partial signature that matches the time window we're shooting for. Put on the Technoscryers and try to pinpoint the sources so we can dial it in.", ["objectivesText"] = "Technoscry for the three attunement relics. Progress: Without those attunement relics we won't be able to solve this mystery, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 202247 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 204835, ["x"] = 0.564, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 204835, ["x"] = 0.564, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3079 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 5469, ["name"] = "Azerothian Archives - Technoscrying Sites", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5515, ["name"] = "Technoscrying: Concord Observatory", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 12, ["flags"] = 0 } } },
[75730] = { ["id"] = 75730, ["name"] = "Slitherdrake Watching", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75730 }, ["description"] = "Well hello there! Word around here is that we've got your continued support--so we got a little something for you. Meet me in Loamm so I can hand it over! Best, Harlowe Marl", ["objectivesText"] = "Talk to Harlowe Marl in Loamm.", ["rewardItems"] = { 203323, 203335, 203341 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205127, ["x"] = 0.564, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202468, ["x"] = 0.564, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
