[75765] = { ["id"] = 75765, ["name"] = "Liquid Art", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75765 }, ["description"] = "<A clay pot filled with... mud? It appears to be niffen in origin. Perhaps a resident of Loamm is looking for it!>", ["objectivesText"] = "Return the Dripping Clay Pot to its owner in Loamm. Progress: Oh, is that...?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 204985, 205188, 205366 }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204215, ["x"] = 0.578, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["startItems"] = { 205366 } },
[75766] = { ["id"] = 75766, ["name"] = "Ruby in the Rough", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75766 }, ["description"] = "<A beautiful ruby set in fine gold sits nestled in a box of draconic origin. The jewelcrafter in Loamm would love to take a look at this.>", ["objectivesText"] = "Deliver the Shimmering Draconic Gem to Fanilly in Loamm. Progress: It's SO shiny!!", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 204985, 205188, 205900 }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203612, ["x"] = 0.566, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["startItems"] = { 205900 } },
[75767] = { ["id"] = 75767, ["name"] = "Good Time Boy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75767 }, ["description"] = "<A very wet gorloc totem rests on the cave floor. How did this even get here? The niffen love stuff like this. Maybe someone in Loamm will take it off your hands.>", ["objectivesText"] = "Find a new home for the Soaked Totem in Loamm. Progress: I've needed a backup dancer!", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 204985, 205188, 205907 }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204863, ["x"] = 0.572, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["startItems"] = { 205907 } },
