[76280] = { ["id"] = 76280, ["name"] = "New Moon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 76276, 76280, 76281, 76282, 76283, 77200, 77201, 77329, 77780, 77781 }, ["description"] = "With these offerings and water from the Well of Eternity, we have all that we need. Speak with me when you are ready to begin the ritual.", ["objectivesText"] = "Speak with Tyrande Whisperwind in the Central Encampment to begin the ritual. Progress: Amirdrassil...", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 208537, ["x"] = 0.508, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 208537, ["x"] = 0.508, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5473, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239, ["questLines"] = { { ["id"] = 5473, ["name"] = "New Beginnings", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 63, ["flags"] = 0 } } },
[76281] = { ["id"] = 76281, ["name"] = "Something Worth Celebrating", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 76276, 76280, 76281, 76282, 76283, 77200, 77201, 77329, 77780, 77781 }, ["description"] = "At long last... let us celebrate all that we have overcome, and the hope that burns brightly amongst these gathered kaldorei. Come, join the festivities.", ["objectivesText"] = "Serve tables at the celebration in Bel'ameth. Progress: Have you thoroughly enjoyed yourself, Champion?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 208537, ["x"] = 0.508, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 206849, ["x"] = 0.542, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5473, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239, ["questLines"] = { { ["id"] = 5473, ["name"] = "New Beginnings", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 64, ["flags"] = 0 } } },
