[76290] = { ["id"] = 76290, ["name"] = "Omarion's Second Handbook", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 139, ["storyline"] = { 76290 }, ["description"] = "Wilhelm, If you are reading this, the first adventurer I sent to you has perished. As have I, finally. I want you to know that my dying thoughts revolved around you and your ineptitude in tradeskills. About the book: These are the rest of my recipes. Please share them with someone more capable. Alas, I am sure you will keep them for yourself and charge a hefty fee for your services because you are, after all, a bastard. In Disdain, Omarion", ["objectivesText"] = "Return the handbook to Master Craftsman Omarion at Light's Hope Chapel in the Eastern Plaguelands.", ["rewardItems"] = { 206449 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["startItems"] = { 206449 } },
[76308] = { ["id"] = 76308, ["name"] = "The Trial of Style", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 76308 }, ["description"] = "Well, that's certainly an... interesting look, <class>. Me? Judgmental? Certainly not. However, I'm curious what others would think of it. You should speak to the Transmogrifier over there and enter the Trial of Style. We'll see what public opinion says about your choice in garb.", ["objectivesText"] = "Speak to a Transmogrifier to enter and complete the Trial of Style. Progress: Ugh, I'm so bored. Did you complete the Trial of Style yet?", ["rewardGold"] = 30900, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 206252, ["x"] = 0.51, ["y"] = 0.725 }, { ["mapID"] = 85, ["npcID"] = 206383, ["x"] = 0.488, ["y"] = 0.765 }, { ["mapID"] = 2339, ["npcID"] = 236405, ["x"] = 0.455, ["y"] = 0.527 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 206252, ["x"] = 0.51, ["y"] = 0.725 }, { ["mapID"] = 85, ["npcID"] = 206383, ["x"] = 0.488, ["y"] = 0.765 }, { ["mapID"] = 2339, ["npcID"] = 236405, ["x"] = 0.455, ["y"] = 0.527 }, { ["mapID"] = 2393, ["npcID"] = 258350, ["x"] = 0.522, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.725 }, ["mapCandidates"] = { ["npc"] = { 84, 85, 2339, 2393 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 2393 },
