[76342] = { ["id"] = 76342, ["name"] = "Light 'Em Up!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76342, 76343, 76344, 76345, 76347, 76348, 76403, 76532, 77178 }, ["description"] = "After Vyranoth left, Fyrakk put all four of the Claws of Vyranoth on different tasks. He left me in charge of this camp and told me to keep the portals open at all costs. The Druids of the Flame are empowering the portals for the Primalist's reinforcements to come through. We should close those portals and thin out their ranks.", ["objectivesText"] = "Weaken the Primalist encampment in the Primalist Stronghold. Progress: The Primalists will only multiply in numbers if we do not hinder them.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 29735, 35884, 35885, 35886, 35887, 36888, 36937, 36938, 38213, 44018, 44039, 44041, 44042, 44043, 65482, 122637, 124634, 124635, 124636, 124637, 124638, 139693, 140610, 140611, 140612, 140613, 140614, 140615, 140616, 140617, 155656, 157829, 158667, 159124, 159152, 159153, 159154, 159155, 181368, 181377, 181612, 181745, 182487, 182496, 182505, 182514, 183744, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184842, 184843, 185717, 207101, 209883, 209889, 211279, 220161, 223432, 223472, 224817, 237812, 242241, 246813, 246815, 246936, 247234, 247915, 248027, 248028, 248029, 248053, 248247, 248555, 248556, 248557, 248558, 248559, 248560, 248561, 248562, 249400, 249780, 251257, 251724, 251725, 251726, 251727, 251728, 251729, 251730, 251731, 251732, 251733, 251734, 251821, 253467, 254267, 254579, 254878, 257143, 264675, 265106, 265631 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206619, ["x"] = 0.368, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206619, ["x"] = 0.368, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5472, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5472, ["name"] = "Ice and Fire", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 27, ["flags"] = 0 } } },
[76343] = { ["id"] = 76343, ["name"] = "Best Laid Plans", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76342, 76343, 76344, 76345, 76347, 76348, 76403, 76532, 77178 }, ["description"] = "Fyrakk may be brash, but he is not a fool. If we are to save the Dream, we must undermine his plans as quickly as possible. At their core, the Primalists are unorganized. Infiltrate their camp and search for any clues or information. The more information we have, the sooner we can take down Fyrakk once and for all.", ["objectivesText"] = "Collect 4 clues in the Primalist Stronghold.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 153735, 153736, 153785, 153786, 153806, 153807, 153820, 153821, 153845, 153846, 153902, 153903, 153936, 153937, 153952, 153953, 154001, 154002, 154014, 154015, 154039, 154040, 154738, 154741, 194524, 194527 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206612, ["x"] = 0.368, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206612, ["x"] = 0.368, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5472, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5472, ["name"] = "Ice and Fire", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 28, ["flags"] = 0 } } },
[76344] = { ["id"] = 76344, ["name"] = "Primalist Directive", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76342, 76343, 76344, 76345, 76347, 76348, 76403, 76532, 77178 }, ["description"] = "Terro was another one of Vyranoth's claws. He never wanted to attack the Dream, and some of the Primalists who served him may feel the same. See if you can convince them to join our side. I can put a mark of Vyranoth on you so Terro's troops will not attack you... right away.", ["objectivesText"] = "Convince 5 of Terro's Primalists to side with Vyranoth. Progress: Terro never wanted to attack the Dream. It was against his nature.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206619, ["x"] = 0.368, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210178, ["x"] = 0.395, ["y"] = 0.228 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5472, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5472, ["name"] = "Ice and Fire", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 29, ["flags"] = 0 } } },
[76345] = { ["id"] = 76345, ["name"] = "Finding Terro", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76342, 76343, 76344, 76345, 76347, 76348, 76403, 76532, 77178 }, ["description"] = "I had no idea my old guard would be willing to return to my side. I am... I am happy to see them. When I chose to go to Alexstrasza, I told no one. I simply left. But we must learn more about Fyrakk's plan before pursuing personal matters. Let us see what else Buri can tell us.", ["objectivesText"] = "Uncover more information about Fyrakk's plan in the Emerald Dream . Progress: If we could just find the other Claws...", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 209915, 209916 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206612, ["x"] = 0.368, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210178, ["x"] = 0.395, ["y"] = 0.228 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5472, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5472, ["name"] = "Ice and Fire", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 30, ["flags"] = 0 } } },
[76347] = { ["id"] = 76347, ["name"] = "Power, Eruption, and Lies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76342, 76343, 76344, 76345, 76347, 76348, 76403, 76532, 77178 }, ["description"] = "Buri told me that Lethka plans to ignite Cinder Summit, and Vyranoth pursued her. Lethka revealed herself because she knew that Vyranoth would go after her. The power in Cinder Summit can destroy this barrier, or Vyranoth . We have to go after them.", ["objectivesText"] = "Slay Lethka at Cinder Summit.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 209885, 209926 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208725, ["x"] = 0.335, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210733, ["x"] = 0.336, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.335, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5472, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5472, ["name"] = "Ice and Fire", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 33, ["flags"] = 0 } } },
[76348] = { ["id"] = 76348, ["name"] = "Big Bright Beautiful Barrier", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76342, 76343, 76344, 76345, 76347, 76348, 76403, 76532, 77178 }, ["description"] = "Buri? Vyranoth? Once she left us at the mercy of Fyrakk, we had no choice but to follow him. I do not know what his plan is, but he ordered me and these Primalists to bring down this barrier. We have made little progress, but Vyranoth will want us to slow him down. Some fragments of the barrier have chipped away. If you collect them, we can channel their energy back into the shield. Can I trust you to undo the damage that I have done?", ["objectivesText"] = "Collect 6 Barrier Fragments in the Emerald Dream .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 209895, 209896, 209897, 209898 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208378, ["x"] = 0.276, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208725, ["x"] = 0.335, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5472, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5472, ["name"] = "Ice and Fire", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 32, ["flags"] = 0 } } },
[76350] = { ["id"] = 76350, ["name"] = "The Chronosmith", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76350 }, ["description"] = "Are you here to aid us? As you can see, the time anomaly around Eon's Fringe has dissipated and there is no shortage of work to be done. We've called in for help from one our best chronosmiths, a bronze dragon by the name of Ironormu. The problem, amongst all this chaos, is that he's nowhere to be found. He should have been back from setting up his workshop by now. <Tempo sighs in agitation.> Can you go find him?", ["objectivesText"] = "Seek out Ironormu at the forge in Eon's Fringe.", ["rewardGold"] = 280900, ["rewardXP"] = 7135, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 195773, ["x"] = 0.548, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205679, ["x"] = 0.525, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[76351] = { ["id"] = 76351, ["name"] = "Titanic Beasts", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76351 }, ["description"] = "<This small device rolled out of the mouth of a beast you defeated. It appears to be a titan information device, but it's more compact than devices you've seen on Azeroth. Soridormi will want to see this.>", ["objectivesText"] = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 206564, 208186 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["startItems"] = { 206564 } },
[76352] = { ["id"] = 76352, ["name"] = "Chronohammer Time!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76352 }, ["description"] = "If I'm to repair young Finduin's blade here, then we need to crack open this timelock on me forge. And if a hammer can break a lock, then I'm betting a chronohammer can break a timelock. Unfortunately, my hammer's a wee bit out of sync. But we're in the prime sort of mishap to fix that. Nearby rifts are tearing into our timeline just outside the Temporal Conflux and out-of-time uglies are pouring through. Head out of Eon's Fringe, clear the area, and recharge my hammer.", ["objectivesText"] = "Kill time-displaced creatures and destroy rifts in the Passage of Time to resync Ironus's Chronohammer.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205679, ["x"] = 0.525, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205679, ["x"] = 0.525, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[76354] = { ["id"] = 76354, ["name"] = "For the Hoard!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76354 }, ["description"] = "I have a storage vault in the Passage of Time chock-full of chronomatic crates. They contain timelost artifacts from various timelines. Unfortunately, me safeguard protocols on the vault itself were damaged by those blasted time rifts. I did a quick fly-about and saw those infernal looters scattering my crates everywhere! Since you're heading that way, can you grab some of my possessions as you go? Not all of them, of course! Just the important stuff.", ["objectivesText"] = "Find and collect Ironus's artifacts. Progress: I swear by the heat of me forge, if any of those retched looters broke into me crates and took anything, I'm going to... Well, we bronze dragons have all sorts of techniques, don't we?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 198612, 208053 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205679, ["x"] = 0.525, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205679, ["x"] = 0.525, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[76355] = { ["id"] = 76355, ["name"] = "If a Hammer Can Break a Lock...", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76355 }, ["description"] = "Now that the hammer is all charged up, all we need is to take one big swing at the time-lock and BOOM! Nothing breaks a temporally-crafted anomaly like a temporally-charged hammer. We'd just need to account for a possible sundering of time and... <Ironus hesitates for a moment as he makes a few calculations under his breath before he looks at you with a not-so-confident smile.> Tell you what? You earned this! You do the honors.", ["objectivesText"] = "Shatter the time-lock with the Chronoforged Hammer.", ["rewardGold"] = 280900, ["rewardXP"] = 7135, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205679, ["x"] = 0.525, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208825, ["x"] = 0.522, ["y"] = 0.805 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[76356] = { ["id"] = 76356, ["name"] = "Sword Stealing Searers", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76356 }, ["description"] = "Those grubby forgespawns knocked Finduin right over and took Seashellamayne! They must've sensed the temporal energies lingering on the sword. Can't imagine what they'd want with it, but there's no time to wait and see. Everything you've done won't mean much if I don't have Finduin's blade to fix. Could you fetch it for me? After all, the fate of Azmerloth depends on it!", ["objectivesText"] = "Retrieve Finduin Wryngrrlgulgll's blade Seashellamayne. Progress: Like time-moths to the chrono-flame, those wee elementals were drawn to Seashellamayne! I can only hope the damage done to it is minimal.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 208100 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208825, ["x"] = 0.522, ["y"] = 0.805 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206138, ["x"] = 0.522, ["y"] = 0.806 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.805 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
