[76361] = { ["id"] = 76361, ["name"] = "Fashion Week", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14771, ["mapID"] = 2112, ["storyline"] = { 76361 }, ["description"] = "Ah, the Trial of Style is upon us, <class>. The outfits, the creativity, the elegance of the Trial are truly a sight to see. Speak to a Trial of Style Envoy to learn more about the event. A word of warning, those envoys can be... challenging to deal with.", ["objectivesText"] = "Speak to a Trial of Style Envoy.", ["rewardGold"] = 28090, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199261, ["x"] = 0.390667, ["y"] = 0.61 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 }, { ["mapID"] = 2339, ["npcID"] = 220870, ["x"] = 0.41, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 206252, ["x"] = 0.51, ["y"] = 0.725 }, { ["mapID"] = 85, ["npcID"] = 206383, ["x"] = 0.488, ["y"] = 0.765 }, { ["mapID"] = 2339, ["npcID"] = 236405, ["x"] = 0.455, ["y"] = 0.527 }, { ["mapID"] = 2393, ["npcID"] = 258350, ["x"] = 0.522, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.390667, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 84, 85, 2112, 2339, 2393 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 2393 },
[76362] = { ["id"] = 76362, ["name"] = "An Antlered Skull", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14843, ["mapID"] = 2025, ["storyline"] = { 76362 }, ["description"] = "<Despite its surroundings, this skull does not appear to be fel-corrupted. As you move your hand closer, you feel a sense of calm emanating from it. Soridormi will want to see this.>", ["objectivesText"] = "Bring the Antlered Skull to Soridormi in the Tyrhold Reservoir. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 206578, 208186 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 14843 } }, ["questType"] = "standard", ["startItems"] = { 206578 } },
