[76384] = { ["id"] = 76384, ["name"] = "The Bloom Begins", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "I sense a change on the wind. Like the dawning rays of the sun. Like petals before they unfurl. A great swelling energy, right at the heart of the Emerald Dream . The Bloom. It has begun.", ["objectivesText"] = "Witness Amirdrassil begin to bloom. Progress: A bloom so beautiful, yet it brings such dread. Can we truly prevail?", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206896, ["x"] = 0.508, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206896, ["x"] = 0.508, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 47, ["flags"] = 0 } } },
[76385] = { ["id"] = 76385, ["name"] = "Hazardous Horticulture", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "We may be outnumbered, but this is my domain. And I have a way of evening our odds. Take this pouch of seeds. Plant them throughout Wildfire Canyon and the Dream's faerie dragons will transform them into treants. With luck, they will draw attention from our front lines and bolster our ground forces.", ["objectivesText"] = "Plant 6 Dream Seeds across Wildfire Canyon. Progress: Hopefully the faerie dragons are small enough to go unnoticed by Fyrakk's forces.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208551, ["x"] = 0.388, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208551, ["x"] = 0.388, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 49, ["flags"] = 0 } } },
[76386] = { ["id"] = 76386, ["name"] = "A Clash of Ice and Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "The Primalists have erected great flame wards throughout their encampment. Yet we know not why. I have asked our ground forces to investigate, but they are blocked at every turn. Two fire elementals in particular stand against us, empowered by Fyrakk's shadowflame. You must clear the area of enemies. I have imbued this scale with my magic. Use it to weaken the elementals and any other who stands in your way.", ["objectivesText"] = "Slay Calderamor , Ignarion , and 15 Wildfire enemies. Progress: Even in the heat of battle, the Primalists continue to empower those flame wards. But to what end? We must clear the way so that our forces can investigate.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208544, 209906, 209929 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208553, ["x"] = 0.388, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208553, ["x"] = 0.388, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 50, ["flags"] = 0 } } },
[76387] = { ["id"] = 76387, ["name"] = "Defense of the Ancients", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "Fyrakk's forces at Skystone Falls are already threatening to overwhelm us. I fear not even the combined might of the Sentinels and Ancients can hold out against them. The Ancients are bearing the brunt of the offensive. We have reports of djaradin attempting to capture them for some unknown purpose. We cannot allow Igira to succeed in whatever nefarious plan she has in mind. You must seek out the Ancients on the battlefield and free any who are captured.", ["objectivesText"] = "Free the Ancients at Skystone Falls. Progress: The Ancients may be few, but they battle fiercely for our cause. Go, <name>. Help them.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 209887 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208552, ["x"] = 0.388, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208552, ["x"] = 0.388, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 51, ["flags"] = 0 } } },
[76388] = { ["id"] = 76388, ["name"] = "Fighting Fire With Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "The notes you found, combined with Merithra's reconnaissance, have revealed Ashendir's plan. The flame wards that surround the Wellspring Temple are blocking our reinforcements. Our allies will distract Fyrakk while you and I slip behind enemy lines to destroy the wards. The skies are filled with drakes, and I must fend them off. Once you find a flame ward and thin out its defenses, signal me to destroy it.", ["objectivesText"] = "Clear out Skyfire Turrets and mark Primalist Flame Wards.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 155159, 155162, 209898 }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208568, ["x"] = 0.35, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 53, ["flags"] = 0 } } },
[76389] = { ["id"] = 76389, ["name"] = "The Age of Mortals", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "Once again, the mortal races have come together to defend a World Tree. It is only fitting then that we bolster their efforts with a relic from that past battle. The Horn of Cenarius . I entrust the horn to you, <name>. Use it to bestow the blessings of Cenarius to our allies. With luck, it will allow us to break through Fyrakk's forces and open a path to the temple. And do not forget to lend your strength as well. Every enemy felled is one fewer between us and Fyrakk.", ["objectivesText"] = "Blow the Horn of Cenarius while next to heroes of Azeroth and slay Fyrakk's forces.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 208752, 209899 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208568, ["x"] = 0.35, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 54, ["flags"] = 0 } } },
[76390] = { ["id"] = 76390, ["name"] = "Inconvenience Fee", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 3456, ["storyline"] = { 76390 }, ["description"] = "I have no idea how you managed to find me or what possessed you to douse a dead guy with holy water, but we can both agree that you owe me. That stuff hurts! Fortunately for you, I like bribes more than my naps. I will happily overlook this horrible first impression you gave so you and I can be best pals; scratch my back and I'll scratch yours. What do you say?", ["objectivesText"] = "Zackett Skullsmash in the rafters of Naxxramas has offered to overlook your transgression in exchange for a variety of items. Progress: Hey, that was quick! What did you forget?", ["rewardItems"] = { 12846, 20520, 33042, 206374, 206375, 206615, 206623, 206631, 206640 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3456 } }, ["questType"] = "standard" },
[76395] = { ["id"] = 76395, ["name"] = "Corruptor's Scourgestones", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 3456, ["storyline"] = { 76395 }, ["objectivesText"] = "Progress: I doubt I need to give you the entire spiel about scourgestones, <name>, so I will cut to the chase. I am VERY interested in growing my collection, and you are VERY interested in what I have to offer. Corruptor's Scourgestones are by far the most powerful, so we can talk business if you only have a few. And don't tell the Argent Dawn about this! It's our little secret, right pal?", ["rewardItems"] = { 12844, 206375, 206576 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3456 } }, ["questType"] = "standard" },
[76396] = { ["id"] = 76396, ["name"] = "Invader's Scourgestones", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 3456, ["storyline"] = { 76396 }, ["objectivesText"] = "Progress: I doubt I need to give you the entire spiel about scourgestones, <name>, so I will cut to the chase. I am VERY interested in growing my collection, and you are VERY interested in what I have to offer. Invader's Scourgestones are rather common, so I ask you bring a decent haul. And don't tell the Argent Dawn about this! It's our little secret, right pal?", ["rewardItems"] = { 12844, 206374, 206576 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3456 } }, ["questType"] = "standard" },
[76397] = { ["id"] = 76397, ["name"] = "Elwynn Forest Flash", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 76397 }, ["description"] = "Fly through the checkpoint rings marking the course.", ["objectivesText"] = "Glide through the rings.", ["rewardItems"] = { 188134, 191140, 203306, 203336, 203355, 203359, 206588, 206589, 206590, 206591, 206592, 206593, 206594 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[76398] = { ["id"] = 76398, ["name"] = "Aerial Supremacy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "The dragonflights have arrived. The skies are ours to reclaim! And you shall help us tip the scales. Mount your drake and target the enemies above. You need only swoop in and take their forces by surprise. Your drake shall handle the rest.", ["objectivesText"] = "Slay 15 enemy proto-drakes flying above the Field of Flames by striking them with your dragonriding mount. Progress: The faster we can take down Fyrakk's aerial forces, the faster we can make our way to the temple and put a stop to this madness.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208567, ["x"] = 0.35, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208567, ["x"] = 0.35, ["y"] = 0.354 }, { ["mapID"] = 2200, ["npcID"] = 208573, ["x"] = 0.35, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 55, ["flags"] = 0 } } },
