[76441] = { ["id"] = 76441, ["name"] = "Grim Reprisal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76433, 76434, 76435, 76437, 76441, 76442, 76443, 77436 }, ["description"] = "The Druids of the Flame will not allow you to proceed unfettered once your intentions here become clear. They are my kin, my brothers and sisters under Elune... But they seek to undo all that we have toiled for. Their machinations would condemn countless lives to an all-consuming inferno. I won't allow it. We cannot allow it. Disrupt their rituals. Destroy their supplies. If they raise their blades against you, cut them down.", ["objectivesText"] = "Disrupt the Smoldering Copse. Progress: Take heed. These druids' zealotry fuels their reckless ends. Should they identify you as an enemy, they will not show mercy.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207160, ["x"] = 0.392, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207160, ["x"] = 0.392, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5471, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5471, ["name"] = "Druids of the Flame", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 23, ["flags"] = 0 } } },
[76442] = { ["id"] = 76442, ["name"] = "Forlorn Hope", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76433, 76434, 76435, 76437, 76441, 76442, 76443, 77436 }, ["description"] = "You've arrived just in time. Norana lurks just beyond the ridge. She appears to be taking part in some manner of ritual - alongside a man who appears to be their leader. These are powerful druids, and their strength is amplified by their ties to the Firelands. Taking the blade to all of them at once would be foolish. Still, the least we can do is disrupt their ritual. If we send them scattering, we buy ourselves time - and an opportunity to press the advance elsewhere.", ["objectivesText"] = "Interrupt the Flame Druids' ritual.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 209900 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207160, ["x"] = 0.392, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211193, ["x"] = 0.36, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5471, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5471, ["name"] = "Druids of the Flame", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 24, ["flags"] = 0 } } },
[76443] = { ["id"] = 76443, ["name"] = "The Looming Cinder", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76433, 76434, 76435, 76437, 76441, 76442, 76443, 77436 }, ["description"] = "The Druids of the Flame are nothing more than allies of convenience to Fyrakk and his ilk. Nevertheless, they present a dire threat to the well-being of Amirdrassil, to say nothing of the rest of the Dream. The victory we earned here today was hard-fought, but it only served to stem the tide. No doubt the Prophet and the Priestess have already reunited with their erstwhile allies. We should return to Merithra . She needs to know of this.", ["objectivesText"] = "Return to Merithra at Amirdrassil.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 208067, 210730 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211193, ["x"] = 0.36, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206896, ["x"] = 0.508, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5471, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5471, ["name"] = "Druids of the Flame", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 25, ["flags"] = 0 } } },
