[76564] = { ["id"] = 76564, ["name"] = "The Tools of the Dragonkillers", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "If you're going to go after a dragon, who better to employ than the Djaradin? Let's see what we can find, <name>.", ["objectivesText"] = "Locate the three attunement relics. Progress: Without those attunement relics we won't be able to solve this mystery, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 202247 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 207763, ["x"] = 0.382, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 207763, ["x"] = 0.382, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.382, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3079 }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5469, ["name"] = "Azerothian Archives - Technoscrying Sites", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5516, ["name"] = "Technoscrying: Igira's Watch", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 38, ["flags"] = 0 } } },
[76566] = { ["id"] = 76566, ["name"] = "The Dryad Garden", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76566 }, ["description"] = "$p, there is a situation I am personally concerned about. A garden cared for by my kin, the dryads, has suffered from growing pains amidst Amirdrassil's growth. An overwrought druid currently tends the garden, but I suspect he will need more assistance than he has requested. Please assist him in his task on my behalf.", ["objectivesText"] = "Speak with Ethidris Creekward in the Root-Bound Sanctuary.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 209318, ["x"] = 0.508, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[76567] = { ["id"] = 76567, ["name"] = "Grousing Garden", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76567 }, ["series"] = { 76568, 76569, 76570 }, ["description"] = "The sanctuary has been overrun! The roots of the World Tree have grown alongside this garden, but it seems the wildlife have grown uncomfortable with the change. Please help them get out their restless energy. Perhaps tired out, they will relax in this space again.", ["objectivesText"] = "Tire out 8 wildlife in the Root-Bound Sanctuary. Progress: <Ethidris winces and rubs his shoulder.> You would think being a bear would lend oneself resistance to being knocked around by deer.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[76568] = { ["id"] = 76568, ["name"] = "Pineshrew Panic", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76568 }, ["series"] = { 76567, 76569, 76570 }, ["description"] = "With the garden in such disarray, the pineshrews here are hoarding seeds. Important seeds. Seeds we've spent a lot of time caring for and teaching. A gentle shake will release the seeds properly. Please hurry before they run off with any more!", ["objectivesText"] = "Shake out 20 Pineshrew seeds in the Root-Bound Sanctuary. Progress: Ordinarily, pineshrews shake out collected seeds across the Dream to promote variety and growth. It's a beautiful cycle. If you have a few hours, I have a lesson prepared about pineshrew migration habits.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[76569] = { ["id"] = 76569, ["name"] = "Druid-Guardian Conference", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76569 }, ["series"] = { 76567, 76568, 76570 }, ["description"] = "Typically, the druid assigned to a dryad sanctuary would guide a newborn dryad until they were ready to take on a position of their own. Unfortunately, it is difficult to separate a dryad from whoever she imprints on. <Ethidris sighs and rubs his eyes.> Which she has made very clear. Regardless, tell me about yourself. Perhaps you will be just as apt a caretaker as I would have been.", ["objectivesText"] = "Speak with Ethidris Creekward about raising a dryad in the Root-Bound Sanctuary. Progress: <Ethidris furrows his brow at Dionaessa.> Among so many other things happening right now, there's a new dryad to raise.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 211371 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[76570] = { ["id"] = 76570, ["name"] = "The Family Business", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76570 }, ["series"] = { 76567, 76568, 76569 }, ["description"] = "I was charged with imparting knowledge on every dryad seed. Dionaessa will have retained all of my teachings, but she will be unpracticed in implementing them. Since it seems you are practiced at completing tasks, you will show Dionaessa the ropes. A group of lashers have grown strangely restless in the Twisting Wood just outside the garden. Collect some of their hearts so we can discern what has happened.", ["objectivesText"] = "Collect 6 Lasher Hearts in the Twisting Wood near the Root-Bound Sanctuary. Progress: The druid Creekward told me lashers tend to lie in wait for their prey. I'm glad these are not. Makes the fight more interesting!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 208732 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[76571] = { ["id"] = 76571, ["name"] = "Growth Experience", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76571 }, ["description"] = "Dionaessa's connection to Cenarius gives her the ability to grow plants, but she needs space to practice. The stirred-up wildlife here will be in your way. The Twisting Wood nearby will have plenty of space with far fewer hooves. <Melyrine smiles. Her eyes shine with intensity.> If she gets poisoned by a podling, don't worry. Dryads are immune to poison. You are not.", ["objectivesText"] = "Have Dionaessa grow 3 flowers in the Twisting Wood. Progress: Do you smell that? <Dionaessa scrunches up her face.> The druid Creekward did not describe lashers and podlings as smelling so foul. I have been misled!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207781, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[76572] = { ["id"] = 76572, ["name"] = "A Poisonous Promotion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76572 }, ["description"] = "Guardian! These podlings have been poisoning the lashers, and now they have twisted that mandragora! If we do not stop it, it will spread the poison to the garden. This must be what had the wildlife in the garden so disturbed. They were on the verge of invasion! Let us kill it. This is what you have prepared me for--a dire quest!", ["objectivesText"] = "Defeat the Sickened Growth in the Twisting Wood.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 208067 }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 209788, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[76576] = { ["id"] = 76576, ["name"] = "An Unlikely Proposal", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Tuskarr artifacts, underground, deep in Djaradin territory? If we didn't find it ourselves I wouldn't believe it. What do you think they were doing down here? Ok looks like the nexus point is right here in this cave. Let's get to the bottom of this!", ["objectivesText"] = "Observe the Scene from the past. Progress: I wonder what we'll find?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 202247 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 207763, ["x"] = 0.382, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 207763, ["x"] = 0.382, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.382, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3079 }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5469, ["name"] = "Azerothian Archives - Technoscrying Sites", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5516, ["name"] = "Technoscrying: Igira's Watch", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 39, ["flags"] = 0 } } },
[76577] = { ["id"] = 76577, ["name"] = "Brewfest in Valdrakken", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Brewfest", ["expansion"] = 9, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 76577 }, ["description"] = "We've sent some Brewfest shipments off to the Dragon Isles. I've heard they've started some of their own celebrations! Of course ye can't beat the festivities here, but it may be worth paying the dragons a visit!", ["objectivesText"] = "Speak to Bragdur Battlebrew in Valdrakken on the Dragon Isles.", ["starts"] = { { ["mapID"] = 27, ["npcID"] = 24710, ["x"] = 0.506, ["y"] = 0.491 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 207496, ["x"] = 0.298, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.491 }, ["mapCandidates"] = { ["npc"] = { 27, 2112 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Epic" },
[76579] = { ["id"] = 76579, ["name"] = "Brewfest in Valdrakken", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Brewfest", ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 76579 }, ["description"] = "Seems the dracthyr have decided to host their own Brewfest festivities this year! Once you've finished celebrating here, you should venture to the Dragon Isles and see what they've put together.", ["objectivesText"] = "Speak to Bragdur Battlebrew in Valdrakken on the Dragon Isles.", ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155194, ["x"] = 0.415, ["y"] = 0.183 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 207496, ["x"] = 0.298, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.183 }, ["mapCandidates"] = { ["npc"] = { 1, 2112 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
[76591] = { ["id"] = 76591, ["name"] = "Bubbling Brews", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 76591 }, ["description"] = "Drat! I might've made a mistake asking the dracthyr to help with these deliveries. They've been rolling barrels of brews through the city and crashing 'em all over the place! Well, we shouldn't let the brew go to waste if we can help it! Take a barrel an' take to the skies! Try to collect and save as much of the brew as you can by collecting the bubbles.", ["objectivesText"] = "Collect brew bubbles in Valdrakken. Progress: Have ye filled up the barrel?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 37829 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 207496, ["x"] = 0.298, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 207496, ["x"] = 0.298, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 } },
[76593] = { ["id"] = 76593, ["name"] = "The Best Intentions", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 76592, 76593, 76594, 76595, 76597, 77098, 77163 }, ["description"] = "Not only did they beat him--they put him in shackles too! What's worse is... I probably would have done the same... We will not be able to carry Marithos out of here with this weight chained to him. The key must be around the camp somewhere. Try to find it, <name>, while I keep him comfortable.", ["objectivesText"] = "Look for a key to Marithos's shackles in the Lonely Falls. Progress: We must free Marithos from his bonds.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 208014 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 207819, ["x"] = 0.748, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 207819, ["x"] = 0.748, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5464, ["name"] = "Reconciliation", ["orderIndex"] = 3, ["flags"] = 0 } } },
[76594] = { ["id"] = 76594, ["name"] = "Dracthyr Down", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 76592, 76593, 76594, 76595, 76597, 77098, 77163 }, ["description"] = "What was done to Marithos goes beyond what simple healing can fix. If we expect him to fly out of here, he will need extra care. Thankfully, there are herbs nearby that may give his healing a boost--enough to get him standing, anyway. Look around and collect some of the Wingfoil nearby, <name>.", ["objectivesText"] = "Look for Wingfoil herbs in the Lonely Falls. Progress: Have you found that Wingfoil ? Marithos cannot fly without it.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 208004 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 207819, ["x"] = 0.748, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 207819, ["x"] = 0.748, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5464, ["name"] = "Reconciliation", ["orderIndex"] = 4, ["flags"] = 0 } } },
[76595] = { ["id"] = 76595, ["name"] = "Urgent Exfiltration", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 76592, 76593, 76594, 76595, 76597, 77098, 77163 }, ["description"] = "The Sundered Flame here are not going to take Quartermaster Doros's death well... They are going to come looking for me. Marithos and Amythora are vulnerable. We cannot let them find us. Secure the perimeter and keep the Sundered Flame away from Amythora and Marithos.", ["objectivesText"] = "Keep the Sundered Flame away from Amythora and Marithos. Progress: If they find us, I do not think the Sundered Flame loyalists will take prisoners.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 204076 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 207820, ["x"] = 0.748, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 207820, ["x"] = 0.748, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5464, ["name"] = "Reconciliation", ["orderIndex"] = 5, ["flags"] = 0 } } },
[76597] = { ["id"] = 76597, ["name"] = "On New Wings", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 76592, 76593, 76594, 76595, 76597, 77098, 77163 }, ["description"] = "I am glad that Winglord Dezran arrived when he did. If he had not, this would have gone... very differently. We must take Marithos back to Valdrakken so he can recuperate, but once I have debriefed Dezran, we will send an envoy to help re-introduce them to our people. They have suffered. We have suffered. Perhaps now we can all heal. Follow me back to Valdrakken. We have much to discuss.", ["objectivesText"] = "Talk to Emberthal in Valdrakken.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 250912 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 207820, ["x"] = 0.748, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 207790, ["x"] = 0.232, ["y"] = 0.374 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2024, 2112 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 5464, ["name"] = "Reconciliation", ["orderIndex"] = 6, ["flags"] = 0 } } },
[76598] = { ["id"] = 76598, ["name"] = "Rough Edges", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76598 }, ["description"] = "I apologize for not meeting you in person, <name>, but this method seemed most timely. Our war against the Primalists has always troubled our queen, but recently she has grown increasingly upset. Something weighs on her. I know how heavy the burdens of the mind can become. She left Valdrakken some time ago, saying she needed to find a quiet place to think, but... I am concerned. Please--seek her out, and make sure she is all right. She does not need to know I sent you.", ["objectivesText"] = "Find Alexstrasza and check on her.", ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208052, ["x"] = 0.548, ["y"] = 0.814 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 208004, ["x"] = 0.565, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.814 }, ["mapCandidates"] = { ["npc"] = { 2022, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
