[77093] = { ["id"] = 77093, ["name"] = "The Shadowflame Axe", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 77093, 77191, 77192, 77193 }, ["description"] = "The moment you attempted to wield Fyrakk's axe, Fyr'alath, its flames consumed you. Clearly the weapon's shadowflame was too intense. Perhaps you should consult an expert on shadowflame and ancient artifacts. Maybe one of the scholars at the Azerothian Archives can deduce a method for handling it safely.", ["objectivesText"] = "Visit the Azerothian Archives to find an expert on Shadowflame", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 190316, 190321, 190324, 190329, 193231, 194756, 194864, 200113, 204460, 204464, 205413, 208212, 208577, 208578, 208592, 208593, 208846, 209351, 209998, 210002, 210003, 210199, 210918, 211396, 211397, 211398 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5462, ["name"] = "Fyr'alath, Dream Render", ["orderIndex"] = 0, ["flags"] = 0 } } },
