[77101] = { ["id"] = 77101, ["name"] = "Ingredient Quest Template", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 77101 }, ["description"] = "Ricket sent word that she was here in Mechagon, so I came right away to help with the uh... research. I had the peons scour the island for any technology they could find. With da stuff we got here, we gonna make some amazing weapons to fight King Mechagon. Then afterwards, we get rich selling 'em! Help me wrangle everyone's ideas into one perfect weapon!", ["objectivesText"] = "Help Rocket-Chief Fuselage build the perfect weapon.", ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
