[77286] = { ["id"] = 77286, ["name"] = "A Knowledgeable Descent", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77286 }, ["description"] = "<The rubbing is in an ancient language. Perhaps Bobby Carlisle can get the text translated.>", ["objectivesText"] = "Take the Unveiled Tablet Rubbing to Bobby Carlisle in Valdrakken . Progress: Did you find anything?", ["rewardItems"] = { 208143 }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 207696, ["x"] = 0.476, ["y"] = 0.470667 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.470667 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
