[77377] = { ["id"] = 77377, ["name"] = "To Tyrhold! For Tyr!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 77339, 77340, 77341, 77342, 77343, 77344, 77377 }, ["description"] = "We recovered. We trained. And now it's time to face Elisande. Come with us to Tyrhold where Nozdormu, Chromie, and Eternus are waiting to send us to the Nighthold. We will get that disc, and Tyr will finally be with us once more.", ["objectivesText"] = "Speak with Eternus in Tyrhold.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208701, ["x"] = 0.605, ["y"] = 0.636 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208832, ["x"] = 0.604, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.636 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5476, ["questLineOrder"] = 3 }, { ["id"] = 241, ["title"] = "Catching Up!", ["questLineID"] = 5476, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5476, ["name"] = "Tyr's Return", ["orderIndex"] = 1, ["flags"] = 0 } } },
