[77408] = { ["id"] = 77408, ["name"] = "Prophecy Stirs", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 84, ["storyline"] = { 77408, 77409, 77410, 77411, 77412, 77789, 77795 }, ["description"] = "Prophet Velen has roused from meditation and he requests your immediate presence. A matter of great import has come to his attention. He would value both your wisdom and strength in addressing it. The Prophet awaits you aboard the Vindicaar . Take this crystal. Our artificers have attuned it to the ship's teleportation matrix.", ["objectivesText"] = "Use the Teleportation Crystal to meet Prophet Velen aboard the Vindicaar . Progress: I am thankful that you could make this journey.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 208206 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 209790, ["x"] = 0.6545, ["y"] = 0.265 }, { ["mapID"] = 85, ["npcID"] = 209803, ["x"] = 0.718, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.6545, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 84, 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1860, ["db2PoiUiMapID"] = 940, ["questLines"] = { { ["id"] = 5482, ["name"] = "Seeing Red", ["orderIndex"] = 0, ["flags"] = 0 } } },
[77409] = { ["id"] = 77409, ["name"] = "Uncertainty", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 9359, ["mapID"] = 830, ["storyline"] = { 77408, 77409, 77410, 77411, 77412, 77789, 77795 }, ["description"] = "Scattered visions came to me as I meditated. Yellow and red. Shattering glass. A rush of warmth. I see my own hand, but I am afraid to grasp it. The scent of fel--of Argus. When I awoke, a message had been delivered. Hatuun wishes to meet. After the defeat of the Legion, I offered to help Hatuun and his people rejoin us. However, they chose to remain on Argus. Hatuun has seldom reached out to us since then. Perhaps he has reconsidered. I will make the journey to Krokuun . Please, join me.", ["objectivesText"] = "Speak to Chieftain Hatuun in Krokuun . Progress: I did not expect Velen to come. He has surprised me.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 208830, ["x"] = 0.538, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 9359 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 5482, ["name"] = "Seeing Red", ["orderIndex"] = 1, ["flags"] = 0 } } },
[77410] = { ["id"] = 77410, ["name"] = "Opening Wounds", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 77408, 77409, 77410, 77411, 77412, 77789, 77795 }, ["description"] = "My hunters were the ones who found Arzal'kal. They said he helped them fight off several Legion ambushes. During our endless vigil on Argus, we had seen nothing like it. He was not as powerful as some demons, but he was persistent. He said he wished to speak with Velen and knew that we had been in contact with him. So, I have fulfilled his request. If Velen is all he claims to be, then he would not turn away even the least worthy of his people. We will see. I expect little.", ["objectivesText"] = "Speak to Arzal'kal and listen to what he has to say. Progress: If Hatuun called me here to listen, then I will. I owe Hatuun that respect.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 208830, ["x"] = 0.538, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 208837, ["x"] = 0.535, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 5482, ["name"] = "Seeing Red", ["orderIndex"] = 2, ["flags"] = 0 } } },
[77411] = { ["id"] = 77411, ["name"] = "Contrition", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 77408, 77409, 77410, 77411, 77412, 77789, 77795 }, ["description"] = "The man'ari have grown desperate since the Legion fell. Some grasp for power. Some isolate themselves. Others have formed cults awaiting the return of Sargeras. They have faith that he will lead them again one day. Nalridun is the leader of one such cult. They are reclusive, but it is rumored that he has seized an ancient relic that Kil'jaeden kept until his death. Nalridun claims to use it to commune with Sargeras. I believe I know what this relic is. If I am correct, it must be returned to Velen.", ["objectivesText"] = "Meet Arzal'kal in the Grove of Naroua, then slay Speaker Nalridun and retrieve the ancient draenic relic. Progress: Even if I die here, at least it will not be at the Legion's whim.", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 174289, 177050, 178153, 179943, 208203 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 208831, ["x"] = 0.536, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 5482, ["name"] = "Seeing Red", ["orderIndex"] = 3, ["flags"] = 0 } } },
[77412] = { ["id"] = 77412, ["name"] = "Proof and Promise", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 77408, 77409, 77410, 77411, 77412, 77789, 77795 }, ["description"] = "Reinforcements are unlikely, but the relic is too important to risk. You should return to Prophet Velen with it immediately. There is a teleporter just ahead that I can attune to a sigil of my own. It will provide you swift passage. I will rejoin you later.", ["objectivesText"] = "Deliver the Brilliant Star to Prophet Velen in Krokuun . Progress: I sense something of great power in your possession. It feels... familiar. But placing the memory feels like grasping at sunlight. Did Arzal'kal lead you to something?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 204076, 208203, 208658, 208691 }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 208893, ["x"] = 0.535, ["y"] = 0.684 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.684 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 5482, ["name"] = "Seeing Red", ["orderIndex"] = 5, ["flags"] = 0 } } },
[77414] = { ["id"] = 77414, ["name"] = "Dreamsurge Investigation", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2022, ["storyline"] = { 77414 }, ["description"] = "The Emerald Dream bleeding over into Azeroth is unprecedented, <name>. We need to understand exactly what is being affected by this phenomenon if we're to prepare ourselves for what is to come. Perhaps we can even turn this to our advantage. Head out into the affected area and see what you can learn. Bring back anything of interest and we will see what can be done.", ["objectivesText"] = "Complete activities in the Dreamsurge. Progress: How fares the Dreamsurge?", ["rewardItems"] = { 207026, 209833 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 208649, ["x"] = 0.584, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 208649, ["x"] = 0.584, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[77417] = { ["id"] = 77417, ["name"] = "What Makes an Infinite", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76407, 76419, 76420, 76421, 76422, 76423, 77417 }, ["description"] = "Eternus clearly has something she wishes to impart to us. I am unsure where this conversation will lead. But I trust Chromie. If she believes that Eternus can be swayed, I trust her judgment. When you are ready, I will see what she has to say.", ["objectivesText"] = "See what Eternus has to reveal. Progress: I am interested in learning what Eternus wishes to say.", ["rewardGold"] = 70225, ["rewardXP"] = 2380, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 207106, ["x"] = 0.655, ["y"] = 0.802 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 207106, ["x"] = 0.655, ["y"] = 0.802 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.655, ["y"] = 0.802 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5508, ["name"] = "Bronze Reconciliation", ["orderIndex"] = 1, ["flags"] = 0 } } },
[77423] = { ["id"] = 77423, ["name"] = "Surging Dreams", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77423 }, ["description"] = "Change is coming, <name>. Those attuned to the Emerald Dream can feel it on the wind. We need your aid in uncovering what this change entails. Let us reconvene in the affected area and formulate a plan.", ["objectivesText"] = "Meet the druids investigating the Dreamsurge.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 211031, ["x"] = 0.5055, ["y"] = 0.5735 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 208649, ["x"] = 0.584, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.5055, ["y"] = 0.5735 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[77432] = { ["id"] = 77432, ["name"] = "Pedgi the Parched", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 77432 }, ["description"] = "Pedgi's being dramatic. Again. I know it seems childish, and that's because it is childish, but he responds well to little treats when he's in a mood. Could you get him a coffee from the bar downstairs?", ["objectivesText"] = "Get Pedgi a drink from the inn's bartender. Progress: Pedgi's treat should get him to stop moping. By the titans, I can't believe I had to say that...", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 206520, 206521, 206523, 206524 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204990, ["x"] = 0.538, ["y"] = 0.8416 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204990, ["x"] = 0.538, ["y"] = 0.8416 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.8416 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[77433] = { ["id"] = 77433, ["name"] = "Excavation: Riverbed", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "There's a Riverbed near Maruukai in Ohn'ahran Plains that's teeming with local lore about a lost caravan! Meet me there as quick as you can! And wear your best, old, mud-ready boots!", ["objectivesText"] = "Meet Roska Rocktooth at the Riverbed dig site in Ohn'ahran Plains.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208614, ["x"] = 0.615, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 204094, ["x"] = 0.674, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 2023, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5468, ["name"] = "Azerothian Archives - Excavation Sites", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 7, ["flags"] = 0 } } },
[77434] = { ["id"] = 77434, ["name"] = "Technoscrying: Observatory", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "My dowsing rods have been pointing towards a set of Drakonid ruins atop a cliff in Waking Shores. I know not what we'll find, but it's never wise to question the whims of my inventions. They're always 97% correct. Always.", ["objectivesText"] = "Meet Zenata at the Concord Observatory in Waking Shores.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 202247 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208355, ["x"] = 0.616, ["y"] = 0.305333 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 204835, ["x"] = 0.564, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.305333 }, ["mapCandidates"] = { ["npc"] = { 2022, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 5469, ["name"] = "Azerothian Archives - Technoscrying Sites", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 11, ["flags"] = 0 } } },
[77436] = { ["id"] = 77436, ["name"] = "The Burning Barrow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76433, 76434, 76435, 76437, 76441, 76442, 76443, 77436 }, ["description"] = "Fyrakk's forces have already set their plans in motion. We are one step behind, and we need to catch up quickly if we are to properly protect Amirdrassil. While you were on your way here, we received word of suspicious-looking figures entering one of the nearby barrow dens. Tyrande already went to investigate. Seek her out and lend her your aid.", ["objectivesText"] = "Find Tyrande near the Sor'theril Barrow Den.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206896, ["x"] = 0.508, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206247, ["x"] = 0.514, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5471, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5471, ["name"] = "Druids of the Flame", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 18, ["flags"] = 0 } } },
[77437] = { ["id"] = 77437, ["name"] = "Eon's Fringe", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77437 }, ["description"] = "Timewalker Tempo and their team finally unfroze Eon's Fringe! Er... mostly. The Timewalkers have things more or less under control but Eon's Fringe has some problems the people of the town wouldn't mind a hand with. Tell Bob I sent ya!", ["objectivesText"] = "Find Bartender Bob in Eon's Fringe.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 209020, ["x"] = 0.789, ["y"] = 0.446 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 203769, ["x"] = 0.522, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.789, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[77484] = { ["id"] = 77484, ["name"] = "Technoscrying: Igira's Watch", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Of all places, my sensors are indicating a site of interest beneath the surface in Zaralek Cavern. Best bring a weapon for this excursion. My preliminary scouting indicated a elevated presence of both lava and djaradin.", ["objectivesText"] = "Meet Zenata at Igira's Watch in Zaralek Cavern.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 208084 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208355, ["x"] = 0.616, ["y"] = 0.305333 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 207763, ["x"] = 0.382, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.305333 }, ["mapCandidates"] = { ["npc"] = { 2025, 2133 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5469, ["name"] = "Azerothian Archives - Technoscrying Sites", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 37, ["flags"] = 0 } } },
[77486] = { ["id"] = 77486, ["name"] = "Excavation: Gaze of Neltharion", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "A Niffen colleague of mine gave me the underground info about an underground tower. It's decrepit and smack-dab in the middle of Zaralek between Loamm, the Djaradin, and that ghastly lab of Neltharion's. Grab your favorite shovel and meet me there!", ["objectivesText"] = "Meet Roska Rocktooth at the Gaze of Neltharion in Zaralek Cavern.", ["rewardGold"] = 34100, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208614, ["x"] = 0.615, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 205413, ["x"] = 0.486, ["y"] = 0.484 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 2025, 2133 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133, ["questLines"] = { { ["id"] = 5468, ["name"] = "Azerothian Archives - Excavation Sites", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 22, ["flags"] = 0 } } },
[77488] = { ["id"] = 77488, ["name"] = "Excavation: Back to Eadweard!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 76026, 76032, 77100, 77151, 77154, 77433, 77486, 77487, 77488 }, ["description"] = "Great job, <name>! We've got plenty of history to report back to Eadweard with. Let's meet back at the Academy!", ["objectivesText"] = "Meet Eadweard Dalyngrigge at the Algeth'ar Academy in Thaldraszus.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5468, ["name"] = "Azerothian Archives - Excavation Sites", ["orderIndex"] = 12, ["flags"] = 0 } } },
