[77762] = { ["id"] = 77762, ["name"] = "A Little Hope is Never Without Worth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77677, 77697, 77711, 77762, 78398 }, ["description"] = "The plant has matured and is thriving. And with this little corner of our ecosystem restored, we've seen something I've been wishing for since I learned what you were up to: the dreamtalons have returned with their kits! One of the grateful mature dreamtalons has offered their services to you, if you wish it.", ["objectivesText"] = "Speak to Professor Ash .", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 208067, 210774, 211131 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208337, ["x"] = 0.496, ["y"] = 0.628 }, { ["mapID"] = 2200, ["npcID"] = 209571, ["x"] = 0.486, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 209571, ["x"] = 0.486, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5477, ["name"] = "A Mix of Hope, Care, and Patience", ["orderIndex"] = 4, ["flags"] = 0 } } },
