[77766] = { ["id"] = 77766, ["name"] = "Curious Find: Hole-Punched Bakar Tooth", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2025, ["storyline"] = { 77766 }, ["description"] = "<This milk-tooth came from a young bakar, though the way the bone has yellowed suggests it's thousands of years old. Someone has carefully drilled a hole at the top of this tooth to turn it into a bead. Upon closer examination, the tattered remains of a woolen cord can still be seen threaded through it. Eadweard would know how to preserve this find and figure out whom it might belong to.>", ["objectivesText"] = "Bring the Hole-Punched Bakar Tooth to Eadweard Dalyngrigge at the Algeth'ar Academy in Thaldraszus.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 208737, 212692, 213176, 213177, 213185 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["startItems"] = { 208737 } },
