[77978] = { ["id"] = 77978, ["name"] = "A Passed Torch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77978 }, ["description"] = "<Strategic documents are scattered around Lyandris. Notes detailing experiments and future assault locations covering many of them.> <It would be of great use to your allies to find more of these documents. Thinning out the Flame's numbers wouldn't hurt either.>", ["objectivesText"] = "Collect documents and kill Druids of the Flame within the Smoldering Copse. Progress: What is it?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 209048, 210921 }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210196, ["x"] = 0.512, ["y"] = 0.635333 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.635333 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
