[78153] = { ["id"] = 78153, ["name"] = "Handling It: Prototype Rune", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 77835, 78003, 78153, 78154 }, ["description"] = "Ah, I see! We're in uncharted territory here, but I've got a plan. You'll need some Cosmic Ink, Runed Writhebark, and Shadowflame Essence. Sharing this recipe with a friendly scribe should allow them to complete a Crafting Order for you. Let me update my notes with a recipe for the Rune of Shadowbinding.", ["objectivesText"] = "Craft or obtain Lydiara's Binding Rune . Progress: Is it ready? Shall we proceed?", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 194754, 194862, 204464, 209349, 209998 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194840, ["x"] = 0.402, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194840, ["x"] = 0.402, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5485, ["name"] = "Rune of Shadowbinding", ["orderIndex"] = 2, ["flags"] = 0 } } },
[78154] = { ["id"] = 78154, ["name"] = "To the Test: Rune of Shadowbinding", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 77835, 78003, 78153, 78154 }, ["description"] = "We need to finalize the binding. We can attune the components properly by testing them in combat against Fyrakk's most powerful lieutenants. Then we can bind the attuned materials to Fyr'alath. If you can defeat Gnarlroot, Igira the Cruel, and Volcoross while this rune is bound to them, you'll be ready to fully attune the Rune of Shadowbinding.", ["objectivesText"] = "Defeat Gnarlroot, Igira the Cruel, and Volocross in Amirdrassil, the Dream's Hope. Progress: A hero never backs down from a challenge. You've got this.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 209999, 211397 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194840, ["x"] = 0.402, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194840, ["x"] = 0.402, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5485, ["name"] = "Rune of Shadowbinding", ["orderIndex"] = 3, ["flags"] = 0 } } },
[78155] = { ["id"] = 78155, ["name"] = "Handling It: Radiant Fleck of Ash", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 77833, 78002, 78155, 78156 }, ["description"] = "I've heard that in the Emerald Dream, a coarse ash with strong properties of shadowflame tends to cling to powerful pieces of equipment. The only way to harvest that powerful dust is by disassembling the equipment. Here, use this rod I've enchanted. It should allow you to siphon off the dust you need.", ["objectivesText"] = "Collect Radiant Flecks of Ash from powerful pieces of gear throughout the Emerald Dream. Progress: Don't give up! This process doesn't just help with crafting. It builds character! Remember that!", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 208581, 210001, 210002 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194837, ["x"] = 0.624, ["y"] = 0.186 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194837, ["x"] = 0.624, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5484, ["name"] = "Concentrated Sophic Vellum", ["orderIndex"] = 1, ["flags"] = 0 } } },
[78156] = { ["id"] = 78156, ["name"] = "Handling It: Radiant Vellum", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 77833, 78002, 78155, 78156 }, ["description"] = "We can refine my creation by embedding the enchantment with Order magic. Here are my notes on Concentrated Sophic Vellum. Sharing this with another friendly enchanter should give them enough info to complete a Crafting Order for you.", ["objectivesText"] = "Craft or obtain Shalasar's Sophic Vellum . Progress: I've seen students become... disenchanted... with this type of task, but I know you're made of sterner stuff. Sorry. I've been in isolation for a long time, and I don't get to use that \"joke\" very often.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 109599, 158380, 208846, 210003, 210011 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194837, ["x"] = 0.624, ["y"] = 0.186 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194837, ["x"] = 0.624, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5484, ["name"] = "Concentrated Sophic Vellum", ["orderIndex"] = 2, ["flags"] = 0 } } },
[78159] = { ["id"] = 78159, ["name"] = "Handling It: Glowspore Grip", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 77791, 77886, 78159, 78160, 78655 }, ["description"] = "To craft something workable, we'll need a substantial amount of Zaralek Glowspores and some leather. Here are my notes on the Symbiotic Glowspore Grip. Sharing this with a friendly leatherworker should give them enough info to complete a Crafting Order for you.", ["objectivesText"] = "Craft or obtain Erden 's Glowspore Grip. Progress: Tracking this down is a lot of work, but the quarry is worth the hunt.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 209351, 210010 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194842, ["x"] = 0.824, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194842, ["x"] = 0.824, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.824, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5483, ["name"] = "Symbiotic Glowspore Grip", ["orderIndex"] = 2, ["flags"] = 0 } } },
[78160] = { ["id"] = 78160, ["name"] = "To the Test: Symbiotic Glowspore Grip", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 77791, 77886, 78159, 78160, 78655 }, ["description"] = "You will have to trust me. We need to activate the reagents embedded in the grip. Wrapping the grip around Fyr'alath's haft should work, as long as you can survive the onslaught that follows. You're going to need to make adjustments as you go, and you won't get it the first time. The spores need to adapt to the axe.", ["objectivesText"] = "Empower the grip while surviving its union with Fyr'alath. Progress: Keep at it. All this hard work is going to pay off.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 205025, 207174, 207528, 210012, 210207, 211396 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194842, ["x"] = 0.824, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194842, ["x"] = 0.824, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.824, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5483, ["name"] = "Symbiotic Glowspore Grip", ["orderIndex"] = 3, ["flags"] = 0 } } },
[78162] = { ["id"] = 78162, ["name"] = "Q'onzu's Distraction", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78162 }, ["description"] = "Truly your questions are important to me. Alas, I am simply too distracted. These podlings--nasty little ones. I'm sure you've seen them. They're encroaching upon my nest and just a total nuisance. Bothering myself and my friends? The nerve! Here's my feather. Why don't you go change these nuisances into something less bothersome.", ["objectivesText"] = "Weaken 8 podlings, then use Q'onzu's Faerie Feather to change them into Faerie Dragons. Progress: I can still hear the annoying sounds of those podlings. It's torture.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 137663, 208775, 210227, 210645 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210524, ["x"] = 0.346, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210524, ["x"] = 0.346, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78163] = { ["id"] = 78163, ["name"] = "Q'onzu's Qualification", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78163 }, ["description"] = "You seek an audience with Q'onzu but bring no offerings? One does not just walk up and speak to the loa of Change, I'm afraid. You must first prove you are worth their time. The friends of Q'onzu have been granted one hundred questions by the loa themself! You must prove your wit and answer each of them true. Return to me if you answer all one hundred. Then perhaps you'll earn an audience.", ["objectivesText"] = "Answer Q'onzu 's 100 questions.", ["rewardGold"] = 286500, ["rewardXP"] = 1415, ["rewardItems"] = { 137663, 208775, 210645, 211373 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210646, ["x"] = 0.348, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210524, ["x"] = 0.346, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78169] = { ["id"] = 78169, ["name"] = "LFGDungeons - Timewalking \"Heroic\" Random - 1st", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 78169 }, ["rewardXP"] = 400, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[78170] = { ["id"] = 78170, ["name"] = "Nurturing Ageless Seeds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78170 }, ["description"] = "The growth of these seeds is a delicate balance, requiring constant nurturing. I've found that Ageless Dewdrops , gathered from around this area, hold a special energy that can awaken the dormant potential within these seeds. If you could collect some dewdrops and apply them to the plants, we can unlock their full potential.", ["objectivesText"] = "Nurture each of the seed we planted with Ageless Dewdrops . Progress: Have you given the Ageless Dewdrops to the blossoming seeds?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 210050, 211406, 211410 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[78171] = { ["id"] = 78171, ["name"] = "Blossoms of the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78171 }, ["description"] = "With your help, these seeds have grown into magnificent plants. However, the most exciting part is yet to come. Each of these plant's blossoms contain a treasure trove of information about their history and the magic that binds them to the world tree. By studying these blossoms, we can better understand the lineage of each plant. Gently collect the blossoms that have fallen and return them to me.", ["objectivesText"] = "Collect 3 Dreamseed Blossoms. Progress: Have you collected the three blossoms?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 208066, 210050, 210052 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78172] = { ["id"] = 78172, ["name"] = "Mysterious Seeds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78172 }, ["description"] = "<These mysterious seeds might be of interest to Sylvia Whisperbloom .>", ["objectivesText"] = "Deliver the seeds to Sylvia Whisperbloom at the Wildling Garden. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 210050 }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["startItems"] = { 210050 } },
[78177] = { ["id"] = 78177, ["name"] = "To Gilneas", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 84, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "The time has come to reclaim my kingdom, champion. The Forsaken have left the land, as promised. However, in their absence it seems the Scarlet Crusade have decided to move in and use the city as their own personal stronghold. I mean to move them out. Join me in retaking Gilneas.", ["objectivesText"] = "Travel to Keel Harbor in the Ruins of Gilneas. Progress: Gilneas will be ours once more.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 54987, 54988, 54989, 54990, 55011, 62837, 62838, 62839 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 214538, ["x"] = 0.339, ["y"] = 0.155667 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.339, ["y"] = 0.155667 }, ["mapCandidates"] = { ["npc"] = { 21, 84 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 1, ["flags"] = 0 } } },
[78178] = { ["id"] = 78178, ["name"] = "To Gilneas", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78178, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78597, 79137 }, ["description"] = "<name>, we've received word of an offensive occurring soon in Gilneas. We have been working with the Alliance to return Gilneas to the Gilneans. Unfortunately, the Scarlet Crusade have taken up residence in the city. We wish to provide assistance in purging the Scarlet's and return the Gilneans lands to them. Lilian and I want you to join us in this operation.", ["objectivesText"] = "Travel to Gilneas in Eastern Kingdoms to assist with retaking Gilneas City for the Gilneans. Progress: Thank you for coming to help, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 54987, 54988, 54989, 54990, 55011, 62837, 62838, 62839 }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210965, ["x"] = 0.428, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 0, ["flags"] = 0 } } },
[78180] = { ["id"] = 78180, ["name"] = "A Crusade of Red", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "Calia will lead the Forsaken army in a distracting assault to the North. I'd like you to meet up with Lilian and me in the city. There's a secret tunnel that will give us access to the south. From there, we can open the south gate and let our forces in while the Scarlets are distracted with Calia's troops. There's a group of Scarlet Crusade currently skulking about the entrance to that secret tunnel. Care to take them out?", ["objectivesText"] = "Kill 10 Scarlet Crusade Members in Aderic's Repose. Progress: These Scarlets are a blight upon the land.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 1, ["flags"] = 0 } } },
[78181] = { ["id"] = 78181, ["name"] = "Aderic's Retort", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 217, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "The scouts report that the Scarlet Crusade at Aderic's Repose are being encouraged to tamper with the graves of my people by one Scarlet in particular. Too many Gilneans gave their lives defending this land. I will not let their sacrifice be... defiled in this manner! Take out their leader, and send them a message they won't soon forget.", ["objectivesText"] = "Slay Consecrator Hennas in Aderic's Repose. Progress: Is she dead, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 217, ["npcID"] = 210904, ["x"] = 0.5, ["y"] = 0.4424 } }, ["ends"] = { { ["mapID"] = 217, ["npcID"] = 212187, ["x"] = 0.495, ["y"] = 0.569 } }, ["coords"] = { ["mapID"] = 217, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.4424 }, ["mapCandidates"] = { ["npc"] = { 217 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 2, ["flags"] = 0 } } },
[78182] = { ["id"] = 78182, ["name"] = "Knee-High", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 217, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "Tess and Voss are waiting for you at the end of the tunnel. Once you arrive, the three of you will open the south gate from the inside, and let our forces into the city. Head through the tunnel to meet them. Take this torch, the way is infested with vermin. I'll ready our forces to storm the gate the moment it is opened.", ["objectivesText"] = "Make your way through the secret tunnel in Aderic's Repose to Gilneas City.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 217, ["npcID"] = 212187, ["x"] = 0.495, ["y"] = 0.569 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 217, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.569 }, ["mapCandidates"] = { ["npc"] = { 21, 217 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 3, ["flags"] = 0 } } },
[78183] = { ["id"] = 78183, ["name"] = "Scarlet Blood", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "Looks like they've filled the city with their most experienced forces. Don't worry, I have plenty of experience taking them down... personally. We'll whittle their numbers down one by one.", ["objectivesText"] = "Kill 12 Scarlet forces. Progress: Are you done?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210964, ["x"] = 0.426, ["y"] = 0.727 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.727 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 4, ["flags"] = 0 } } },
[78184] = { ["id"] = 78184, ["name"] = "Smokepowder and Mirrors", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "Opening the gate is all well and good, but we'll need to clear a way for our forces to advance first. Our scouts reported that the Crusade has explosives that they've stashed in the area. Surely they won't mind if we borrow some?", ["objectivesText"] = "Collect 8 Scarlet Explosives . Progress: Hmm?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 211248 }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 5, ["flags"] = 0 } } },
[78185] = { ["id"] = 78185, ["name"] = "Hounds of War", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 217, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "I think we've had enough fun on our own, yes? The Scarlets stationed near the city's chapel seem to be the most elite of their forces. I believe we'll find whoever is leading them there, but going alone is unnecessarily dangerous. Time to bring the true might of Gilneas and take our city back. My forces stand ready to charge!", ["objectivesText"] = "Open the gates to Gilneas City. Progress: My people stand ready.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 6, ["flags"] = 0 } } },
[78186] = { ["id"] = 78186, ["name"] = "Crushing the Crusade", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "The most powerful members of the Scarlet Crusade will be defending the nest of their leader, <name>. That's where I come in. Nothing like a little distraction to take an enemy down swiftly. Just let me know where and when to strike.", ["objectivesText"] = "Kill 12 Scarlet Crusade members in the Gilneas City chapel courtyard.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210964, ["x"] = 0.426, ["y"] = 0.727 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.727 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 7, ["flags"] = 0 } } },
[78187] = { ["id"] = 78187, ["name"] = "Artillerist Arsonist", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "The chapel seems to be their base, and it is well defended--they've set up multiple defenses throughout the courtyard. The troops would have an easier time sieging if we could get some of them out of the way. Remember those explosives we gathered? Now is when they come in handy.", ["objectivesText"] = "Plant 6 explosives.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 8, ["flags"] = 0 } } },
[78188] = { ["id"] = 78188, ["name"] = "Righteous Fire, Righteous Fury", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "Only one person remains standing between us and our city. Ready yourself--this won't be an easy fight.", ["objectivesText"] = "Slay the leader of the Scarlet Crusade. Progress: Is she dead?", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 9, ["flags"] = 0 } } },
[78189] = { ["id"] = 78189, ["name"] = "Beginning a New Dawn", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 217, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "Much has changed since we had to leave this city. Both the land, and my people. Bear witness, <name>, to the future of Gilneas.", ["objectivesText"] = "Listen to Genn Greymane 's conversation with Tess.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 211788, 211873 }, ["starts"] = { { ["mapID"] = 217, ["npcID"] = 210904, ["x"] = 0.5, ["y"] = 0.4424 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 217, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.4424 }, ["mapCandidates"] = { ["npc"] = { 21, 217 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 10, ["flags"] = 0 } } },
[78190] = { ["id"] = 78190, ["name"] = "What We Left Behind", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "He just... handed me the kingdom. Me! This is going to take a bit to process. But... look, <name>. I know my father's a strong man, but there are times he holds himself so rigid that I fear he'll break. I'm not about to coddle him, but if you could just follow along, make sure he's all right? Soothe a daughter's heart? A queen's heart?", ["objectivesText"] = "Follow King Greymane and keep an eye on him.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 211788, 211873 }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 217, ["npcID"] = 210904, ["x"] = 0.5, ["y"] = 0.4424 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 21, 217 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 217, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 12, ["flags"] = 0 } } },
[78203] = { ["id"] = 78203, ["name"] = "Superbloom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 78203 }, ["rewardXP"] = 2125, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924, 211389, 211411, 211413, 211414 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2VignetteID"] = 5813, ["db2VignetteName"] = "Superbloom" },
[78206] = { ["id"] = 78206, ["name"] = "Emerald Bounty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78206 }, ["description"] = "There are so many more species to locate and study. As you explore the Dream, you will find more seeds known as Dreamseeds. Please, nurture them to continue our studies, and enjoy the bounty they share with you! You will find Dreamseeds all over, but many are hoarded by powerful creatures around the Dream. Additionally, you should keep an eye out for the surge of life energy we call an Emerald Frenzy. It will be a source of many Emerald Dewdrops, which will help in nurturing Dreamseeds.", ["objectivesText"] = "Partake in the Emerald Frenzy to earn Emerald Dewdrops and contribute a Dreamseed to sprout new growths. Progress: Have you helped further our research?", ["rewardGold"] = 77400, ["rewardXP"] = 355, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924, 208047, 208066, 208067, 210050 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
