[78262] = { ["id"] = 78262, ["name"] = "It Starts With a Stone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78262 }, ["description"] = "This land holds so many secrets. And even more power! And you... we both know you enjoy unraveling secrets and collecting marvelous gear. And when you're ready to unlock the power of gear you find in this new land, come visit Cuzolth and me. We are experimenting and will be able to upgrade your gear by the time you come back. Please bring me some Flightstones and a new item so I can show you how these upgrades work.", ["objectivesText"] = "Acquire 50 Flightstones by defeating unique creatures, conquering dungeons and raids, completing world activities, or by looting caches. Then speak to Cuzolth and upgrade a piece of Season 3 equipment using Flightstones . Progress: Can you feel the power? The excitement of knowing you can now take on even more daring adventures?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211328, ["x"] = 0.498, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211328, ["x"] = 0.498, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5505, ["name"] = "10.2 Upgrade System Tutorial", ["orderIndex"] = 0, ["flags"] = 0 } } },
[78271] = { ["id"] = 78271, ["name"] = "Dreaming of Crests", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78271 }, ["description"] = "Now that you've learned the fundamentals, you can easily upgrade lower-level gear. Sooner than later, though, you will find better gear that requires various types of Dreaming Crests to upgrade. Much like Flightstones, these Crests are rewarded through many different activities. Dreaming Crests have four tiers, and more dangerous tasks reward you with higher-tier crests. Go and help with tasks, down formidable foes, find treasures, and bring me a few handfuls of Whelpling's Dreaming Crests!", ["objectivesText"] = "Acquire 15 Whelpling's Dreaming Crests by defeating unique creatures, conquering dungeons and raids, completing world activities, or by looting caches. Then speak to Vaskarn . Progress: I foresee great results with these Dreaming Crests.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 210180, 210917 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211328, ["x"] = 0.498, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211328, ["x"] = 0.498, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78272] = { ["id"] = 78272, ["name"] = "Interrupting Duck", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 9, ["storyline"] = { 78272 }, ["description"] = "There are so many bunches of baby bunnies bouncing all about! Ducks have been swarming us and we haven't been able to feed the newborns. You look like you could handle the situation--care to help?", ["objectivesText"] = "Feed carrots to 10 baby bunnies.", ["rewardItems"] = { 45072 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[78274] = { ["id"] = 78274, ["name"] = "Quacking Down", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 9, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 78274 }, ["series"] = { 79134 }, ["description"] = "Here they go again. Do you mind scaring off those ducks again? I need to stay here and keep an eye on my golden egg.", ["objectivesText"] = "Scare off 10 ducks using the Horn of Honking . Progress: Show those ducks who's boss!", ["rewardItems"] = { 45072, 210558 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3250 } },
