[78363] = { ["id"] = 78363, ["name"] = "The Tabard of Your Dreams", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78363 }, ["description"] = "< Melsysra drops a slightly damp note into your hand.> <name>, we are immensely grateful for all you've done to help us. Please meet me at Central Encampment so we can properly reward you for your efforts! - Amrymn", ["objectivesText"] = "Talk to Keeper Amrymn at the Central Encampment.", ["rewardItems"] = { 210501 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211962, ["x"] = 0.496, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208143, ["x"] = 0.502, ["y"] = 0.616 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
