[78379] = { ["id"] = 78379, ["name"] = "The Stench of Revenge", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 21, ["storyline"] = { 78379 }, ["series"] = { 78369, 78729 }, ["description"] = "We're never gonna see an end to this unless we take on the boss himself. Look, Apothecary Hummel is holed up in Shadowfang Keep with his cronies. He's working on a new batch of poisonous perfumes, and they'll knock out all of Stormwind if we let him finish his research. You go do what you do best, pal. Get in there and foil his schemes before we're all lavender-scented corpses.", ["objectivesText"] = "Speak to Snagglebolt to enter the Crown Chemical Co. battle and defeat Apothecary Hummel . Progress: You ready to see what Hummel is cooking? I guarantee you it's not as pretty as it smells.", ["rewardGold"] = 1123600, ["rewardXP"] = 400, ["rewardItems"] = { 49927 }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 38066, ["x"] = 0.458, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 38066, ["x"] = 0.458, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 1519 } }, ["questType"] = "dungeon", ["db2LabelIDs"] = { 3027 } },
[78381] = { ["id"] = 78381, ["name"] = "Dreams Unified", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78381 }, ["description"] = "Another incredible find, <name>! This half of a Spark of Dreams could prove useful in your crafting endeavors if you could unite it with a sister piece. Set out in search of another Splintered Spark of Dreams and combine them.", ["objectivesText"] = "Find another Splintered Spark of Dreams . Progress: Have you located another Splintered Spark of Dreams ?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 206271, 208396, 210872 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208669, ["x"] = 0.498, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208669, ["x"] = 0.498, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5510, ["name"] = "Spark of Dreams", ["orderIndex"] = 0, ["flags"] = 0 } } },
