[78591] = { ["id"] = 78591, ["name"] = "Getaway to Scenic Nagrand!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 78591 }, ["description"] = "Today's special is a magical getaway to the great plains of Nagrand! If you're headed there, would you mind shooting a few animals? Oh, not like that! Here, borrow my camera. My friend Beatrice has been roaming around there lately. She would really appreciate some photographs, but I've got portals to attend to.", ["objectivesText"] = "Take the Scenic Getaway Portal to Nagrand, then take pictures of wildlife for Beatrice. Progress: There are so many places in Azeroth to escape to! Everywhere you look, there's something new to discover.", ["rewardGold"] = 286500, ["rewardXP"] = 1415, ["rewardItems"] = { 49927, 122637, 210743 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 212677, ["x"] = 0.342, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 212677, ["x"] = 0.342, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78594] = { ["id"] = 78594, ["name"] = "Getaway to Scenic Feralas!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 78594 }, ["description"] = "Today's special is a magical getaway to the sunny beaches of Feralas! The Steam Pools resort is having a lovely celebration and all are invited! Unfortunately, some of the partygoers who took this portal earlier left their gifts here at the gala. Could you help me return them? Meet me at the beach and we'll figure out which gifts belong to whom.", ["objectivesText"] = "Take the Scenic Getaway Portal to Feralas, then deliver the lost gifts to the correct recipients. Progress: There are so many places in Azeroth to escape to! Everywhere you look, there's something new to discover.", ["rewardGold"] = 89550, ["rewardXP"] = 1415, ["rewardItems"] = { 49927, 211922, 211923 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 212677, ["x"] = 0.342, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 212677, ["x"] = 0.342, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78595] = { ["id"] = 78595, ["name"] = "Dream Infused", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78595 }, ["description"] = "< Melsysra drops a slightly damp note into your hand.> <name>, your deeds have helped garner enough strength for a dream infusion ! Meet me at the Central Encampment so I can get it to you. - Elianna", ["objectivesText"] = "Talk to Elianna in the Central Encampment.", ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211962, ["x"] = 0.496, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211209, ["x"] = 0.502, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
