= 2112, ["questLines"] = { { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 68, ["flags"] = 0 } } },
[78646] = { ["id"] = 78646, ["name"] = "Fire Watch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "My mother seems unable to fully attune with the Eye. Perhaps it senses her ties to Ardenweald... Her shield is but a fraction of the Eye's power. If she was fully attuned, she could completely quench our foes' flames. But we cannot idly wait. We still need more information about Galok and his plan of attack. Bodwin indicates there is new flurry of activity in Igira's base of operations. With Bodwin's help, we can investigate without being seen.", ["objectivesText"] = "Regroup with Merithra at the edge of Eye of Ysera, overlooking Slagfell Hold.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.5225, ["y"] = 0.2785 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 37, ["flags"] = 0 } } },
[78655] = { ["id"] = 78655, ["name"] = "Adaptive Cooling Salve", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 77791, 77886, 78159, 78160, 78655 }, ["description"] = "Should you need my assistance, I can craft you an ointment that should prove helpful in your attunement with Fyr'alath. Bring me the materials I don't have, and I'm sure I can put something together.", ["objectivesText"] = "Bring Erden Zaralek Glowspores , Awakened Frost , and a Dreaming Essence for the Adaptive Cooling Salve . Progress: Keep at it. All this hard work is going to pay off.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 190329, 204460, 208212, 210918 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194842, ["x"] = 0.824, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194842, ["x"] = 0.824, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.824, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5483, ["name"] = "Symbiotic Glowspore Grip", ["orderIndex"] = 4, ["flags"] = 0 } } },
[78664] = { ["id"] = 78664, ["name"] = "The Gift of Self-Care", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 78664 }, ["description"] = "The eyes of a tired adventurer. A <class> that does many great deeds for many people. When was the last time you did a kind gesture for yourself? Perhaps now is the time. Look into your heart. What do YOU desire?", ["objectivesText"] = "Speak with Ying to discover your heart's desire. Progress: Love is a blessing, especially if it comes from within.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 213262, ["x"] = 0.35, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 213262, ["x"] = 0.35, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard" },
[78674] = { ["id"] = 78674, ["name"] = "The Gift of Relief", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 78674 }, ["description"] = "You adventurers are known to carry heavy burdens. There will be no better time to confront them than now. I saw a veteran somewhere around here. There is a chance he may know what it means to cope with stress. Perhaps he has insight to teach you.", ["objectivesText"] = "Speak to Simeon Griswold at the Gala of Gifts, then relieve your stress in Old Town. Progress: I've seen men die of stress. You don't want to bottle it up every day.", ["rewardGold"] = 331700, ["rewardXP"] = 1415, ["rewardItems"] = { 49927, 207793 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 213262, ["x"] = 0.35, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 213294, ["x"] = 0.338, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78724] = { ["id"] = 78724, ["name"] = "Loving Yourself, Your Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 78724 }, ["description"] = "If it's a challenge you're after, I think I have an idea. I saw a boastful champion heading toward Goldshire. You could challenge him to a duel. This would satisfy your desire and perhaps teach him a valuable lesson in humility.", ["objectivesText"] = "Defeat Matley Graston in a duel near Goldshire. Progress: How fares your challenge?", ["rewardGold"] = 89550, ["rewardXP"] = 1415, ["rewardItems"] = { 49927 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 213262, ["x"] = 0.35, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 213262, ["x"] = 0.35, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78726] = { ["id"] = 78726, ["name"] = "Loving Yourself, Your Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 78726 }, ["description"] = "A full belly is a happy belly! There is plenty of good food and drink right here at the gala. Why don't you buy yourself something nice?", ["objectivesText"] = "Consume treat packages from vendors at the Gala of Gifts. Progress: Have you had your fill of treats? I love the fruits, myself.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 49927, 210926, 210928, 210929, 239015 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 213262, ["x"] = 0.35, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 213262, ["x"] = 0.35, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78727] = { ["id"] = 78727, ["name"] = "Loving Yourself, Your Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 78727 }, ["description"] = "While visiting this gala, I am staying at the Lion's Pride Inn at Goldshire. I hear they have some extra beds upstairs. Why not see if you can sleep there for a while? I think I will have a bit of a rest too... Right... here...", ["objectivesText"] = "Take a nap in the upstairs guest room at the Lion's Pride Inn. Progress: < Ying is quietly snoring.>", ["rewardGold"] = 79250, ["rewardXP"] = 1415, ["rewardItems"] = { 49927 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 213262, ["x"] = 0.35, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 213262, ["x"] = 0.35, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
