[78762] = { ["id"] = 78762, ["name"] = "Your First Find", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "We've got a find on our hands! Looks like this might be one of my books from undergrad. Hah! Now, your job is to get all that dirt off of it, but you have to be careful. The artifacts we handle are very fragile, and the only thing worse than them staying in the ground is them breaking on the way out. Empowering your elemental will only get you halfway. You'll need to use your environment to keep things in balance so that it's safe to excavate.", ["objectivesText"] = "Practice excavating on the Outdated Geology Textbook . Progress: What do you think? Having fun yet?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 210956 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208614, ["x"] = 0.615, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208614, ["x"] = 0.615, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 2, ["flags"] = 0 } } },
