[78863] = { ["id"] = 78863, ["name"] = "A Place Beneath the Boughs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 78863 }, ["description"] = "Thanks to you and all the mortals who defended the Emerald Dream, a new World Tree now grows in the Dragon Isles. Amirdrassil 's boughs will be a haven of peace and tranquility, and a place of respite for the kaldorei souls lost at Teldrassil. Tyrande Whisperwind and Shandris Feathermoon are at the tree now. They would share words with you.", ["objectivesText"] = "Meet Tyrande and Shandris in Amirdrassil .", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 212981, 213003, 213004, 213005, 213006, 213007, 213008, 213009, 213010, 213011, 213012, 213013, 213160 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 216067, ["x"] = 0.512667, ["y"] = 0.606667 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.583778, ["y"] = 0.357111 }, ["mapCandidates"] = { ["npc"] = { 2112, 2239 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
