[79130] = { ["id"] = 79130, ["name"] = "The Northrend Cup Circuit", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 495, ["mapID"] = 2112, ["storyline"] = { 79130 }, ["series"] = { 79131, 79132, 79133 }, ["description"] = "It is time once again to test your mettle. My bronze colleagues have traveled to Northrend to create more new challenges. We would like to see if any daring skyriders will complete the entire circuit! Are you up to the task?", ["objectivesText"] = "Fly through Northrend Cup courses. Progress: Have you taken wing today?", ["rewardGold"] = 77400, ["rewardXP"] = 1030, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 206737, ["x"] = 0.27, ["y"] = 0.474 }, { ["mapID"] = 84, ["npcID"] = 214111, ["x"] = 0.6, ["y"] = 0.663 }, { ["mapID"] = 85, ["npcID"] = 214112, ["x"] = 0.524, ["y"] = 0.599 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 206737, ["x"] = 0.27, ["y"] = 0.474 }, { ["mapID"] = 84, ["npcID"] = 214111, ["x"] = 0.6, ["y"] = 0.663 }, { ["mapID"] = 85, ["npcID"] = 214112, ["x"] = 0.524, ["y"] = 0.599 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 84, 85, 2112 }, ["zone"] = { 495 } }, ["questType"] = "standard" },
