[79134] = { ["id"] = 79134, ["name"] = "A Spring Awakening", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 9, ["zoneID"] = 15969, ["mapID"] = 2112, ["storyline"] = { 79134 }, ["series"] = { 78274 }, ["description"] = "The citizens of Goldshire have reported frequent interruptions to their recent festivities. Something about being overrun by angry... ducks? Perhaps you could look further into this conundrum.", ["objectivesText"] = "Speak with Zinnia Brooks at Goldshire in Elwynn Forest.", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199261, ["x"] = 0.390667, ["y"] = 0.61 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.390667, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 37, 2112, 2339 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[79135] = { ["id"] = 79135, ["name"] = "Quacking Down", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 79135 }, ["series"] = { 79136 }, ["description"] = "Those dratted ducks! Do you mind scaring them off again? I simply cannot leave my golden egg unattended!", ["objectivesText"] = "Scare off 10 ducks using the Horn of Honking . Progress: Have you sufficiently shooed those ducks yet?", ["rewardItems"] = { 45072, 216487 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3250 } },
[79136] = { ["id"] = 79136, ["name"] = "A Spring Awakening", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 9, ["zoneID"] = 15969, ["mapID"] = 2112, ["storyline"] = { 79136 }, ["series"] = { 79135 }, ["description"] = "The citizens of Razor Hill have reported frequent interruptions to their recent festivities due to a duck infestation, of all things. Perhaps you could look further into this conundrum.", ["objectivesText"] = "Talk to Sylnaria Fareflame in Razor Hill.", ["rewardGold"] = 34100, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199261, ["x"] = 0.390667, ["y"] = 0.61 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.390667, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 1, 2112, 2339 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[79137] = { ["id"] = 79137, ["name"] = "The Wall Between Us", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78178, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78597, 79137 }, ["description"] = "I know this fight was not ours, <name>. But I thank you for your assistance. It was with the Alliance's assistance that Lordaeron was cleansed and the favor has now been returned. I do not think I can hope for peace. Instead, I will hope that these efforts have led to at least an understanding of the plights of both Gilneans and the Forsaken. Let us meet with Lilian in Pyrewood Village. This celebration is not for us.", ["objectivesText"] = "Speak with Lilian and Calia in Pyrewood Village.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 211788, 211873 }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210965, ["x"] = 0.428, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210964, ["x"] = 0.426, ["y"] = 0.727 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 21, ["questLines"] = { { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 12, ["flags"] = 0 } } },
[79178] = { ["id"] = 79178, ["name"] = "Play Hearthstone!", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 1, ["storyline"] = { 79178 }, ["description"] = "It's time to play Hearthstone! Here's a starter pack -- open it up and add those cards to you collection. Then, if you can find a seat at the game table, then sit down with someone else and play! Or if you can't find a seat, then you'll want some Wild cards.... I didn't tell you this but there's a shady card dealer lurking around here somewhere.", ["objectivesText"] = "Play 5 Hearthstone cards at a Hearthstone Game Table, or Wild Cards NEAR a Hearthstone Game Table. Progress: Like the game so far? Give it a chance and play those cards!", ["rewardGold"] = 31500, ["rewardItems"] = { 211965, 212979 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 215409, ["x"] = 0.53, ["y"] = 0.152 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 215409, ["x"] = 0.53, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[79184] = { ["id"] = 79184, ["name"] = "It's Hearthstone's Anniversary!", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 79184 }, ["description"] = "\"Hearthstone's been played for ten years, can you believe it? I'm hosting Hearthstone games in Valdrakken, way up in the Seat of the Aspects. Come join us! -Farala, Master of Ceremonies\"", ["objectivesText"] = "Speak with M.C. Farala in Valdrakken, in the Seat of the Aspects.", ["rewardGold"] = 33500, ["rewardItems"] = { 212154 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 215409, ["x"] = 0.53, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
[79186] = { ["id"] = 79186, ["name"] = "It's Hearthstone's Anniversary!", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["storyline"] = { 79186 }, ["description"] = "Hearthstone's been played for ten years, can you believe it? Farala, Master of Ceremonies, is hosting Hearthstone games at the Stormwind Harbor. Come join in the celebration!", ["objectivesText"] = "Speak with M.C. Farala in Stormwind.", ["rewardGold"] = 30900, ["rewardItems"] = { 212155 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 212154, 212155 } },
[79189] = { ["id"] = 79189, ["name"] = "It's Hearthstone's Anniversary!", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["storyline"] = { 79189 }, ["description"] = "\"Hearthstone's been played for ten years, can you believe it? Farala, Master of Ceremonies, is hosting Hearthstone games in Durotar, between Orgrimmar and the docks. Come join in the celebration!", ["objectivesText"] = "Speak with M.C. Farala in Durotar.", ["rewardGold"] = 28090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 231019 } },
[79199] = { ["id"] = 79199, ["name"] = "Renowned with Keg Leg's Crew", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = { "emissary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 79199 }, ["description"] = "Your deeds have not gone unnoticed, and you continue to show that you are a renowned explorer! Return to the Dragonscale Basecamp as I have prepared more supplies to help you continue in your endeavours.", ["objectivesText"] = "Speak with Cataloger Jakes at the Dragonscale Basecamp.", ["rewardItems"] = { 204378 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[79223] = { ["id"] = 79223, ["name"] = "Finally, An Archivist!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "So you've got your bearings now? You've felt the dirt? You've smelled the history? Why not celebrate this glorious moment of above average success with... a cap! That's right! Take this token to our beloved provisioner, Aristta. She'll be happy to provide you with one of our all-purpose caps to signify your elevation to Archivist from naive passerby.", ["objectivesText"] = "Purchase an Archivist's Buckled Cap from Provisioner Aristta. Progress: The cap suits you quite well!", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 212371 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 20, ["flags"] = 0 } } },
[79226] = { ["id"] = 79226, ["name"] = "The Big Dig: Traitor's Rest", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13844, ["mapID"] = 2025, ["storyline"] = { 79226 }, ["description"] = "Don your cap, put on a pair of sturdy gloves, and grab a snack because Traitor's Rest is ready for Archivists everywhere to sink their history-craving teeth into!", ["objectivesText"] = "Aid Eadweard Dalyngrigge and the Azerothian Archivists at The Big Dig in Traitor's Rest. Progress: Not every day you unearth ancient dragon mysteries... or even a dragon themselves!", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["rewardItems"] = { 213134, 213177, 213190, 213429 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 }, { ["mapID"] = 2024, ["npcID"] = 209134, ["x"] = 0.27, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 }, { ["mapID"] = 2024, ["npcID"] = 209134, ["x"] = 0.27, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13844 } }, ["questType"] = "standard" },
