[80446] = { ["id"] = 80446, ["name"] = "Looking for Group", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5842, ["mapID"] = 371, ["storyline"] = { 80446 }, ["description"] = "There's my favorite champion! If you are in need of a mark to hunt, I know a few dungeons worth exploring.", ["objectivesText"] = "Defeat 3 dungeon bosses. Progress: How goes the dungeon delving?", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 211279, 223908, 223909, 223910, 223911, 226142, 226143, 226144, 226145 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 219030, ["x"] = 0.428, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 219030, ["x"] = 0.428, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5842 } }, ["questType"] = "dungeon" },
[80447] = { ["id"] = 80447, ["name"] = "Looking for More", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5842, ["mapID"] = 371, ["storyline"] = { 80447 }, ["description"] = "You think you're tough? I'll believe it when you take on a real challenge. Defeat the most powerful foes on Pandaria and we'll see how tough you really are.", ["objectivesText"] = "Defeat 2 raid bosses. Progress: The real challenge is finding enough other puny elf to team up with.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 211279, 223908, 223909, 223910, 223911, 226142, 226143, 226144, 226145 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 219027, ["x"] = 0.428, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 219027, ["x"] = 0.428, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5842 } }, ["questType"] = "raid" },
[80448] = { ["id"] = 80448, ["name"] = "A Fresh Scene", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5841, ["mapID"] = 371, ["storyline"] = { 80448 }, ["description"] = "Uh-uh honey, I'm not gonna let you spend all day in stuffy dungeons where no one can see your getup! Put on your going-out look and let's get you somewhere fresh!", ["objectivesText"] = "Complete a scenario. Progress: You wouldn't catch me dead in a dungeon, nuh-uh. You know what's down there? Mud! Cobwebs! People wearing those shoulderpads way too big for 'em. No sir, I'll stay right here, thank you.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 94221, 211279, 223908, 223909, 223910, 223911, 226142, 226143, 226144, 226145 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 219025, ["x"] = 0.428, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 219025, ["x"] = 0.428, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[81564] = { ["id"] = 81564, ["name"] = "The Story of Noodles", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 81564 }, ["description"] = "Ah, being here again makes me hungry. Have I ever told you about the time I learned to cook from Sungshin Ironpaw? Perhaps you can experience it for yourself. Say the word and I will take you to a version of this timeline where you--yes YOU--ran your own noodle stand! It all began with the Lin family's secret recipe...", ["objectivesText"] = "Talk to Grandmaster Jakkus to complete the scenario Finding the Secret Ingredient. Progress: Mmm, noodles...", ["rewardGold"] = 625600, ["rewardXP"] = 5990, ["rewardItems"] = { 211279 }, ["starts"] = { { ["mapID"] = 376, ["npcID"] = 220895, ["x"] = 0.532, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 376, ["npcID"] = 220895, ["x"] = 0.532, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 376, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 376 }, ["zone"] = { 5805 } }, ["questType"] = "standard" },
