[82229] = { ["id"] = 82229, ["name"] = "An Uncommon Request", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 80069, 80071, 80072, 80073, 80075, 80077, 82229 }, ["description"] = "<name>, welcome to Bel'ameth. I wonder -- do you have time for a small favor? Earlier today, a young kaldorei named Kelestra came to see me. She sought permission to bury her family in a barrow den. An uncommon request, but I gave her my blessing and directed her to the Barrows of Reverie. She looked... melancholy. After she left, it struck me that she might be the last of her family still alive. If you have the time, could you check on her?", ["objectivesText"] = "Meet Kelestra in the Barrows of Reverie.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 223146 }, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 216069, ["x"] = 0.4925, ["y"] = 0.6815 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 218623, ["x"] = 0.7255, ["y"] = 0.7305 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.4925, ["y"] = 0.6815 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239, ["questLines"] = { { ["id"] = 5547, ["name"] = "Sins of the Sister", ["orderIndex"] = 0, ["flags"] = 0 } } },
